        ["I've heard there's a penguin located where the Fremennik 'heim' and seek"] = "He oído que hay un pingüino ubicado donde el Fremennik 'heim' y busca",
        ["I've heard there's a penguin located where the Imperial Guard train"] = "He oído que hay un pingüino ubicado donde entrena la Guardia Imperial.",
        ["I've heard there's a penguin located where wizards study"] = "He oído que hay un pingüino ubicado donde estudian los magos.",
        ["I'm having trouble find the penguins. Can I have a hint?"] = "Tengo problemas para encontrar los pingüinos. ¿Puedo tener una pista?",
        ["Never mind."] = "No importa.",
        ["Ello, who's this?"] = "Hola, ¿quién es?",
        ["It's Player. I'm using my magic to communicate with you."] = "Soy Player. Estoy usando mi magia para comunicarme contigo.",
        ["What a waste of runes. I can see you, you know. Let's talk face to face."] = "Qué desperdicio de runas. Puedo verte, ¿sabes? Hablemos cara a cara.",
        ["A useful application of magical talent. How can I help?"] = "Una aplicación útil del talento mágico. ¿Cómo puedo ayudar?",
        ["What is this?! You must not break my concentration!"] = "¡¿Qué es esto?! ¡No debes romper mi concentración!",
        ["What a waste of runes! - I can see you, lets talk face to face."] = "¡Qué desperdicio de runas! - Puedo verte, hablemos cara a cara.",
        ["Are you trying to collapse the Abyss? What do you want? Speak quickly!"] = "¿Estás intentando colapsar el Abismo? ¿Qué deseas? ¡Habla rápido!",
        ["Actually, I can't think of anything right now..."] = "En realidad, no se me ocurre nada en este momento...",
        ["THEN STOP DISTRACTING ME!"] = "¡ENTONCES DEJA DE DISTRAERME!",
        ["Honestly, you have no idea of the pressure I am under attempting to keep this portal open!"] = "Honestamente, ¡no tienes idea de la presión que estoy bajo al intentar mantener este portal abierto!",
        ["Sorry to disturb you. I just needed your help with something quickly."] = "Lamento molestarte. Solo necesitaba tu ayuda con algo rápido.",
        ["What? Oh... Very well. what did you want?"] = "¿Qué? Ah... Muy bien. ¿Qué querías?",
        ["Chose an option:"] = "Elige una opción:",
        ["Can I have another Abyssal book?"] = "¿Puedo tener otro libro de Abyssal?",
        ["Can I have another Abyssal book? I seem to have misplaced the one I was given."] = "¿Puedo tener otro libro de Abyssal? Parece que perdí el que me dieron.",
        ["Here, take it, it is important to pool our research. Now leave me be, I must concentrate!"] = "Toma, tómatelo, es importante aunar nuestra investigación. ¡Ahora déjame en paz, debo concentrarme!",
        ["Ahh, a familiar voice in my head!"] = "¡Ahh, una voz familiar en mi cabeza!",
        ["So, where's Pikkenmix?"] = "Entonces, ¿dónde está Pikkenmix?",
        ["What's it all about?"] = "¿De qué se trata?",
        ["Hi Pauline!"] = "¡Hola Paulina!",
        ["Bah! You made me jump! I suppose you want to claim some reward wishes?"] = "¡Bah! ¡Me hiciste saltar! ¿Supongo que quieres reclamar algunos deseos de recompensa?",
        ["Yes please."] = "Sí, por favor.",
        ["What? Ah, very bright of you contacting me this way."] = "¿Qué? Ah, muy brillante que me contactes de esta manera.",
        ["Yeah, thought I'd make use of the new spell to ask a question."] = "Sí, pensé en utilizar el nuevo hechizo para hacer una pregunta.",
        ["Can you change my spell book back to the standard one?"] = "¿Puedes cambiar mi libro de hechizos al estándar?",
        ["Hmmm, no I think you need to prove yourself a bit more first."] = "Hmmm, no, creo que primero debes demostrar tu valía un poco más.",
        ["If you complete the elite achievement diary tasks the Oneiromancer will help you."] = "Si completas las tareas del diario de logros de élite, Oneiromancer te ayudará.",
        ["Certainly..."] = "Ciertamente...",
        ["There!"] = "¡Ahí!",
        ["Can I tell you a joke?"] = "¿Puedo contarte un chiste?",
        ["Oh, I do like jokes, go ahead."] = "Oh, me gustan las bromas, adelante.",
        ["What do you call a crazy moon?"] = "¿Cómo se llama una luna loca?",
        ["A crazy moon... Hmm, I don't know. What?"] = "Una luna loca... Hmm, no lo sé. ¿Qué?",
        ["A luna-tic!"] = "¡Un lunático!",
        ["Ahahahaha!"] = "¡Jajajajaja!",
        ["Hahaa!"] = "¡Jajaa!",
        ["Hahahaha!"] = "¡Jajajaja!",
        ["Okay, okay. It wasn't THAT funny."] = "Está bien, está bien. No fue TAN gracioso.",
        ["Mieliki sent Nyriki to a swamp, south-east of Canifis."] = "Mieliki envió a Nyriki a un pantano, al sureste de Canifis.",
        ["What would you like to say?"] = "¿Qué te gustaría decir?",
        ["Who are you?"] = "¿Quién eres?",
        ["Mieliki is an alchemist. Mieliki's stupid husband Nyriki hunts for giant chinchompas to get chemicals for Mieliki."] = "Mieliki es un alquimista. El estúpido marido de Mieliki, Nyriki, busca chinchompas gigantes para conseguir productos químicos para Mieliki.",
        ["Nyriki needs human help because he is stupid. Use Mieliki portal, in this shop, to go to him now."] = "Nyriki necesita ayuda humana porque es estúpido. Utilice el portal Mieliki, en esta tienda, para acudir a él ahora.",
        ["Can you teleport me?"] = "¿Puedes teletransportarme?",
        ["Mieliki is working! Use the portal."] = "¡Mieliki está trabajando! Utilice el portal.",
        ["Mieliki is working! Come to Mieliki's shop in the Gnome Stronghold and use the portal."] = "¡Mieliki está trabajando! Ven a la tienda de Mieliki en Gnome Stronghold y utiliza el portal.",
        ["Thanks."] = "Gracias.",
        ["Very well, human. Work hard."] = "Muy bien, humano. Atarearse.",
        ["If you're going to bother me with your prattle, you could at least have the decency to do it to my face. Get over here."] = "Si vas a molestarme con tu parloteo, al menos podrías tener la decencia de hacerlo en mi cara. Ven aquí.",
        ["You have no business in my head. My secrets are not for your eyes. Get out."] = "No tienes nada que hacer en mi cabeza. Mis secretos no son para tus ojos. Salir.",
        ["Too scared to seek me out in person, hmm? Well, what is it?"] = "Tienes demasiado miedo para buscarme en persona, ¿eh? Bueno, ¿qué es?",
        ["Why would you waste the runes to contact me when you're standing so close?"] = "¿Por qué desperdiciarías las runas para contactarme cuando estás tan cerca?",
        ["You have no business in my head. My thoughts are my own."] = "No tienes nada que hacer en mi cabeza. Mis pensamientos son míos.",
        ["That's a shame. It'd have been nice to see you. Well, what is it?"] = "Es una pena. Hubiera sido bueno verte. Bueno, ¿qué es?",
        ["Ugh, another one."] = "Uf, otro.",
        ["What?"] = "¿Qué?",
        ["Oh nothing. What can I help with?"] = "Oh, nada. ¿En qué puedo ayudar?",
        ["Oh, well, someone said something about some druids in the desert, and rather than go there I figured I'd see what was going on first."] = "Oh, bueno, alguien dijo algo sobre unos druidas en el desierto, y en lugar de ir allí pensé en ver qué estaba pasando primero.",
        ["Look, if you want to help, maybe come and have a chat rather than pushing your way into my head."] = "Mira, si quieres ayudar, tal vez vengas y conversemos en lugar de meterte en mi cabeza.",
        ["Well I did-"] = "Bueno, lo hice-",
        ["Good day!"] = "¡Buenos días!",
        ["Helloooo?"] = "¿Holaaaa?",
        ["There is no one there but the cold, dark void of your own mind."] = "No hay nadie allí excepto el vacío frío y oscuro de tu propia mente.",
        ["Hello, Polletix?"] = "Hola, ¿Polletix?",
        ["What are you doing?"] = "¿Qué estás haciendo?",
        ["Well I was jus-"] = "Bueno, solo estaba-",
        ["I can see you. You're right here."] = "Puedo verte. Estás justo aquí.",
        ["Oh, I-"] = "Oh, yo-",
        ["Now, if you want to talk I suggest you come and do so in person, rather than this misuse of magic."] = "Ahora, si quieres hablar te sugiero que vengas y lo hagas en persona, en lugar de este mal uso de la magia.",
        ["Hello adventurer. This is a nifty little trick. How can I help?"] = "Hola aventurero. Este es un pequeño truco ingenioso. ¿Cómo puedo ayudar?",
        ["I was just wondering what herb you wanted planted today?"] = "Me preguntaba qué hierba querías plantar hoy.",
        ["Oh, today I'd like you to plant and harvest: [Herb type] seed."] = "Oh, hoy me gustaría que plantes y coseches: semilla [Herb type].",
        ["Great, thanks!"] = "¡Genial, gracias!",
        ["Hello? is this the Raptor?"] = "¿Hola? ¿Es este the Raptor?",
        ["**The Raptor** You have no business in my head. My thoughts are my own."] = "**The Raptor** No tienes nada que hacer en mi cabeza. Mis pensamientos son míos.",
        ["**The Raptor** Explain yourself."] = "**The Raptor** Explícate.",
        ["Huh? Okay."] = "¿Eh? Bueno.",
        ["Baa, baaaa, BAA!"] = "¡Baa, baaaa, BAA!",
        ["Baaa?"] = "¿Baaa?",
        ["What? Who's that?"] = "¿Qué? ¿Quién es ese?",
        ["Hehe...ahem..."] = "Jeje... ejem...",
        ["This is the voice of your conscience! You've been a very naughty boy, haven't you?"] = "¡Esta es la voz de tu conciencia! Has sido un chico muy travieso, ¿no?",
        ["What? No I haven't!"] = "¿Qué? ¡No, no lo he hecho!",
        ["You know what I'm talking about! Don't lie!"] = "¡Sabes de lo que estoy hablando! ¡No mientas!",
        ["Okay, okay! I'm sorry, I'll never do it again."] = "¡Está bien, está bien! Lo siento, no lo volveré a hacer nunca más.",
        ["If you do it again, you'll be in deep trouble."] = "Si lo vuelves a hacer, estarás en serios problemas.",
        ["Hello."] = "Hola.",
        ["Ow!"] = "¡Ay!",
        ["Keep your foreign magicks out of my head!"] = "¡Mantén tus magias extranjeras fuera de mi cabeza!",
        ["Hi there."] = "Hola.",
        ["Voice in my head?"] = "¿Voz en mi cabeza?",
        ["Go away voice, leave My Arm."] = "Vete voz, deja My Arm.",
        ["Now that's the most weird conversation I've had in a long time."] = "Esa es la conversación más extraña que he tenido en mucho tiempo.",
        ["Is dat you, Player? My Arm can hear you but you not here."] = "¿Eres tú, Player? My Arm puede oírte pero no estás aquí.",
        ["I'm using magic to talk to you. How's the goutweed?"] = "Estoy usando magia para hablar contigo. ¿Cómo está la hierba gotosa?",
        ["Sorry, Player, but My Arm not know magic, so My Arm no can reply."] = "Lo siento, Player, pero My Arm no sabe magia, así que My Arm no puede responder.",
        ["Hiya."] = "Hola.",
        ["Oooh! Who are you?"] = "¡Oh! ¿Quién eres?",
        ["I'm a brave knight! I am coming to kill anyone in the vicinity of Lumbridge Castle!"] = "¡Soy un caballero valiente! ¡Vengo a matar a cualquiera que esté en las cercanías del Castillo Lumbridge!",
        ["Aaaaargh! Run away, run away!"] = "¡Aaaaargh! ¡Huye, huye!",
        ["Hehe. Fool!"] = "Jeje. ¡Tonto!",
        ["Hallo!"] = "¡Hola!",
        ["Whoa! A voice in my head! What do you want?"] = "¡Vaya! ¡Una voz en mi cabeza! ¿Qué deseas?",
        ["I am your evil master!"] = "¡Soy tu malvado maestro!",
        ["You're using dark magic to contact me! That is SO evil! What is thy bidding, O Master?"] = "¡Estás usando magia oscura para contactarme! ¡Eso es TAN malvado! ¿Cuál es tu orden, oh Maestro?",
        ["Build me an army worthy of Zamorak!"] = "¡Constrúyeme un ejército digno de Zamorak!",
        ["Yes, O master! As soon as I get this summoning thing to work, my army of evil UNDEAD CHAOS ZOMBIE DEMON ASSASSINS OF DARKNESS will overrun the world! Mwuhahahahaaa!"] = "¡Sí, oh maestro! ¡Tan pronto como haga funcionar esta cosa de invocación, mi ejército de malvados UNDEAD CHAOS ZOMBIE DEMON ASSASSINS OF DARKNESS OF DARKNESS invadirá el mundo! ¡Mwuhahahahaaa!",
        ["Error! Perception mismatch (auditory/visual)."] = "¡Error! Desajuste de percepción (auditiva/visual).",
        ["Don't worry, Golem! It's Player!"] = "¡No te preocupes, Golem! ¡Es Player!",
        ["I am sorry. I can hear you but not see you. I will have to examine my eyes."] = "Lo siento. Puedo oírte pero no verte. Tendré que examinarme los ojos.",
        ["No, you can't see me because I'm not there. I'm contacting you by magic!"] = "No, no puedes verme porque no estoy allí. ¡Me estoy contactando contigo por arte de magia!",
        ["If you are not here then I cannot be hearing you. I will have to examine my ears."] = "Si no estás aquí, entonces no puedo escucharte. Tendré que examinarme los oídos.",
        ["Don't worry about it, Golem."] = "No te preocupes, Golem.",
        ["What you want, Bentnoze?"] = "¿Qué quieres, Bentnoze?",
        ["Then who did say something? Who that?"] = "Entonces, ¿quién dijo algo? ¿Quién ese?",
        ["It's Player! I'm talking to you by magic!"] = "¡Es Player! ¡Te estoy hablando por arte de magia!",
        ["Hello, Player!"] = "¡Hola, Player!",
        ["Bentnoze, [he/she] is here! I hear [him/her] in head!"] = "Bentnoze, ¡[he/she] está aquí! ¡Escucho [him/her] en la cabeza!",
        ["Me not crazy, Bentnoze! [He/She] talk to me by magic!"] = "¡No estoy loco, Bentnoze! [He/She] hablame por arte de magia!",
        ["You shut up Bentnoze! You stupid! You just jealous Player talk to me not you!"] = "¡Cállate Bentnoze! ¡Eres estúpido! ¡Solo estás celoso! Player ¡Habla conmigo, no tú!",
        ["Shut up Bentnoze! You stupid!"] = "¡Cállate Bentnoze! ¡Eres estúpido!",
        ["SHUT UP!"] = "¡CÁLLATE!",
        ["Howdy."] = "Hola.",
        ["Waaahaaay! It's Player! *hic* Maate!"] = "¡Waaahaaay! ¡Es Player! *hip* ¡Maate!",
        ["How's things?"] = "¿Cómo van las cosas?",
        ["I fink oiv drunk a bit toooo much."] = "Creo que estoy borracho demasiado.",
        ["So, same as always."] = "Entonces, lo mismo de siempre.",
        ["Wont a kebab?"] = "¿Quieres kebab?",
        ["Uh, no, I'm good, thanks."] = "Uh, no, estoy bien, gracias.",
        ["Well, oym goona pass owt now. Have one on me!"] = "Bueno, oym goona pasa ahora. ¡Ten uno conmigo!",
        ["Oh, okay."] = "Oh, está bien.",
        ["Erm, bye."] = "Erm, adiós.",
        ["Hi there!"] = "¡Hola!",
        ["Why, helloooo!"] = "¡Hola!",
        ["A camel?"] = "¿Un camello?",
        ["Well this is grand, darling. How nice it is to make your acquaintance!"] = "Bueno, esto es grandioso, cariño. ¡Qué lindo es conocerte!",
        ["Thank you. Nice to meet you too."] = "Gracias. Estoy encantado de conocerte también.",
        ["Wait a minute. How am I talking to you without a camulet?"] = "Espera un minuto. ¿Cómo te hablo sin camuleto?",
        ["My dear, I'm a camel; how should I know?"] = "Querida, soy un camello; ¿Cómo debería saberlo?",
        ["Hmmm. I suppose this spell must tap directly into your mind, so there's no need for language to get in the way."] = "Mmmm. Supongo que este hechizo debe llegar directamente a tu mente, por lo que no es necesario que el lenguaje se interponga en tu camino.",
        ["I think I am somewhat confused."] = "Creo que estoy algo confundido.",
        ["May one ask how you contacted me?"] = "¿Puedo preguntar cómo me contactó?",
        ["I'm just using one of the Lunar spells."] = "Sólo estoy usando uno de los hechizos lunares.",
        ["Oh my, oh my. These youngsters today and their new-fangled gadgets!"] = "Dios mío, Dios mío. ¡Estos jóvenes de hoy y sus novedosos aparatos!",
        ["What do ya want for tea? And it better not be a baguette!"] = "¿Qué quieres de té? ¡Y más vale que no sea una baguette!",
        ["Don't ignore me, Player!"] = "¡No me ignores, Player!",
        ["Why won't people talk to me?"] = "¿Por qué la gente no me habla?",
        ["I'll beat you up!"] = "¡Te daré una paliza!",
        ["Uhh, urr, a sandwich please?"] = "Uhh, urr, ¿un sándwich, por favor?",
        ["Okay, then, my dear! Toodle-oo!"] = "¡Está bien, querida! ¡Toodle-oo!",
        ["Hey, I started the conversation!"] = "¡Oye, comencé la conversación!",
        ["No you didn't. Get out of my spell!"] = "No, no lo hiciste. ¡Sal de mi hechizo!",
        ["No! Get out of my spell!"] = "¡No! ¡Sal de mi hechizo!",
        ["Cry-baby."] = "Bebé llorón.",
        ["What! I'm no cry-baby, you cry-baby!"] = "¡Qué! ¡No soy un llorón, llorón!",
        ["I'm reporting you!"] = "¡Te estoy denunciando!",
        ["Oh, how scary!"] = "¡Oh, qué miedo!",
        ["Idiot."] = "Idiota.",
        ["Reveal yourself!"] = "¡Revélate!",
        ["Ha, call yourself a spymaster! You can't see me!"] = "¡Ja, llámate a ti mismo un maestro de espías! ¡No puedes verme!",
        ["Ahh, I'm hallucinating! Must cut back on sq'irks!"] = "¡Ahh, estoy alucinando! ¡Debemos reducir el consumo de sq'irks!",
        ["You have reached the Lunar Communication Helpline. I'm sorry we can't answer your telekinetic question right now. Our opening times are carefully organised to coincide with you being busy. If you are having an emergency, you have"] = "Te comunicaste con la línea de ayuda de comunicación lunar. Lamento que no podamos responder tu pregunta telequinética en este momento. Nuestros horarios de apertura están cuidadosamente organizados para que coincidan con su actividad. Si tiene una emergencia, tiene",
        ["our most profound apologies. Have a nice day. Goodbye."] = "nuestras más profundas disculpas. Que tenga un lindo día. Adiós.",
        ["Typical."] = "Típico.",
        ["At last! The voice of Saradomin! My years of meditation have paid off!"] = "¡Por fin! ¡La voz de Saradomin! ¡Mis años de meditación han dado sus frutos!",
        ["Um..."] = "Eh...",
        ["O mighty Saradomin! What is your message to me?"] = "¡Oh, poderoso Saradomin! ¿Cuál es tu mensaje para mí?",
        ["Stop sitting around in a house in a swamp and go and do something useful!"] = "¡Deja de quedarte sentado en una casa en un pantano y ve y haz algo útil!",
        ["Oh, thank you Saradomin! I will meditate on what this message means!"] = "¡Oh, gracias Saradomin! ¡Meditaré sobre lo que significa este mensaje!",
        ["Oh, hello. You sound lovely."] = "Oh, hola. Suenas encantador.",
        ["Sorry?"] = "¿Perdón?",
        ["You sound lovely. You have a beautiful...twang to your voice."] = "Suenas encantador. Tienes un hermoso... tono en tu voz.",
        ["Twang? It's Romeo, isn't it?"] = "¿Tang? Es Romeo, ¿no?",
        ["May I compare thee to some pineapple chunks?"] = "¿Puedo compararte con unos trozos de piña?",
        ["No, Romeo. Goodbye."] = "No, Romeo. Adiós.",
        ["Blurberry here! Can I help?"] = "¡Blurberry aquí! ¿Puedo ayudar?",
        ["Hehe. Yes you can. I'm looking for a Gnome. Gnome Mates."] = "Jeje. Sí puedes. Estoy buscando un Gnome. Gnome Compañeros.",
        ["Okay, I'll ask. Everybody shush! Is there a Gnome Mates here? Did anyone come in with Gnome Mates?"] = "Está bien, preguntaré. ¡Cállate todo el mundo! ¿Hay algún Gnome Mates aquí? ¿Alguien entró con Gnome Mates?",
        ["You hear laughter in the background."] = "Se oyen risas de fondo.",
        ["Ooooh, who is this? I'll get you!"] = "Ooooh, ¿quién es? ¡Te atraparé!",
        ["Hahaha."] = "Jajaja.",
        ["Because I can tell the future."] = "Porque puedo predecir el futuro.",
        ["Um?"] = "¿Eh?",
        ["That is the answer to your next question."] = "Esa es la respuesta a tu siguiente pregunta.",
        ["But how did you know what I would ask?"] = "¿Pero cómo supiste lo que te preguntaría?",
        ["Ah, that's very clever."] = "Ah, eso es muy inteligente.",
        ["Thanks. Oh - and be careful in the Wilderness. Tonight is not your night."] = "Gracias. Ah, y ten cuidado con el Wilderness. Esta noche no es tu noche.",
        ["Cheers!"] = "¡Salud!",
        ["Hello there! Who is this?"] = "¡Hola! ¿Quién es?",
        ["Hakeem who?"] = "¿Hakeem quién?",
        ["I'm Hakeem the Sandsweeper."] = "Soy Hakeem the Sandsweeper.",
        ["You sweep sand?"] = "¿Barres arena?",
        ["Certainly do! I'm the best darn sandsweeper this side of the Lum."] = "¡Por supuesto que sí! Soy el mejor barrendero de este lado del Lum.",
        ["There's more of you?"] = "¿Hay más de ustedes?",
        ["We have a union, mate! There's always sand to sweep."] = "¡Tenemos un sindicato, amigo! Siempre hay arena que barrer.",
        ["Indeed. Um, I have to go."] = "De hecho. Mmm, tengo que irme.",
        ["Excuse me!"] = "¡Disculpe!",
        ["Oh sorry, what did I do?"] = "Oh, lo siento, ¿qué hice?",
        ["Can't you see I'm on the toilet?"] = "¿No ves que estoy en el baño?",
        ["Wait a minute...a toilet?"] = "Espera un minuto... ¿un baño?",
        ["Yeah. A toilet."] = "Sí. Un baño.",
        ["Riiiight. Oh, man, you didn't wipe your hands?"] = "Correcto. Oh, hombre, ¿no te limpiaste las manos?",
        ["Get over it."] = "Supéralo.",
        ["Yo! Party, party, party!"] = "¡Oye! ¡Fiesta, fiesta, fiesta!",
        ["Um, Party Pete?"] = "Eh, ¿Party Pete?",
        ["Yeah! Party's the name, and partying is the game! Actually it's a full-time profession. You can't stop the party."] = "¡Sí! ¡La fiesta es el nombre y la fiesta es el juego! En realidad es una profesión de tiempo completo. No puedes detener la fiesta.",
        ["Party Pete. Do you ever want to just relax?"] = "Party Pete. ¿Alguna vez has querido simplemente relajarte?",
        ["Relax, don't do it! Yeah! Party mania! Yeah!"] = "¡Relájate, no lo hagas! ¡Sí! ¡Manía de fiesta! ¡Sí!",
        ["Bye, Party."] = "Adiós fiesta.",
        ["You may leave the party, but the party never leaves you! Party!"] = "¡Puedes abandonar la fiesta, pero la fiesta nunca te dejará a ti! ¡Fiesta!",
        ["Ah, Bob! I've been meaning to ask you some questions"] = "¡Ah, Bob! He querido hacerte algunas preguntas",
        ["Okay, but be quick."] = "Está bien, pero date prisa.",
        ["Well, where did you come from? Why do you wander around Gielinor? I've heard lots of rumours about your past!"] = "Bueno, ¿de dónde vienes? ¿Por qué deambulas por Gielinor? ¡He oído muchos rumores sobre tu pasado!",
        ["It's simple really..."] = "Es realmente simple...",
        ["*cough* *cough*."] = "*tos* *tos*.",
        ["Are you okay?"] = "¿Estás bien?",
        ["*cough* I'm *cough* just..."] = "*tos* Estoy *tos* solo...",
        ["Bob! Don't die! Noooooo!"] = "¡Bob! ¡No mueras! ¡Nooooo!",
        ["Sorry, I had a hairball."] = "Lo siento, tuve una bola de pelo.",
        ["Euw! That's nasty."] = "¡Uf! Eso es desagradable.",
        ["Hey, it's normal. I'm off now!"] = "Oye, es normal. ¡Me voy ahora!",
        ["Oh no, Bob, please don't go."] = "Oh no, Bob, por favor no te vayas.",
        ["Goodbye."] = "Adiós.",
        ["Who's that?"] = "¿Quién es ese?",
        ["What? Such insolence! How dare you speak like that, you poor excuse for goblin-dribble!"] = "¿Qué? ¡Qué insolencia! ¡Cómo te atreves a hablar así, pobre excusa para el regate duende!",
        ["Drop and give me twenty!"] = "¡Déjame veinte!",
        ["Okay, okay. I'm doing them now."] = "Está bien, está bien. Los estoy haciendo ahora.",
        ["Liar!"] = "¡Mentiroso!",
        ["Wait a minute, I don't have to put up with this. You do twenty!"] = "Espera un minuto, no tengo que aguantar esto. ¡Haces veinte!",
        ["Why I oughtta!"] = "¡Por qué debería hacerlo!",
        ["Erm, yeah. Bye!"] = "Erm, sí. ¡Adiós!",
        ["It's Player. How are you?"] = "Es Player. ¿Cómo estás?",
        ["Fine, thanks. How about you?"] = "Bien, gracias. ¿Y tú?",
        ["Alchemists return the other day. Me turn them into animals."] = "Los alquimistas regresan el otro día. Yo los convierto en animales.",
        ["No! Really?"] = "¡No! ¿En realidad?",
        ["Yeah, me made a uniman and a chickalchemist!"] = "Sí, ¡hice un uniman y un pollueloquimista!",
        ["Nice work!"] = "¡Buen trabajo!",
        ["Anyone there?"] = "¿Hay alguien ahí?",
        ["INTRUDER! Red alert! Batten down the hatches! DIVE, DIVE, DIVE!"] = "¡INTRUSO! ¡Alerta roja! ¡Fijar con listones los encerados de escotilla! ¡BUCEO, BUCEO, BUCEO!",
        ["Err, maybe I'll call back later."] = "Err, tal vez vuelva a llamar más tarde.",
        ["The fish cannot ride the gravy train."] = "Los peces no pueden subirse al tren de la salsa.",
        ["The cyclops cannot see his inner walrus?"] = "¿El cíclope no puede ver su morsa interior?",
        ["Is this code?"] = "¿Es este código?",
        ["Waddle into a sunset of flaking mackerel?"] = "¿Avanzar como un pato hacia un atardecer de caballa desmenuzada?",
        ["I'm going now."] = "Ya me voy.",
        ["The sardine is leaving the tin?"] = "¿La sardina se está saliendo de la lata?",
        ["Moooooo."] = "Muuuuuuuu.",
        ["Hey, I know you can talk!"] = "¡Oye, sé que puedes hablar!",
        ["Moooo."] = "Muuuu.",
        ["Stop ignoring me!"] = "¡Deja de ignorarme!",
        ["Look, mate. Leave me alone!"] = "Mira, amigo. ¡Déjame en paz!",
        ["You talked! You talked!"] = "¡Hablaste! ¡Hablaste!",
        ["I think I'll have some beef tonight."] = "Creo que comeré un poco de carne esta noche.",
        ["I'm contacting you by magic!"] = "¡Me estoy contactando contigo por arte de magia!",
        ["Hey Player, do you know someone named Evil Dave? He's telling me about his plan for world domination, but I'm not sure if he's being serious."] = "Hola Player, ¿conoces a alguien llamado Evil Dave? Me está contando sobre su plan para dominar el mundo, pero no estoy seguro de si habla en serio.",
        ["He's an evil wizard! You've got to stop him!"] = "¡Es un mago malvado! ¡Tienes que detenerlo!",
        ["Okay, I've got this."] = "Bien, ya lo tengo.",
        ["Stop right now, Evil Dave! If you want to conquer the world you'll have to get past me first!"] = "¡Detente ahora mismo, Evil Dave! ¡Si quieres conquistar el mundo, primero tendrás que superarme!",
        ["He's casting a spell, Player! He's made a magic circle and he's going to summon something! I have to disrupt the magic somehow!"] = "¡Está lanzando un hechizo, Player! ¡Ha hecho un círculo mágico y va a invocar algo! ¡Tengo que interrumpir la magia de alguna manera!",
        ["Make him get the words wrong!"] = "¡Haz que se equivoque en las palabras!",
        ["Disrupt the magic circle!"] = "¡Interrumpe el círculo mágico!",
        ["There! The circle's broken! Something is still happening, though..."] = "¡Ahí! ¡El círculo se ha roto! Aunque algo todavía está sucediendo...",
        ["Evil Dave has turned into a fish! He's flopping around and-"] = "¡Evil Dave se ha convertido en un pez! Él está dando vueltas y-",
        ["Oh, he's turned back."] = "Oh, ha regresado.",
        ["He says he's going to go and have a lie down. I think his evil plans are foiled for the time being."] = "Dice que va a ir a acostarse. Creo que sus malvados planes se han frustrado por el momento.",
        ["Just let him cast the spell"] = "Sólo déjalo lanzar el hechizo",
        ["I think he's harmless."] = "Creo que es inofensivo.",
        ["Really? He's asking me to join his evil scheme. He says I could be his 'Evil Death-Bringer Assassin of Darkness'."] = "¿En serio? Me está pidiendo que me una a su malvado plan. Dice que podría ser su 'Asesino de la oscuridad portador de la muerte malvado'.",
        ["You'd make a great assassin of darkness."] = "Serías un gran asesino de la oscuridad.",
        ["Ha! I bet I would. I'd stand on a rooftop, wrapped in a black cloak, a crossbow bolt glinting in the moonlight as my target moved unsuspecting below..."] = "¡Ja! Apuesto que lo haría. Me paraba en un tejado, envuelto en una capa negra, una ballesta brillando a la luz de la luna mientras mi objetivo se movía desprevenido abajo...",
        ["Um, if I were evil, of course."] = "Um, si fuera malvado, por supuesto.",
        ["Which I'm not."] = "Lo cual no soy.",
        ["I think I've hung around with Evil Dave for long enough. I'll talk to you some other time, Player."] = "Creo que ya llevo bastante tiempo con Evil Dave. Te hablaré en otro momento, Player.",
        ["You're not going to join him, are you?"] = "No vas a unirte a él, ¿verdad?",
        ["Of course not. You won't catch me being part of any evil scheme!"] = "Por supuesto que no. ¡No me pillarás siendo parte de ningún plan malvado!",
        ["Well, except that one time, of course. But I don't want to talk about that."] = "Bueno, excepto esa vez, por supuesto. Pero no quiero hablar de eso.",
        ["Anyway, I think I should leave Evil Dave to his schemes. I'll see you around, Player."] = "De todos modos, creo que debería dejar a Evil Dave con sus planes. Nos vemos por ahí, Player.",
        ["Player? Oldak, something's happening. I've got Player in my head."] = "¿Player? Oldak, algo está pasando. Tengo Player en mi cabeza.",
        ["I'm contacting you by magic."] = "Me estoy contactando contigo por arte de magia.",
        ["Um, okay. Hey Player, do you know what an 'abyssal doom vortex' is?"] = "Mmm, está bien. Hola Player, ¿sabes qué es un 'vórtice de fatalidad abisal'?",
        ["Because that's what Oldak says he's created in his lab."] = "Porque eso es lo que Oldak dice que creó en su laboratorio.",
        ["It's kind of getting larger, I think it's going to explode."] = "Se está haciendo más grande, creo que va a explotar.",
        ["Run away!"] = "¡Huye!",
        ["Okay! Oldak! Grubfoot! Let's get out of here!"] = "¡Está bien! ¡Oldak! ¡Grubfoot! ¡Salgamos de aquí!",
        ["Grubfoot's stuck under a thing. I'm going back for him."] = "Grubfoot está atrapado debajo de una cosa. Voy a volver por él.",
        ["Oh no!"] = "¡Oh, no!",
        ["I've ended up somewhere else. The walls are red...I think this is the abyss."] = "Terminé en otro lugar. Las paredes son rojas... Creo que esto es el abismo.",
        ["I can see a portal out, but there are some monsters between it and me."] = "Puedo ver un portal, pero hay algunos monstruos entre él y yo.",
        ["You should fight them."] = "Deberías luchar contra ellos.",
        ["Okay, I haven't got my crossbow, but I'm got a dagger. Here goes..."] = "Vale, no tengo mi ballesta, pero tengo una dagger. Aquí va...",
        ["There! They weren't as tough as they looked. I've reached the portal."] = "¡Ahí! No eran tan duros como parecían. He llegado al portal.",
        ["I'm home! And Grubfoot is fine. That's a relief."] = "¡Estoy en casa! Y Grubfoot está bien. Eso es un alivio.",
        ["Okay, I'm going to help Oldak clean up the mess. I'll see you around, Player."] = "Está bien, voy a ayudar a Oldak a limpiar el desorden. Nos vemos por ahí, Player.",
        ["You should sneak past them."] = "Deberías escabullirte de ellos.",
        ["You need to shut it down!"] = "¡Necesitas apagarlo!",
        ["Yeah, that's what I was thinking."] = "Sí, eso es lo que estaba pensando.",
        ["Hey, Oldak, Player thinks you should shut it down!"] = "¡Oye, Oldak, Player cree que deberías cerrarlo!",
        ["Oh no! Oldak!"] = "¡Oh, no! ¡Oldak!",
        ["Oldak's paralysed!"] = "¡Oldak está paralizado!",
        ["I can't remember how to shut it down! What did Oldak say? It was either de-align the rune injector, or reverse to polarity on the polarity reverser."] = "¡No recuerdo cómo apagarlo! ¿Qué dijo Oldak? Se trataba de desalinear el inyector de runas o invertir la polaridad en el inversor de polaridad.",
        ["De-align the injector!"] = "¡Desalinee el inyector!",
        ["Okay! Here goes..."] = "¡Está bien! Aquí va...",
        ["It worked! It's shut off! But it's left this red gunk all over the floor."] = "¡Funcionó! ¡Está apagado! Pero ha dejado esta porquería roja por todo el suelo.",
        ["Oldak is scraping some of it into a sample jar. A very interesting result, he says."] = "Oldak está raspando un poco en un frasco de muestra. Un resultado muy interesante, afirma.",
        ["Anyway, that looks like the end of that abyssal doom vortex. I'll see you around Player."] = "De todos modos, eso parece el final de ese vórtice abismal de fatalidad. Nos vemos en Player.",
        ["Reverse the polarity!"] = "¡Invierte la polaridad!",
        ["Okay, I'm turning this part the other way round..."] = "Bien, voy a darle la vuelta a esta parte...",
        ["Wow..."] = "Vaya...",
        ["That's the most amazing...it's...indescribable..."] = "Eso es lo más sorprendente... es... indescriptible...",
        ["What was it? What happened?"] = "¿Qué fue? ¿Qué pasó?",
        ["I can't describe it! It's literally indescribable!"] = "¡No puedo describirlo! ¡Es literalmente indescriptible!",
        ["Anyway, it's gone now."] = "De todos modos, ya no está.",
        ["I think I should leave Oldak and Grubfoot to work. I'll see you around, Player."] = "Creo que debería dejar que Oldak y Grubfoot trabajen. Nos vemos por ahí, Player.",
        ["Player? Where are you? I can't see you in the swamp."] = "¿Player? ¿Dónde estás? No puedo verte en el pantano.",
        ["Oh! I'm exploring Morytania and..."] = "¡Oh! Estoy explorando Morytania y...",
        ["Whoah! I'm slipping! Wo-o-oah!"] = "¡Vaya! ¡Me estoy resbalando! ¡Guau!",
        ["Zanik? Are you alright?"] = "¿Zanik? ¿Estás bien?",
        ["I've fallen in the swamp! What should I do Player?"] = "¡Me caí en el pantano! ¿Qué debo hacer Player?",
        ["Grapple out with your crossbow!"] = "¡Enfréntate con tu ballesta!",
        ["Okay, I'll try that..."] = "Está bien, lo intentaré...",
        ["There, the grapple's caught on a tree. I'm climbing out..."] = "Allí, la garra está atrapada en un árbol. Estoy saliendo...",
        ["I've landed in a bush, and... hey, there's someone else here! Hey! Lumberjack! Over here!"] = "Aterricé en un arbusto y... ¡oye, hay alguien más aquí! ¡Ey! ¡Leñador! ¡Por aquí!",
        ["He's turning this way, and... oh. Uh-oh. I think he's a zombie."] = "Está girando hacia aquí y... oh. Oh, oh. Creo que es un zombi.",
        ["Run for it!"] = "¡Corre por ello!",
        ["You can take it! Fight!"] = "¡Puedes aceptarlo! ¡Luchar!",
        ["It's not so tough!"] = "¡No es tan difícil!",
        ["Its arm's come off, but it's still coming at me!"] = "¡Se le ha caído el brazo, pero todavía viene hacia mí!",
        ["Now I've cut off both its arms, but it's still trying to bite me!"] = "Ahora le corté ambos brazos, ¡pero todavía intenta morderme!",
        ["What? It's hopping at me with just one leg! Why doesn't it die already?"] = "¿Qué? ¡Está saltando hacia mí con una sola pierna! ¿Por qué no muere ya?",
        ["There. I've cut off all its limbs and kicked it in the swamp. No zombie is safe from Zanik of the Dorgeshuun!"] = "Ahí. Le corté todas las extremidades y lo pateé al pantano. ¡Ningún zombi está a salvo de Zanik de Dorgeshuun!",
        ["I don't think I'll have trouble with anything else in this swamp. Thanks for the help, Player! See you around!"] = "No creo que tenga problemas con nada más en este pantano. ¡Gracias por la ayuda, Player! ¡Ya nos veremos!",
        ["Try to swim to the bank!"] = "¡Intenta nadar hasta la orilla!",
        ["I think I can do that! The bank is just..."] = "¡Creo que puedo hacer eso! El banco es sólo...",
        ["Hey, what's that? There's a head poking out of the water..."] = "Oye, ¿qué es eso? Hay una cabeza asomando del agua...",
        ["Eek! Tentacles! It's got me!"] = "¡Eek! Tentáculos! ¡Me tiene!",
        ["Attack the tentacle!"] = "Attack el tentáculo!",
        ["Attack the head!!"] = "Attack la cabeza!!",
        ["Attack the head!"] = "¡Attack la cabeza!",
        ["I hope that my crossbow's still dry enough..."] = "Espero que mi ballesta todavía esté lo suficientemente seca...",
        ["Haha! Got it! Crossbow bolt in the eye!"] = "¡Jaja! ¡Entiendo! ¡Perno de ballesta en el ojo!",
        ["It didn't seem to hurt it too much, but it's let me go. I've got back to the bank. I think I can see a way out of the swamp from here."] = "No pareció dolerme demasiado, pero me dejó ir. He vuelto al banco. Creo que puedo ver una salida del pantano desde aquí.",
        ["Thanks for your help, Player! I'll talk to you some other time."] = "¡Gracias por tu ayuda, Player! Hablaré contigo en otro momento.",
        ["Last contact not found. Please call again."] = "Último contacto no encontrado. Por favor llame nuevamente.",
        ["Redialing '[NPC]'..."] = "Volviendo a marcar '[NPC]'...",
        ["You do not have enough [rune type] runes to cast this spell."] = "No tienes suficientes runas [rune type] para lanzar este hechizo.",
    },
    ["Naff"] = {
        ["Hello."] = "Hola.",
        ["Ello, [guv/miss], wot you want then?"] = "Hola, [guv/miss], ¿qué quieres entonces?",
        ["Select an option"] = "Selecciona una opción",
        ["Do you have any battlestaves?"] = "¿Tienes algún bastón de batalla?",
        ["Ahh, you're one of those nos- I mean, you've been helping out in Varrock haven't you? I've been told to always keep a few extra battlestaves for loyal citizens such as yourself."] = "Ahh, eres uno de esos nos- Quiero decir, has estado ayudando en Varrock, ¿no? Me han dicho que siempre guarde algunos bastones de batalla extra para ciudadanos leales como tú.",
        ["Nothing, bye!"] = "¡Nada, adiós!",
    },
    ["Naida"] = {
        ["Aren't you tired?"] = "¿No estás cansado?",
        ["Yep! But it's worth it to see the water turn into a beautiful glistening pool. I plan on going for a dip after I'm done!"] = "¡Sí! Pero vale la pena ver cómo el agua se convierte en una hermosa piscina reluciente. ¡Planeo darme un chapuzón cuando termine!",
        ["Just watch out for the scarabs and crocodiles..."] = "Solo ten cuidado con los escarabajos y los cocodrilos...",
    },
    ["Nails Newton"] = {
        ["You here for something?"] = "¿Estás aquí por algo?",
        ["I'm trying to complete a treasure trail."] = "Estoy intentando completar un rastro del tesoro.",
        ["Well you need to do this favour for me first."] = "Bueno, primero debes hacerme este favor.",
        ["[Nails Newton has given you a challenge scroll!]"] = "[¡Nails Newton te ha dado un pergamino de desafío!]",
        ["Please enter the answer to the question."] = "Ingrese la respuesta a la pregunta.",
        ["Enter amount:<br>[Input field]"] = "Ingrese la cantidad:<br>[Input field]",
        ["Wrong. Have you tried counting?"] = "Incorrecto. ¿Has probado a contar?",
        ["[Nails Newton has given you another clue scroll!]"] = "[¡Nails Newton te ha dado otro pergamino de pistas!]",
        ["[You've found a casket!]"] = "[¡Has encontrado un ataúd!]",
        ["Correct!"] = "¡Correcto!",
    },
    ["Nakatra, Devourer Eternal"] = {
        ["Stunning the Corrupted scarab healer has made it susceptible to damage."] = "Aturdir al sanador escarabajo corrupto lo ha hecho susceptible al daño.",
        ["Stunning the Volatile scarab akh has made it susceptible to damage."] = "Aturdir al escarabajo volátil akh lo ha hecho susceptible a sufrir daños.",
        ["Avoiding the attack gives you a rush of energy, resetting your movement ability cooldowns."] = "Evitar el ataque te proporciona una oleada de energía, lo que restablece los tiempos de reutilización de tus habilidades de movimiento.",
        ["Nefthys, the Split Soul is taking greatly reduced damage while howling. Move closer to stop it!"] = "Nefthys, Split Soul recibe un daño muy reducido mientras aúlla. ¡Acércate para detenerlo!",
        ["You grab attention of Nefthys, the Split Soul and disrupt the howling."] = "Llamas la atención de Nefthys, el Alma Dividida e interrumpes los aullidos.",
        ["Nefthys finishes howling and greatly empowers Nakatra."] = "Nefthys termina de aullar y potencia enormemente a Nakatra.",
        ["The crushing power tears through your defences."] = "El poder aplastante atraviesa tus defensas.",
        ["Release and recover soul fragments to escape the Shadowsands before your soul is devoured!"] = "¡Libera y recupera fragmentos de alma para escapar de Shadowsands antes de que tu alma sea devorada!",
        ["As you attempt to release the soul fragments, defending devourers appear!"] = "Mientras intentas liberar los fragmentos de alma, ¡aparecen devoradores defensores!",
        ["Defeating the devourers releases their hold on your soul."] = "Derrotar a los devoradores libera su control sobre tu alma.",
        ["Shadowsands gorilla akh has been affected by Devour! Their healing has been reduced!"] = "¡El gorila akh de Shadowsands ha sido afectado por Devour! ¡Su curación se ha reducido!",
        ["You recover fragments of your soul and escape the Shadowsands."] = "Recuperas fragmentos de tu alma y escapas de Shadowsands.",
        ["Nakatra is preparing to unleash a fatal attack! Protect yourself by standing on the hieroglyph missing from the Shadowsands."] = "¡Nakatra se está preparando para desatar un ataque fatal! Protégete parándote sobre el jeroglífico que falta en Shadowsands.",
        ["Nakatra is taking greatly reduced damage while she holds a connection to the Devourer"] = "Nakatra recibe un daño muy reducido mientras mantiene una conexión con el Devorador.",
        ["The missing Shadowsands hieroglyph protects you from Nakatra's barrage!"] = "¡El jeroglífico desaparecido de Shadowsands te protege del bombardeo de Nakatra!",
        ["You have unlocked access to the hard mode encounter."] = "Has desbloqueado el acceso al encuentro en modo difícil.",
        ["Completion Time: [time] - New Personal Record!"] = "Tiempo de finalización: [time] - ¡Nuevo récord personal!",
        ["Completion Time: [time] - New Personal Record! An improvement of [time]!"] = "Tiempo de finalización: [time] - ¡Nuevo récord personal! ¡Una mejora de [time]!",
        ["Congratulations. You have completed the Boss Dungeon: The Sanctum of Rebirth."] = "Felicitaciones. Has completado Boss Dungeon: The Sanctum of Rebirth.",
        ["You have killed [number] Nakatra, Devourer Eternal in normal mode."] = "Has matado a [número] Nakatra, Devourer Eternal en modo normal.",
        ["Congratulations. You have completed the Boss Dungeon: The Sanctum of Rebirth (hard mode)."] = "Felicitaciones. Has completado Boss Dungeon: The Sanctum of Rebirth (modo difícil).",
        ["You have killed [number] Nakatra, Devourer Eternal in hard mode."] = "Has matado a [número] Nakatra, Devourer Eternal en modo difícil.",
    },
    ["Name"] = {
        ["Hello."] = "Hola.",
        ["Hey there. You look like an adventurer type."] = "Hola. Pareces un tipo aventurero.",
        ["You could say that. What do you need?"] = "Se podría decir eso. ¿Qué necesitas?",
        ["Oh, nothing. Just making an observation."] = "Oh, nada. Sólo hago una observación.",
        ["That's a first, I think."] = "Creo que es la primera vez.",
    },
    ["Nanuq"] = {
        ["Grrrrrrrrrrr. Groooowliowlioooo!"] = "Grrrrrrrrrrr. Groooowlioowlioooo!",
        ["Grrroooorgh. <br>(Hello, Player. What can I do for you today?)"] = "Grrroooorgh. <br>(Hola, Player. ¿Qué puedo hacer por ti hoy?)",
        ["Select an Option"] = "Selecciona una opción",
        ["Could you look after this beacon for me?"] = "¿Podrías cuidar esta baliza por mí?",
        ["Grrrrrrrrrrr. Groooowliowlioooo! <br>(Of course. Once the beacon is lit, just have 5 logs with me and I'll take care of the fire for as long as I can.)"] = "Grrrrrrrrrrr. Groooowlioowlioooo! <br> (Por supuesto. Una vez que la baliza esté encendida, solo ten 5 logs conmigo y yo me encargaré del fuego tanto tiempo como pueda).",
        ["Groooowliowlioooo! ( Well, I could, but since you're here, you might as well do it yourself.)"] = "¡Gruooowlioowlioooo! (Bueno, podría, pero ya que estás aquí, es mejor que lo hagas tú mismo).",
        ["You must give the fire tender five of the same type of log for the beacon."] = "Debes darle al bombero cinco troncos del mismo tipo para la baliza.",
        ["Grrrrrrrrrrr. Groooowliowlioooo! <br> (I'm afraid that you don't have enough of the right type of log for me to use.)"] = "Grrrrrrrrrrr. Groooowlioowlioooo! <br> (Me temo que no tiene suficiente registro del tipo correcto para que yo lo use).",
        ["Grrr-arrrrg?<br>(I'll need five logs to be able to tend the fire. Is that okay?)"] = "Grrr-arrrrg?<br>(Necesitaré cinco logs para poder atender el fuego. ¿Está bien?)",
        ["Do you want to give five logs to the fire tender?"] = "¿Quieres darle cinco logs al fuego?",
        ["Yes."] = "Sí.",
        ["Here are five logs for you."] = "Aquí tienes cinco logs para ti.",
        ["Groooowliowlioooo!  <br>(Thank you! I'll use these five logs to keep the beacon burning while you're away.)"] = "¡Gruooowlioowlioooo!  <br>(¡Gracias! Usaré estos cinco logs para mantener la baliza encendida mientras estás fuera).",
        ["I think I'll keep hold of my logs for now."] = "Creo que conservaré mi logs por ahora.",
        ["Raaaargh-groooool. <br> (Well, you know where I am if you change your mind.)"] = "Raaaargh-groooool. <br> (Bueno, ya sabes dónde estoy si cambias de opinión).",
        ["Yes. Please don't ask me for confirmation in future."] = "Sí. Por favor, no me pidas confirmación en el futuro.",
        ["Groooowliowlioooo! <br>(Of course I will, don't worry. I'll use the logs you've already left with me."] = "¡Gruooowlioowlioooo! <br>(Por supuesto que lo haré, no te preocupes. Usaré el logs que ya me dejaste.",
        ["Can you tell me about other beacons?"] = "¿Puedes hablarme de otras balizas?",
        ["Grrrroooorrg-gah. <br>(Most certainly.)"] = "Grrrroooorrg-gah. <br>(Sin duda.)",
        ["Is it possible to get information about beacons that are further away?"] = "¿Es posible obtener información sobre balizas que están más alejadas?",
        ["Grrroooorrgh.<br> (I can tell you about the beacons in either direction, up to and including the first one that's out.)"] = "Grrroooorrgh.<br> (Puedo informarte sobre las balizas en cualquier dirección, hasta la primera que sale inclusive).",
        ["Grrrummmbberggrah. <br>(Of course, a macaw has much sharper eyes than I do. If I could work with that macaw you've got there, we could tell you about the entire beacon network.)"] = "Grrrummmbberggrah. <br>(Por supuesto, una guacamaya tiene ojos mucho más agudos que yo. Si pudiera trabajar con esa guacamaya que tienes allí, podríamos contarte sobre toda la red de balizas).",
        ["A macaw?"] = "¿Una guacamaya?",
        ["Grrrummmbble. <br>(Yes. Macaws have the ability to fly high into the air and see things that are much further away.}"] = "Grrrummmbble. <br>(Sí. Las guacamayas tienen la capacidad de volar muy alto en el aire y ver cosas que están mucho más lejos.}",
        ["Grrr-bah.<br> {They are also highly intelligent and can be trained to provide the exact information needed for a complete overview of the beacon network.)"] = "Grrr-bah.<br> {También son muy inteligentes y pueden ser entrenados para proporcionar la información exacta necesaria para una descripción completa de la red de balizas).",
        ["Grrroooorrgh.<br> (Come to think of it, the macaw you've got there in  pack would be perfect.)"] = "Grrroooorrgh.<br> (Ahora que lo pienso, el guacamayo que tienes en el paquete sería perfecto).",
        ["How's it going?"] = "¿Cómo te va?",
        ["Grrrrrrrrrrr. Groooowliowlioooo!<br> (Oo, are you the snack that I ordered? I must say, I'm impressed at the speed of deliveries these days.)"] = "Grrrrrrrrrrr. Groooowliowlioooo!<br> (Oo, ¿eres el bocadillo que pedí? Debo decir que estoy impresionado por la velocidad de las entregas en estos días).",
        ["I'm no snack! You can get that thought right out of your head."] = "¡No soy un bocadillo! Puedes sacar ese pensamiento de tu cabeza.",
        ["Raaaargh, grrrrrrowl groooo.<br> (Sincerest apologies, my mistake.)"] = "Raaaargh, grrrrrrowl groooo.<br> (Mis más sinceras disculpas, error mío).",
        ["I'm done talking to you, now!"] = "¡Ya terminé de hablar contigo!",
        ["Grrroooorrgh. <br>(Goodbye, then.)"] = "Grrroooorrgh. <br>(Adiós, entonces.)",
        ["Grrrrrrrrrrr. Groooowliowlioooo! <br> (I wouldn't bother. That beacon won't stay alight until that windbreak gets repaired.)"] = "Grrrrrrrrrrr. Groooowlioowlioooo! <br> (No me molestaría. Esa baliza no permanecerá encendida hasta que se repare el cortavientos).",
        ["Rawwrrr grrrrowl. <br> (I've been trying to chew the fibres together with my teeth, but for some reason, that just seems to make it worse.)"] = "Rawwrrr grrrrowl. <br> (He estado tratando de masticar las fibras con los dientes, pero por alguna razón, eso parece empeorar las cosas).",
        ["Hmm. Could you use a little help with that?"] = "Mmm. ¿Te vendría bien un poco de ayuda con eso?",
        ["Grrrrrrrrrrumph...grr. <br> (Perhaps a more pedestrian approach would suffice. I suspect someone with opposable thumbs could fix it with a needle and several pieces of jute fibre.)"] = "Grrrrrrrrrrumph...grr. <br> (Quizás un enfoque más peatonal sería suficiente. Sospecho que alguien con pulgares oponibles podría arreglarlo con una aguja y varios trozos de fibra de yute).",
        ["Grrrah? <br> (You wouldn't have time for a little DIY, would you?)"] = "¿Grrrah? <br> (No tendrías tiempo para un poco de bricolaje, ¿verdad?)",
        ["I'll see what I can do."] = "Veré qué puedo hacer.",
        ["Grrroooorrgh. <br>(Much obliged.)"] = "Grrroooorrgh. <br>(Muchas gracias.)",
        ["Do you want to give the fire tender your macaw?"] = "¿Quieres darle al fuego tierno tu guacamayo?",
        ["Raaaargh, grooool grrrrrrrowl. <br> (Thank you very much. This will help me give you more detailed information about the fire network.)"] = "Raaaargh, genial grrrrrrrowl. <br> (Muchas gracias. Esto me ayudará a brindarle información más detallada sobre la red contra incendios).",
        ["I think I'll keep my macaw for now."] = "Creo que me quedaré con mi guacamaya por ahora.",
        ["Raaaargh-groooool. <br> (Suit yourself.)"] = "Raaaargh-groooool. <br> (Haz lo que quieras.)",
        ["I've already given him a macaw; he doesn't need another."] = "Ya le regalé una guacamaya; él no necesita otro.",
        ["There's no fire here for the fire tender to tend."] = "Aquí no hay fuego para que lo atienda el bombero.",
        ["Since I'm here and the beacon's fire is dying down, I might as well tend the fire myself."] = "Ya que estoy aquí y el fuego de la baliza se está apagando, también podría cuidarlo yo mismo.",
        ["The fire tender needs five of the same type of log to maintain this fire."] = "El bombero necesita cinco troncos del mismo tipo para mantener este fuego.",
        ["You give the fire tender 5 [type] logs."] = "Le das al fuego tierno 5 [type] logs.",
        ["I think I'll hang on to my logs after all."] = "Creo que, después de todo, me quedaré con mi logs.",
        ["Yes. Please don't ask me for confirmation again."] = "Sí. Por favor, no vuelvas a pedirme confirmación.",
        ["You've already left logs with this fire tender."] = "Ya saliste de logs con este ténder de fuego.",
        ["Oi! Get away from that! Until you've proven yourself a true ally of Varrock, you can't use that!"] = "¡Oye! ¡Aléjate de eso! Hasta que no hayas demostrado que eres un verdadero aliado de Varrock, ¡no podrás usar eso!",
        ["You need to claim the reward for the elite set Tasks in Varrock to use this chest."] = "Debes reclamar la recompensa por las tareas del conjunto de élite en Varrock para usar este cofre.",
    },
    ["Naomi"] = {
        ["If you're looking for a tailor, you've come to the right place."] = "Si buscas un sastre, has venido al lugar correcto.",
        ["If you're looking for a potter so careless that he ruined a season's supply of perfectly good cloth, you'll find my husband across the street."] = "Si estás buscando a un alfarero tan descuidado que arruinó el suministro de telas en perfecto estado para una temporada, encontrarás a mi marido al otro lado de la calle.",
        ["He's not allowed in the house during work hours anymore."] = "Ya no se le permite entrar a la casa durante las horas de trabajo.",
    },
    ["Naragi (echo)"] = {
        ["The Nature of things is a perfect cycle, from one state to another, and a return to prior existence."] = "La Naturaleza de las cosas es un ciclo perfecto, de un estado a otro, y un retorno a la existencia anterior.",
        ["Things that once existed, yet now are lost, may yet return and in improved form."] = "Las cosas que alguna vez existieron, pero que ahora están perdidas, aún pueden regresar y en forma mejorada.",
        ["That which is no more shall return again, renewed with more vigour and power than before."] = "Lo que ya no existe volverá de nuevo, renovado con más vigor y poder que antes.",
        ["Those who remember the past will see the truth in my words."] = "Aquellos que recuerden el pasado verán la verdad en mis palabras.",
        ["Of future events, I see most clear, yet things that must be, must be."] = "De los eventos futuros, los veo más claros, sin embargo, las cosas que deben ser, deben ser.",
        ["I could change them if I so desired, but I do not, for all things must happen as they run their course."] = "Podría cambiarlos si así lo deseara, pero no lo hago, ya que todas las cosas deben suceder a medida que siguen su curso.",
    },
    ["Naragi"] = {
        ["The Nature of things is a perfect cycle, from one state to another, and a return to prior existence."] = "La Naturaleza de las cosas es un ciclo perfecto, de un estado a otro, y un retorno a la existencia anterior.",
        ["Things that once existed, yet now are lost, may yet return and in improved form."] = "Las cosas que alguna vez existieron, pero que ahora están perdidas, aún pueden regresar y en forma mejorada.",
        ["That which is no more shall return again, renewed with more vigour and power than before."] = "Lo que ya no existe volverá de nuevo, renovado con más vigor y poder que antes.",
        ["Those who remember the past will see the truth in my words."] = "Aquellos que recuerden el pasado verán la verdad en mis palabras.",
        ["Of future events, I see most clear, yet things that must be, must be."] = "De los eventos futuros, los veo más claros, sin embargo, las cosas que deben ser, deben ser.",
        ["I could change them if I so desired, but I do not, for all things must happen as they run their course."] = "Podría cambiarlos si así lo deseara, pero no lo hago, ya que todas las cosas deben suceder a medida que siguen su curso.",
    },
    ["Nardok"] = {
        ["**Nardok** Psst... wanna buy some weapons?"] = "**Nardok** Psst... ¿quieres comprar algunas armas?",
        ["What have you got?"] = "¿Qué tienes?",
        ["**Player** What have you got?"] = "**Player** ¿Qué tienes?",
        ["**Nardok** Well, first up there's the normal bone club and bone spear. Good, solid frog-bone, and the spear has an iron tip. Can withstand a lot of punishment, if you know what I mean!"] = "**Nardok** Bueno, primero está el garrote de hueso y la lanza de hueso normales. Un hueso de rana bueno y sólido, y la lanza tiene una punta de hierro. ¡Puede soportar muchos castigos, si sabes a qué me refiero!",
        ["**Nardok** But if you're after something a bit fancier, a bit more sophisticated, there's the bone crossbow and dagger."] = "**Nardok** Pero si buscas algo un poco más sofisticado, un poco más sofisticado, están la ballesta de hueso y dagger.",
        ["**Nardok** These are specially good for getting your prey unawares, but you're not going to get the best out of them unless you've been taught the special technique."] = "**Nardok** Estos son especialmente buenos para sorprender a tu presa, pero no obtendrás lo mejor de ellos a menos que te hayan enseñado la técnica especial.",
        ["**Nardok** So, you interested?"] = "**Nardok** Entonces, ¿estás interesado?",
        ["I might be."] = "Podría serlo.",
        ["**Player** I might be."] = "**Player** Podría serlo.",
        ["Nardok's Bone Weapons opens."] = "Se abren las armas de hueso de Nardok.",
        ["No thanks."] = "No gracias.",
        ["**Player** No thanks"] = "**Player** No, gracias",
        ["**Nardok** Yeah, you stay out of trouble."] = "**Nardok** Sí, no te metas en problemas.",
        ["Why are you whispering?"] = "¿Por qué estás susurrando?",
        ["**Player** Why are you whispering?"] = "**Player** ¿Por qué estás susurrando?",
        ["**Nardok** Well, y'know, it's not the most reputable profession, is it? Selling weapons?"] = "**Nardok** Bueno, ya sabes, no es la profesión de mayor reputación, ¿verdad? ¿Vender armas?",
        ["**Player** Why not?"] = "**Player** ¿Por qué no?",
        ["**Nardok** Well, they're used to hurt people, aren't they? That's not considered very, y'know, respectable. Even though the guards use them, and the hunters, they're still considered a bit, y'know, dirty"] = "**Nardok** Bueno, están acostumbrados a lastimar a la gente, ¿no? Eso no se considera muy, ya sabes, respetable. A pesar de que los guardias los usan, y los cazadores, todavía se los considera un poco, ya sabes, sucios.",
        ["**Nardok** Isn't it like that where you come from?"] = "**Nardok** ¿No es así de donde vienes?",
        ["**Player** No, on the surface weapon-making is considered a noble profession."] = "**Player** No, en la superficie la fabricación de armas se considera una profesión noble.",
        ["**Nardok** I don't know, you surface people are strange!"] = "**Nardok** No lo sé, ¡la gente de la superficie es extraña!",
    },
    ["Naressa"] = {
        ["Stay back!"] = "¡Quédate atrás!",
        ["Nice... dragonkin..."] = "Bien... dragonante...",
        ["Don't act innocent. I've seen what you and your people out there have been doing to my kind."] = "No actúes inocente. He visto lo que tú y tu gente le han estado haciendo a los de mi especie.",
        ["I'm not here to kill you. Unless you want to kill me, that is."] = "No estoy aquí para matarte. A menos que quieras matarme, claro está.",
        ["No, I have no interest in that. Who are you, and why are you here?"] = "No, no tengo ningún interés en eso. ¿Quién eres y por qué estás aquí?",
        ["I'm Player! I was just wandering about, exploring this place, and just happened to spot you."] = "¡Soy Player! Estaba deambulando, explorando este lugar y casualmente te vi.",
        ["Alright, Player. I'm Naressa. But I'm still keeping my eye on you."] = "Muy bien, Player. Soy Naressa. Pero sigo vigilándote.",
        ["Hello, Player. I'm pleased you came out to visit me again."] = "Hola, Player. Me alegra que hayas vuelto a visitarme.",
        ["**SELECT AN OPTION**"] = "**SELECCIONA UNA OPCIÓN**",
        ["What are you doing out here?"] = "¿Qué estás haciendo aquí afuera?",
        ["What are you doing all the way out here? Why aren't you trying to kill me?"] = "¿Qué haces hasta aquí? ¿Por qué no intentas matarme?",
        ["Those are some good questions. I ran here from the battlefield. Something menacing is going on down there, but I managed to break free. There wasn't really anywhere else to go - those creatures in the Cathedral would attack me on sight."] = "Esas son algunas buenas preguntas. Corrí aquí desde el campo de batalla. Algo amenazador está sucediendo ahí abajo, pero logré liberarme. Realmente no había ningún otro lugar a donde ir; esas criaturas en la Catedral me atacarían en cuanto me vieran.",
        ["Something menacing? What do you mean?"] = "¿Algo amenazante? ¿Qué quieres decir?",
        ["It's... hard to explain. Up until recently, I felt like I was living in a dream. Yet, every so often, there would be brief moments of lucidity. I insisted on chasing those moments, trying to make sense of what I was feeling, until eventually the blurriness just ceased."] = "Es... difícil de explicar. Hasta hace poco me sentía como si estuviera viviendo un sueño. Sin embargo, de vez en cuando, habría breves momentos de lucidez. Insistí en perseguir esos momentos, tratando de darle sentido a lo que estaba sintiendo, hasta que finalmente la confusión simplemente cesó.",
        ["Huh. I wonder if that could have anything to do with your hibernation pods?"] = "Eh. Me pregunto si eso podría tener algo que ver con tus cápsulas de hibernación.",
        ["You know about those? Regardless, yes, that was my theory too. We had many shared dreams while we slept. I can't really recall any of them, except one. It was as if we had been awoken, under attack by the Roakin once again. And so we defended ourselves. Everything became clear to me once my senses came back under my control. Which is fine for me, but I don't know what I can do to help my kin down there."] = "¿Conoces esos? De todos modos, sí, esa también era mi teoría. Tuvimos muchos sueños compartidos mientras dormíamos. Realmente no puedo recordar ninguno de ellos, excepto uno. Era como si nos hubieran despertado, bajo el ataque de los Roakin una vez más. Y así nos defendimos. Todo quedó claro para mí una vez que mis sentidos volvieron a estar bajo control. Lo cual está bien para mí, pero no sé qué puedo hacer para ayudar a mis parientes de allá.",
        ["Neither do I. At this point I'm afraid they may only be able to help themselves. However, I do know that Kerapac is involved here, presenting himself as the leader of your army."] = "Yo tampoco. En este punto me temo que solo podrán ayudarse a sí mismos. Sin embargo, sé que Kerapac está involucrado aquí, presentándose como el líder de su ejército.",
        ["Kerapac? That menacing little... Before our hibernation, he was always messing about with his little science experiments. Intelligent, creative, and driven, but unscrupulous. It was inevitable he'd go too far one day. Many of us Nodon knew he was untrustworthy."] = "¿Kerapac? Ese pequeño amenazador... Antes de nuestra hibernación, siempre estaba trasteando con sus pequeños experimentos científicos. Inteligente, creativo y motivado, pero sin escrúpulos. Era inevitable que algún día fuera demasiado lejos. Muchos de nosotros, Nodon, sabíamos que no era digno de confianza.",
        ["Yep, that's pretty much been my experience with him too."] = "Sí, esa también ha sido mi experiencia con él.",
        ["Well, he's nothing if not consistent, I guess."] = "Bueno, supongo que no es más que consistente.",
        ["Tell me about yourself."] = "Háblame de ti.",
        ["Can you tell me anything about yourself?"] = "¿Puedes contarme algo sobre ti?",
        ["Hmm... What exactly would you like to know?"] = "Hmm... ¿Qué es exactamente lo que te gustaría saber?",
        ["Do you have any hobbies?"] = "¿Tienes algún pasatiempo?",
        ["Hobbies? No, not really. I devoted my life to my work, engrossing myself in all things architecture. If I wasn't training, I was studying, and if I wasn't studying, I was building."] = "¿Pasatiempos? No, en realidad no. Dediqué mi vida a mi trabajo, absorto en todo lo relacionado con la arquitectura. Si no estaba entrenando, estaba estudiando, y si no estaba estudiando, estaba construyendo.",
        ["Well I must say, it clearly paid off! You guys really did a good job of building up Orthen."] = "Bueno, debo decir que ¡claramente valió la pena! Ustedes realmente hicieron un buen trabajo fortaleciendo a Orthen.",
        ["Ah, you're familiar with our work?"] = "Ah, ¿estás familiarizado con nuestro trabajo?",
        ["Yes, I visited what remains of Orthen on an island to the north-east! Quite a lovely holiday destination, and stunning structures all over."] = "Sí, ¡visité lo que queda de Orthen en una isla al noreste! Un destino de vacaciones bastante encantador y con estructuras impresionantes por todas partes.",
        ["*sigh* Reduced to rubble and ruins. All of our hard work, gone in the blink of an eye. Nonetheless, it pleases me to hear this. I shall have to revisit one day."] = "*suspiro* Reducido a escombros y ruinas. Todo nuestro arduo trabajo desapareció en un abrir y cerrar de ojos. Sin embargo, me agrada escuchar esto. Tendré que volver a visitarlo algún día.",
        ["Do you have any family?"] = "¿Tienes familia?",
        ["Generally, my creed - the Nodon - were tight-knit enough to count as both my family and my friends. I mingled with a few Aughra here and there, but not so much the others."] = "Generalmente, mi credo, los Nodon, eran lo suficientemente unidos como para contarlos como mi familia y mis amigos. Me mezclé con algunos Aughra aquí y allá, pero no tanto con los demás.",
        ["What was life like for you back on Orthen?"] = "¿Cómo era tu vida en Orthen?",
        ["Relaxing. I got to spend my days doing what I loved, creating beautiful buildings, and chiselling away at statues. Easy to say now, but I do wish I cherished those days more in the moment."] = "Relajante. Pude pasar mis días haciendo lo que amaba, creando hermosos edificios y tallando estatuas. Es fácil decirlo ahora, pero desearía apreciar esos días más en este momento.",
        ["Go back."] = "Vuelve atrás.",
        ["How are you doing?"] = "¿Cómo estás?",
        ["Could be better, could be worse. Right now, I'm just taking things day by day. On one hand, I'm not dead. And I managed to escape the clutches of the Roakin, unlike my brothers and sisters out there. On the other hand, I'm currently in hiding, and the only one of my kind left lucid, so our hibernation was all for nothing. All those years wasted. Woken up years later to no pain, yet the control over us still persists."] = "Podría ser mejor, podría ser peor. Ahora mismo estoy tomando las cosas día a día. Por un lado, no estoy muerto. Y logré escapar de las garras de los Roakin, a diferencia de mis hermanos y hermanas. Por otro lado, actualmente estoy escondido y el único de mi especie que quedó lúcido, por lo que nuestra hibernación fue en vano. Todos esos años desperdiciados. Años después nos despertamos sin sentir ningún dolor, pero el control sobre nosotros aún persiste.",
        ["Pain?"] = "¿Dolor?",
        ["Yes, pain. From that horrid stone."] = "Sí, dolor. De esa horrible piedra.",
        ["The Stone of Jas?"] = "¿La Piedra de Jas?",
        ["Of course, what other pain-causing stone would I be on about?"] = "Por supuesto, ¿de qué otra piedra que causa dolor hablaría?",
        ["Sorry, so much has happened since then that it's just old news at this point, you know?"] = "Lo siento, han pasado tantas cosas desde entonces que a estas alturas ya no son más que noticias viejas, ¿sabes?",
        ["I suppose I can get you caught up a bit on recent events..."] = "Supongo que puedo ponerte al día un poco sobre los acontecimientos recientes...",
        ["You start to tell Naressa all about your journeys over Gielinor in excruciating detail."] = "Empiezas a contarle a Naressa todo sobre tus viajes a través de Gielinor con insoportable detalle.",
        ["You tell her about the good times, the bad times, and the inbetween times, ensuring not to leave even the most minute detail out."] = "Le cuentas los buenos, los malos y los intermedios, asegurándote de no omitir ni el más mínimo detalle.",
        ["Naressa begins to yawn, so you hurry up and cut to the chase."] = "Naressa comienza a bostezar, así que te apresuras y vas al grano.",
        ["...And that's how Kerapac saved you all by destroying the stone!"] = "... ¡Y así fue como Kerapac los salvó a todos al destruir la piedra!",
        ["Really? Kerapac? You're not pulling my tail?"] = "¿En serio? ¿Kerapac? ¿No me estás tirando de la cola?",
        ["Yes. He destroyed it using another Elder Artefact, the Mirror. It was all very dramatic."] = "Sí. Lo destruyó usando otro Artefacto Anciano, el Espejo. Fue todo muy dramático.",
        ["That makes one good thing that dastardly Dactyl has done for our race. Thank you for informing me, Player."] = "Eso es algo bueno que el cobarde Dactyl ha hecho por nuestra raza. Gracias por informarme, Player.",
        ["Is there anything you can tell me about the Nodon?"] = "¿Hay algo que puedas contarme sobre el Nodon?",
        ["Is there any information you can tell me about the Nodon?"] = "¿Hay alguna información que puedas darme sobre el Nodon?",
        ["We may not be trying to kill each other, Player, but that doesn't mean I'm thrilled about the prospect of you killing my kin. Well, more like attempting to kill."] = "Puede que no estemos intentando matarnos unos a otros, Player, pero eso no significa que esté emocionado ante la perspectiva de que mates a mis parientes. Bueno, más bien como intentar matar.",
        ["Hey, I'm strong! And powerful! I'm the World Guardian, I'll have you know."] = "¡Oye, soy fuerte! ¡Y poderoso! Soy el Guardián Mundial, te lo haré saber.",
        ["Yes, yes, I'm sure you are. Anyway, to get back to my original point. I entrust you won't use this information to benefit you at their expense."] = "Sí, sí, estoy seguro de que sí. De todos modos, volviendo a mi punto original. Le confío que no utilizará esta información para beneficiarlo a sus expensas.",
        ["Of course not. I promise."] = "Por supuesto que no. Prometo.",
        ["We're not really fighters. As you might be aware, we specialise in construction, design, and building claws-on. When the war against the Roakin started brewing, we fled into hiding rather than fight head-on. *sigh* Of course, you wouldn't be able to guess that looking at how we are today. If you look closely, you can tell that those siege engines aren't even made by us. They are far too fragile, and easy to tamper with. You can find parts of them falling out all over the place! Truly awful work, clearly invented by an amateur."] = "En realidad no somos luchadores. Como ya sabrá, nos especializamos en construcción, diseño y construcción con garras. Cuando la guerra contra los Roakin comenzó a gestarse, huimos a escondernos en lugar de luchar frontalmente. *suspiro* Por supuesto, no serías capaz de adivinar eso viendo cómo estamos hoy. Si miras de cerca, puedes ver que esas máquinas de asedio ni siquiera las fabricamos nosotros. Son demasiado frágiles y fáciles de manipular. ¡Puedes encontrar partes de ellos que se caen por todos lados! Un trabajo realmente horrible, claramente inventado por un aficionado.",
        ["Interesting..."] = "Interesante...",
        ["Leave."] = "Vete.",
        ["Farewell."] = "Adiós.",
        ["It's been nice chatting to a friendly face, Player. I hope to run into you again sometime."] = "Ha sido agradable charlar con una cara amiga, Player. Espero volver a encontrarme contigo alguna vez.",
        ["You're sick!"] = "¡Estás enfermo!",
        ["Hey, my lucky coin! Thank you for returning it to me. It really means a lot, you see. My grandmother passed it down to me and-"] = "¡Oye, mi moneda de la suerte! Gracias por devolvérmelo. Realmente significa mucho, ya ves. Mi abuela me lo pasó y-",
        ["AGH! NO!"] = "¡AGH! ¡NO!",
        ["Oh. I guess I'll just have to find a new one, then."] = "Ah. Entonces supongo que tendré que encontrar uno nuevo.",
        ["Skethzzzzz. Be careful with that!"] = "Skethzzzzz. ¡Cuidado con eso!",
        ["Does this belong to you? I found it on the battlefield."] = "¿Esto te pertenece? Lo encontré en el campo de batalla.",
        ["Ah, so it does! In my haste I must have dropped it. Thank you for returning it to me."] = "¡Ah, así es! En mi prisa debo haberlo dejado caer. Gracias por devolvérmelo.",
        ["I hope you don't mind, but I had a bit of a nosey through it."] = "Espero que no te importe, pero estuve un poco entrometido.",
        ["*sigh* You adventurers, thinking you can just go around reading everyone and anyone's private journals."] = "*suspiro* Ustedes, aventureros, piensan que pueden andar leyendo los diarios privados de todos y cada uno.",
        ["These are used by my kind to fix up our siege machinery, but clearly I have no use for them anymore. Maybe you can find a purpose for them."] = "Los de mi especie los usan para arreglar nuestra maquinaria de asedio, pero claramente ya no los uso. Quizás puedas encontrarles un propósito.",
    },
    ["Nastroth"] = {
        ["Greetings, brave warrior.<br>What can I do for you?"] = "Saludos, valiente guerrero.<br>¿Qué puedo hacer por ti?",
        ["Choose an option:"] = "Elige una opción:",
        ["Tell me about yourself."] = "Háblame de ti.",
        ["Select an Option"] = "Selecciona una opción",
        ["Who are you?"] = "¿Quién eres?",
        ["I am Nastroth. Like my brother, Mandrith, I'm a collector of ancient artefacts. I'm just not as excited about it as he is."] = "Soy Nastroth. Al igual que mi hermano Mandrith, soy coleccionista de artefactos antiguos. Simplemente no estoy tan emocionado como él.",
        ["Why aren't you excited about it?"] = "¿Por qué no estás emocionado por eso?",
        ["Truth be told, I'd much rather be out there with the rest of you, breaking bones and cracking skulls."] = "A decir verdad, preferiría estar ahí fuera con el resto de ustedes, rompiendo huesos y rompiendo cráneos.",
        ["Then why aren't you?"] = "¿Entonces por qué no lo estás?",
        ["My days of battle are over. Now I spend my time here, collecting ancient artefacts."] = "Mis días de batalla han terminado. Ahora paso mi tiempo aquí, coleccionando artefactos antiguos.",
        ["What are these ancient artefacts?"] = "¿Cuáles son estos artefactos antiguos?",
        ["Have fun with that."] = "Diviértete con eso.",
        ["That's not what I do."] = "Eso no es lo que hago.",
        ["Oh. My apologies."] = "Ah. Mis disculpas.",
        ["Let's talk about something else."] = "Hablemos de otra cosa.",
        ["As the blood and sweat of warriors is spilled on the ground, relics of the God Wars are drawn out from the dirt where they were once left forgotten. If you happen to come acoss any of these ancient items, bring them to me or my brother Mandrith near the Pirates' Hideout in the Wilderness, and we will pay you a fair price for them. We don't accept them in noted form, though, remember that. Also, we don't want to buy any weapons or armour."] = "A medida que la sangre y el sudor de los guerreros se derraman en el suelo, las reliquias de las Guerras de Dios se extraen de la tierra donde una vez quedaron olvidadas. Si te encuentras con alguno de estos objetos antiguos, tráelos a mí o a mi hermano Mandrith cerca del escondite de los piratas en Wilderness y te pagaremos un precio justo por ellos. Sin embargo, no los aceptamos en forma anotada, recuérdelo. Además, no queremos comprar armas ni armaduras.",
        ["Who is Mandrith?"] = "¿Quién es Mandrith?",
        ["Why won't you buy weapons or armour?"] = "¿Por qué no compras armas o armaduras?",
        ["They should be used as they were meant to be used, not traded for money. Mandrith and I only collect ancient artefacts."] = "Deben usarse como deben usarse, no intercambiarse por dinero. Mandrith y yo sólo coleccionamos artefactos antiguos.",
        ["Mandrith is my overly excited brother and the one who made me wear this outfit. We share the same purpose, collecting ancient artefacts, but he is located near the Pirates' Hideout in the Wilderness."] = "Mandrith es mi hermano demasiado emocionado y quien me hizo usar este conjunto. Compartimos el mismo propósito, recolectar artefactos antiguos, pero él está ubicado cerca del escondite de los piratas en Wilderness.",
        ["What do you do here?"] = "¿Qué haces aquí?",
        ["I collect ancient artefacts acquired by warriors in return for money."] = "Colecciono artefactos antiguos adquiridos por guerreros a cambio de dinero.",
        ["I'd like to skip my current challenges."] = "Me gustaría saltarme mis desafíos actuales.",
        ["[challenge content]<br><br>Would you like to skip this objective?<br><br>When you Claim Rewards, you won't get XP in this challenge's skill."] = "[challenge content]<br><br>¿Te gustaría saltarte este objetivo?<br><br>Cuando reclamas recompensas, no obtendrás XP en la habilidad de este desafío.",
        ["Cancel"] = "Cancelar",
        ["I want to block XP from specific skills."] = "Quiero bloquear XP de habilidades específicas.",
        ["Block XP from which skill?"] = "¿Bloquear XP de qué habilidad?",
        ["Block XP"] = "Bloquear XP",
        ["Disabled [skill] XP"] = "Deshabilitado [skill] XP",
        ["Give XP"] = "Dar XP",
        ["Enabled [skill] XP"] = "Habilitado [skill] XP",
        ["Let's talk about skill resets."] = "Hablemos de reinicios de habilidades.",
        ["For your own protection, to request a skill reset, you must have an active bank pin."] = "Para tu propia protección, para solicitar un reinicio de habilidad, debes tener un pin bancario activo.",
        ["Okay, what would you like to reset?"] = "Bien, ¿qué te gustaría restablecer?",
        ["What do you want to reset?"] = "¿Qué quieres restablecer?",
        ["Are you sure you want to reset? The process can be quite...rough..."] = "¿Estás seguro de que quieres restablecer? El proceso puede ser bastante... duro...",
        ["You cannot have anything equipped while resetting your stats."] = "No puedes tener nada equipado mientras restableces tus estadísticas.",
        ["You need an empty inventory to reset your stats."] = "Necesitas un inventario vacío para restablecer tus estadísticas.",
        ["You have recently dropped something. Try again later."] = "Recientemente se te ha caído algo. Vuelve a intentarlo más tarde.",
        ["I have already done this for you once, if I do this again I might do permanent damage."] = "Ya hice esto por ti una vez, si lo hago de nuevo podría causar un daño permanente.",
        ["Reset My Skills"] = "Restablecer mis habilidades",
        ["Okay, here we go!"] = "¡Bien, allá vamos!",
        ["You have just advanced -[number] Prayer levels! You have reached level 1."] = "¡Acabas de avanzar niveles -[número] Prayer! Has alcanzado el nivel 1.",
        ["You have just advanced -[number] Constitution levels! You have reached level 10."] = "¡Acabas de avanzar niveles -[número] Constitution! Has alcanzado el nivel 10.",
        ["Don't Reset My Skills"] = "No reinicies mis habilidades",
        ["Are you sure you want to do this? To make sure of this come back and talk to me in 7 days if you're still serious about this."] = "¿Estás seguro de que quieres hacer esto? Para asegurarte de esto, regresa y habla conmigo en 7 días si todavía te tomas esto en serio.",
        ["To cancel this 7 day cooldown, speak to Nastroth again."] = "Para cancelar este tiempo de reutilización de 7 días, habla con Nastroth nuevamente.",
        ["I told you to come back in 7 days. You've still got [number] days to wait. Or did you want something else?"] = "Te dije que volvieras en 7 días. Todavía te quedan [número] días de espera. ¿O querías algo más?",
        ["Select an option"] = "Selecciona una opción",
        ["I don't want to reset"] = "no quiero resetear",
        ["Fine. Begone."] = "Bien. Vete.",
        ["No thanks"] = "No gracias",
        ["I'll see you soon."] = "Te veré pronto.",
        ["You waited 7 days for this. Are you sure you want to go through with this?"] = "Esperaste 7 días para esto. ¿Estás seguro de que quieres seguir adelante con esto?",
        ["You have just advanced -[number] Defence levels! You have reached level 1."] = "¡Acabas de avanzar niveles -[número] Defence! Has alcanzado el nivel 1.",
        ["Never reset my skills."] = "Nunca reinicies mis habilidades.",
        ["Are you sure you want me to stop offering to reset your skills? If you do this, I will NEVER ask about resetting your skills again."] = "¿Estás seguro de que quieres que deje de ofrecerme para restablecer tus habilidades? Si haces esto, NUNCA te preguntaré sobre cómo restablecer tus habilidades nuevamente.",
        ["Never reset your skills?"] = "¿Nunca reinicias tus habilidades?",
        ["Yes, never reset my skills."] = "Sí, nunca reinicies mis habilidades.",
        ["Fair enough, let's never talk of this again."] = "Es justo, no volvamos a hablar de esto nunca más.",
        ["No, let me reset my skills."] = "No, déjame restablecer mis habilidades.",
        ["Nothing."] = "Nada.",
        ["I want to prove I've never used an XP block/reset."] = "Quiero demostrar que nunca he usado un bloqueo/restablecimiento de XP.",
        ["If you choose to enable proof and a player examines your skills, the tooltip for your combat level will display the following information:<br><br>This player has never:<br>- blocked XP<br>- blocked reward XP<br>- reset a specific skill<br><br>Would you like to enable proof?"] = "Si eliges habilitar la prueba y un jugador examina tus habilidades, la información sobre herramientas para tu nivel de combate mostrará la siguiente información:<br><br>Este jugador nunca ha:<br>- bloqueado XP<br>- recompensa bloqueada XP<br>- restablecer una habilidad específica<br><br>¿Te gustaría habilitar la prueba?",
        ["OK"] = "bien",
        ["I no longer want to prove I've never used an XP block/reset."] = "Ya no quiero demostrar que nunca he usado un bloqueo/restablecimiento de XP.",
        ["If a player examines your skills, the tooltip for your combat level currently displays the following information:<br><br>This player has never:<br>- blocked XP<br>- blocked reward XP<br>- reset a specific skill<br><br>Would you like to disable proof?"] = "Si un jugador examina tus habilidades, la información sobre herramientas para tu nivel de combate actualmente muestra la siguiente información:<br><br>Este jugador nunca ha:<br>- bloqueado XP<br>- recompensa bloqueada XP<br>- restablecer una habilidad específica<br><br>¿Te gustaría desactivar la prueba?",
        ["Ah! I see you have found [one/some] of the ancient artefacts my brother and I are seeking."] = "¡Ah! Veo que has encontrado [one/some] de los artefactos antiguos que mi hermano y yo estamos buscando.",
        ["Say, you wouldn't be willing to sell [it/them] to me?"] = "Oye, ¿no estarías dispuesto a venderme [it/them]?",
        ["Sure, I can do that."] = "Claro, puedo hacerlo.",
        ["You sold the [artefact/artefacts] for [number] coins."] = "Vendiste el [artefact/artefacts] por [número] coins.",
        ["If you brought me the item itself, rather than a picture of it, I could give you some money for it."] = "Si me trajeras el artículo en sí, en lugar de una foto, podría darte algo de dinero por él.",
    },
    ["Natasha"] = {
        ["Some of our brothers and sisters can be found around the island. You should try to find them all."] = "Algunos de nuestros hermanos y hermanas se pueden encontrar por toda la isla. Deberías intentar encontrarlos todos.",
    },
    ["Nathan"] = {
        ["One day I'll go on a real adventure, and at the end I'll be swimming in riches! Woo-hoo!"] = "¡Un día emprenderé una verdadera aventura y al final estaré nadando en riquezas! ¡Guau!",
    },
    ["Nathifa"] = {
        ["Hi. Are you one of the returned townspeople?"] = "Hola. ¿Eres uno de los habitantes que regresaron?",
        ["Why, yes. You must be the brave adventurer that Maisa told us was seeking our return."] = "Pues, sí. Debes ser el valiente aventurero que, según nos dijo Maisa, buscaba nuestro regreso.",
        ["I guess so."] = "Supongo que sí.",
        ["Select an Option"] = "Selecciona una opción",
        ["I would like to buy some of your produce."] = "Me gustaría comprar algunos de sus productos.",
        ["Why were you stuck in Menaphos?"] = "¿Por qué estabas atrapado en Menaphos?",
        ["Well, it all started the day that the plagues broke out here."] = "Bueno, todo empezó el día que estallaron las plagas aquí.",
        ["I had gone into Menaphos in the morning to get some flour and chocolate powder and, when it came time for me to return, the gates were shut."] = "Había entrado a Menaphos por la mañana a buscar harina y chocolate en polvo y, cuando llegó el momento de regresar, las puertas estaban cerradas.",
        ["So the guards wouldn't let you back?"] = "¿Entonces los guardias no te dejaron regresar?",
        ["No, not at first. I actually didn't want to return. I didn't want to come down with the plagues so I stayed."] = "No, al principio no. En realidad no quería volver. No quería contraer las plagas, así que me quedé.",
        ["What happened then?"] = "¿Qué pasó entonces?",
        ["Well, word must have traveled back to the slaves that their fellow slaves in Sophanem no longer had to work and so they rioted."] = "Bueno, los esclavos deben haber recibido la noticia de que sus compañeros esclavos en Sophanem ya no tenían que trabajar y por eso se amotinaron.",
        ["That must have been scary."] = "Eso debe haber sido aterrador.",
        ["It was, but Coenus, chief gate keeper of the city, stamped the revolt down fairly fast...and quite brutally."] = "Lo era, pero Coenus, el principal guardián de la puerta de la ciudad, sofocó la revuelta bastante rápido... y de forma bastante brutal.",
        ["If the revolt was stamped out, why are the gates not open?"] = "Si la revuelta fue sofocada, ¿por qué no están abiertas las puertas?",
        ["No, it was only really stopped in the Imperial and Merchant districts of the city. There is still trouble brewing in the Worker and Ports districts."] = "No, en realidad solo se detuvo en los distritos Imperial y Mercantil de la ciudad. Todavía se están gestando problemas en los distritos de Trabajadores y Puertos.",
        ["Now, if you wouldn't mind, I'd rather not dwell any further on the past. Can I interest you in my goods?"] = "Ahora, si no te importa, prefiero no insistir más en el pasado. ¿Puedo interesarle mis productos?",
        ["Yes, please."] = "Sí, por favor.",
        ["No, thanks."] = "No, gracias.",
        ["It was nice to meet you."] = "Fue un placer conocerte.",
    },
    ["Natural historian (Rellekka Hunter area)"] = {
        ["How splendid to see you again. I can't wait to study the statue you found in the desert."] = "Qué espléndido verte de nuevo. No puedo esperar a estudiar la estatua que encontraste en el desierto.",
        ["Are you still looking for yetis?"] = "¿Sigues buscando Yetis?",
        ["Yes, but I think I'll have to give up here. I'm sure the locals could help, but they won't even talk to me. They just mutter about some kind of trials, then set me a bunch of impossible tasks!"] = "Sí, pero creo que tendré que rendirme. Estoy seguro de que los lugareños podrían ayudar, pero ni siquiera me hablan. ¡Simplemente murmuran sobre algún tipo de prueba y luego me imponen un montón de tareas imposibles!",
        ["Perhaps you'll have better luck with the desert statue."] = "Quizás tengas más suerte con la estatua del desierto.",
        ["I do hope so."] = "Eso espero.",
    },
    ["Natural historian"] = {
        ["Hello there and welcome to the Natural History exhibit of the Varrock Museum!"] = "¡Hola y bienvenidos a la exposición de Historia Natural del Museo Varrock!",
        ["Hello. So what is it you do here?"] = "Hola. Entonces, ¿qué haces aquí?",
        ["Well, we look after all of the research in this section."] = "Bueno, nos ocupamos de toda la investigación en esta sección.",
        ["When I'm not doing that, I'm teaching people like yourself about how wonderful the natural world is. Ask me a question and I'll give you an insight into the exciting world of animals."] = "Cuando no hago eso, enseño a personas como tú lo maravilloso que es el mundo natural. Hazme una pregunta y te daré una idea del apasionante mundo de los animales.",
        ["**SELECT AN OPTION**"] = "**SELECCIONA UNA OPCIÓN**",
        ["*North room:*"] = "*Habitación Norte:*",
        ["Tell me about lizards."] = "Háblame de los lagartos.",
        ["Ahh lizards, the scaly carnivores."] = "Ahh lagartos, los carnívoros escamosos.",
        ["If you just follow me to the display case I shall explain all about them."] = "Si me sigues hasta la vitrina, te explicaré todo sobre ellos.",
        ["Contrary to popular belief, even though most lizards have a yellow belly, they are not in fact cowardly. Most Gielinorian lizards will not shy away from a good fight and can be very tough."] = "Contrariamente a la creencia popular, aunque la mayoría de los lagartos tienen el vientre amarillo, en realidad no son cobardes. La mayoría de los lagartos gielinorianos no rehuyen una buena pelea y pueden ser muy duros.",
        ["This is due to a very thick and tough hide, made from thousands of thick scales. Most people who claim to be hunters have a very hard time trying to dispatch lizards."] = "Esto se debe a una piel muy gruesa y resistente, hecha de miles de escamas gruesas. A la mayoría de las personas que dicen ser cazadores les resulta muy difícil acabar con los lagartos.",
        ["In fact, the only people to successfully discern how to kill these tough little squamatas are the five legendary Slayer masters, although we assume they must have some kind of natural predator."] = "De hecho, las únicas personas que lograron discernir con éxito cómo matar a estos pequeños y duros squamatas son los cinco legendarios Slayer masters, aunque asumimos que deben tener algún tipo de depredador natural.",
        ["Interestingly enough, these scales are made from the same substance that your hair is comprised of. This substance is called keratin."] = "Curiosamente, estas escamas están hechas de la misma sustancia que compone tu cabello. Esta sustancia se llama queratina.",
        ["Lizards have a very well developed sense of vision and hearing. Some people think that some lizards have a third eye!"] = "Los lagartos tienen un sentido de la vista y el oído muy desarrollado. ¡Algunas personas piensan que algunos lagartos tienen un tercer ojo!",
        ["A tiny, light-sensitive, transparent structure on top of the head that helps them regulate how long they stay in the sun."] = "Una estructura diminuta, transparente y sensible a la luz en la parte superior de la cabeza que les ayuda a regular cuánto tiempo permanecen al sol.",
        ["This is vital for the cold-blooded lizards who have no means to regulate their internal temperature."] = "Esto es vital para los lagartos de sangre fría que no tienen medios para regular su temperatura interna.",
        ["Like many cold-blooded creatures, if they are subjected to a sudden decrease in temperature, they will become sluggish and sleepy."] = "Como muchas criaturas de sangre fría, si se les somete a una disminución repentina de temperatura, se volverán lentos y somnolientos.",
        ["And this concludes my short lecture on lizards. I hope you've enjoyed yourselves."] = "Y esto concluye mi breve conferencia sobre los lagartos. Espero que lo hayáis disfrutado.",
        ["Tell me about tortoises."] = "Háblame de las tortugas.",
        ["Tell me about the tortoises."] = "Háblame de las tortugas.",
        ["Ahh tortoises, the armoured ancients."] = "Ahh tortugas, los antiguos acorazados.",
        ["The tortoise is a very well defended beast. It uses an armoured shell just like its aquatic cousins the terrapin and the turtle."] = "La tortuga es una bestia muy bien defendida. Utiliza un caparazón blindado al igual que sus primas acuáticas, la galápago y la tortuga.",
        ["Tortoises can vary in size from about as long as your hand to as big as a unicorn. Most land tortoises eat nothing but plants in the wild."] = "Las tortugas pueden variar en tamaño, desde aproximadamente el largo de tu mano hasta el tamaño de un unicornio. La mayoría de las tortugas terrestres no comen más que plantas silvestres.",
        ["Did you know you can tell how old a tortoise is by the number of rings in its shell, just like a tree."] = "¿Sabías que puedes saber la edad de una tortuga por el número de anillos en su caparazón, como un árbol?",
        ["Most land-based tortoises eat plants, feeding on grazing grasses, weeds, leafy greens, flowers, and cabbages."] = "La mayoría de las tortugas terrestres comen plantas y se alimentan de pastos, malezas, verduras de hojas verdes, flores y repollos.",
        ["Tortoises generally live as long as people, and some individual ones are known to have lived longer than 300 years."] = "Las tortugas generalmente viven tanto como las personas, y se sabe que algunas han vivido más de 300 años.",
        ["Because of this, they symbolise longevity within some cultures, such as gnomes who also breed them for battle."] = "Debido a esto, simbolizan la longevidad dentro de algunas culturas, como los gnomos que también los crían para la batalla.",
        ["The oldest tortoise ever recorded was Mibbiwocket, who was presented to the King Healthorg the Great, by the famous explorer Admiral Bake, shortly after its birth."] = "La tortuga más antigua jamás registrada fue Mibbiwocket, quien fue presentada al Rey Healthorg el Grande por el famoso explorador Almirante Bake, poco después de su nacimiento.",
        ["Mibbiwocket is still in the care of the gnomish royal family."] = "Mibbiwocket todavía está al cuidado de la familia real gnoma.",
        ["And this concludes my short lecture on tortoises. I hope you've enjoyed yourselves."] = "Y aquí concluye mi breve conferencia sobre las tortugas. Espero que lo hayáis disfrutado.",
        ["Tell me about dragons."] = "Háblame de dragones.",
        ["Ahh dragons, the mighty hunters of the sky."] = "Ahh dragones, los poderosos cazadores del cielo.",
        ["The dragons of Gielinor are a most confusing species. Standing at approximately twelve feet tall, these imposing predators strike fear into the hearts and minds of most sane folk."] = "Los dragones de Gielinor son una especie muy confusa. Con una altura de aproximadamente tres metros y medio, estos imponentes depredadores infunden miedo en los corazones y las mentes de la mayoría de las personas en su sano juicio.",
        ["However, if you delve a little deeper into their history and lifestyle, a few things stick out as very unusual."] = "Sin embargo, si profundizas un poco más en su historia y estilo de vida, algunas cosas destacan como muy inusuales.",
        ["With most species there is a line, an ancestry if you will, whereby you can track how a creature has come to be in its present form."] = "Con la mayoría de las especies hay una línea, una ascendencia si se quiere, mediante la cual se puede rastrear cómo una criatura ha llegado a su forma actual.",
        ["For instance, you can trace the ancestry of the common house cat back to the same creature that became the sabre-toothed kyatt."] = "Por ejemplo, puedes rastrear la ascendencia del gato doméstico común hasta la misma criatura que se convirtió en el kyatt con dientes de sable.",
        ["However, with the dragon, no such root ancestor can be found."] = "Sin embargo, con el dragón, no se puede encontrar tal ancestro raíz.",
        ["There are many forms of dragon, such as the common coloured and the metallic, or ferrous, dragon."] = "Hay muchas formas de dragón, como el dragón de color común y el dragón metálico o ferroso.",
        ["They colonise many areas of Gielinor, though most notably, sites of ancient battles and small dank caves."] = "Colonizan muchas áreas de Gielinor, aunque sobre todo sitios de antiguas batallas y pequeñas cuevas húmedas.",
        ["Eating habits tend to vary, with the majority of their food being meat. However, it has also been noted that they can consume metals just as easily, with runite being thought of as a delicacy."] = "Los hábitos alimentarios tienden a variar y la mayoría de sus alimentos son carne. Sin embargo, también se ha observado que pueden consumir metales con la misma facilidad, considerándose la runita un manjar.",
        ["Throughout history, dragons have appeared in myth and legend as fearsome adversaries and cunning creatures."] = "A lo largo de la historia, los dragones han aparecido en mitos y leyendas como temibles adversarios y criaturas astutas.",
        ["However, modern evidence does not support this. Most young dragons are largely creatures of instinct with a strong vicious streak."] = "Sin embargo, la evidencia moderna no respalda esto. La mayoría de los dragones jóvenes son en gran medida criaturas instintivas con una fuerte vena viciosa.",
        ["The lifespan of the common dragon is as yet unknown, as no dragon has ever been observed dying of old age."] = "La esperanza de vida del dragón común aún se desconoce, ya que nunca se ha observado que ningún dragón muera de viejo.",
        ["Although, it has been mooted that spontaneous combustion could be considered a natural cause of death for this species."] = "Aunque se ha discutido que la combustión espontánea podría considerarse una causa natural de muerte de esta especie.",
        ["And this concludes my short lecture on dragons. I hope you've enjoyed yourselves."] = "Y esto concluye mi breve conferencia sobre dragones. Espero que lo hayáis disfrutado.",
        ["Tell me about wyverns."] = "Háblame de los wyverns.",
        ["Tell me about the wyverns."] = "Háblame de los wyverns.",
        ["Ahh, wyverns. The extinct lizards."] = "Ahh, wyverns. Los lagartos extintos.",
        ["The wyverns' tale is a sad one. This now extinct species is presumed in some way to be related to the dragon, in that they are both large flying reptiles. The wyvern stands much shorter than the adult dragon and only has two legs as opposed to the dragon's four."] = "La historia de los wyverns es triste. Se presume que esta especie ahora extinta está relacionada de alguna manera con el dragón, ya que ambos son grandes reptiles voladores. El wyvern es mucho más bajo que el dragón adulto y sólo tiene dos patas, a diferencia de las cuatro del dragón.",
        ["Much of the evidence for wyvern behaviour comes from the reconstruction of old bones in the icy mountains of Asgarnia."] = "Gran parte de la evidencia del comportamiento de los wyvern proviene de la reconstrucción de huesos antiguos en las montañas heladas de Asgarnia.",
        ["As most lizards cannot maintain their own body temperature, two theories as to how they managed to survive have been proposed."] = "Como la mayoría de los lagartos no pueden mantener su propia temperatura corporal, se han propuesto dos teorías sobre cómo lograron sobrevivir.",
        ["One is that Asgarnia was at one time a much more temperate climate than it is now. The other is that wyverns could generate fire internally in much the same way as dragons."] = "Una es que Asgarnia alguna vez tuvo un clima mucho más templado de lo que es ahora. La otra es que los wyverns podrían generar fuego internamente de la misma manera que los dragones.",
        ["If they follow the dragon paradigm, then they would have been carnivores, feeding on cows, sheep and other livestock animals."] = "Si siguen el paradigma del dragón, entonces habrían sido carnívoros y se alimentarían de vacas, ovejas y otros animales de ganado.",
        ["How and why the wyverns became extinct is something of a mystery. Though if you consider the theory that the climate of Asgarnia changed suddenly, then this could provide an explanation."] = "Cómo y por qué se extinguieron los wyverns es un misterio. Aunque si consideramos la teoría de que el clima de Asgarnia cambió repentinamente, esto podría proporcionar una explicación.",
        ["There are some inconsistencies in the findings we have for the wyverns, such as the odd wear patterns of some of bones{{Sic}}, which really could only have happened after the creature died."] = "Hay algunas inconsistencias en los hallazgos que tenemos para los wyverns, como los extraños patrones de desgaste de algunos de los huesos {{Sic}}, que en realidad solo pudieron haber sucedido después de que la criatura murió.",
        ["Also the bones we have collected remain a little below room temperature wherever they are kept."] = "Además, los huesos que hemos recolectado permanecen un poco por debajo de la temperatura ambiente dondequiera que se guarden.",
        ["They have also been shown to radiate a very weak magical aura."] = "También se ha demostrado que irradian un aura mágica muy débil.",
        ["I'm sure that in due time, these mysteries will be solved."] = "Estoy seguro de que a su debido tiempo estos misterios se resolverán.",
        ["And this concludes my short lecture on wyverns. I hope you've enjoyed yourselves."] = "Y esto concluye mi breve conferencia sobre los wyverns. Espero que lo hayáis disfrutado.",
        ["*East room:*"] = "*Habitación este:*",
        ["Tell me about snails."] = "Háblame de los caracoles.",
        ["Ahh snails, the gelatinous gastropods."] = "Ahh caracoles, los gasterópodos gelatinosos.",
        ["Snails move like worms by squishing up and stretching out, very, very slowly. They also make a lot of slime, in order to aid moving by reducing friction."] = "Los caracoles se mueven como gusanos apretándose y estirándose, muy, muy lentamente. También producen mucha baba para facilitar el movimiento reduciendo la fricción.",
        ["They also use slime for protection. For instance, snails can use their slime to crawl over razor-blades without being hurt. It also helps keep away dangerous insects like ants."] = "También usan limo como protección. Por ejemplo, los caracoles pueden usar su baba para arrastrarse sobre hojas de afeitar sin sufrir daño. También ayuda a mantener alejados insectos peligrosos como las hormigas.",
        ["When they hide in their shells, snails secrete a special type of slime, which dries to cover the entrance of their shells like a 'trapdoor'. This is called an operculum."] = "Cuando se esconden en sus caparazones, los caracoles secretan un tipo especial de baba, que se seca para cubrir la entrada de sus caparazones como una \"trampilla\". Esto se llama opérculo.",
        ["The snails of Morytania are the most malignant molluscs ever to have been studied."] = "Los caracoles de Morytania son los moluscos más malignos jamás estudiados.",
        ["They are broken down into two distinct species: achatina acidia and achatina acidia giganteus or, as they are more commonly known, the acid-spitting snail and the giant acid-spitting snail."] = "Se dividen en dos especies distintas: achatina acidia y achatina acidia giganteus o, como se les conoce más comúnmente, el caracol que escupe ácido y el caracol gigante que escupe ácido.",
        ["Both of these varieties are voracious carnivores, using their mutated mouthpieces to spit a glob of powerful acid to kill their foe."] = "Ambas variedades son carnívoros voraces y usan sus boquillas mutadas para escupir una bola de ácido poderoso para matar a su enemigo.",
        ["They then simply have to wait, whilst the digestive juices make short work of the poor creature. Then, they simply slurp up what remains."] = "Luego simplemente tienen que esperar, mientras los jugos digestivos acaban con la pobre criatura. Luego, simplemente sorben lo que queda.",
        ["How these strange creatures came to be is still something of a mystery. The most prevalent theory suggests that they mutated, as a reaction to an 'as yet unknown' pollutant that has appeared in the swamps."] = "Cómo surgieron estas extrañas criaturas sigue siendo un misterio. La teoría más extendida sugiere que mutaron como reacción a un contaminante \"aún desconocido\" que apareció en los pantanos.",
        ["The local populace has capitalised on the appearance of these strange species, using their shells to fashion a rudimentary helm that is fairly resistant to the snails acid."] = "La población local ha aprovechado la apariencia de estas extrañas especies, utilizando sus caparazones para crear un yelmo rudimentario que es bastante resistente al ácido de los caracoles.",
        ["Other known uses of snail by-products include a tasty local delicacy and a fireproof oil."] = "Otros usos conocidos de los subproductos del caracol incluyen un sabroso manjar local y un aceite ignífugo.",
        ["And this concludes my short lecture on snails. I hope you've enjoyed yourselves."] = "Y aquí concluye mi breve conferencia sobre los caracoles. Espero que lo hayáis disfrutado.",
        ["Tell me about monkeys."] = "Háblame de los monos.",
        ["Ahh monkeys, the simian collective."] = "Ahh monos, el colectivo de simios.",
        ["A monkey is a member of either of two known groupings of simian primates. These two known groupings are the Karamja monkeys and the 'harmless' monkeys."] = "Un mono es miembro de cualquiera de dos grupos conocidos de primates simios. Estos dos grupos conocidos son los monos Karamja y los monos \"inofensivos\".",
        ["Because of their similarity to monkeys, apes such as chimpanzees and gibbons are often called monkeys by accident."] = "Debido a su similitud con los monos, a los simios como los chimpancés y los gibones a menudo se les llama monos por accidente.",
        ["Though some natural historians don't consider them to be monkeys. Also, a few monkey species have the word 'ape' in their common name."] = "Aunque algunos historiadores naturales no los consideran monos. Además, algunas especies de monos tienen la palabra \"simio\" en su nombre común.",
        ["The Karamja monkeys are rumoured to be fairly cunning and intelligent creatures, although rumours that they have learned human speech is anecdotal at best."] = "Se rumorea que los monos Karamja son criaturas bastante astutas e inteligentes, aunque los rumores de que han aprendido el habla humana son, en el mejor de los casos, anecdóticos.",
        ["In appearance, they stand much shorter than a human and tend to move in a hunched fashion. Karamja monkeys also sport a red mohawk, though it is unknown whether this is an affectation or not."] = "En apariencia, son mucho más bajos que un humano y tienden a moverse encorvados. Los monos Karamja también lucen un mohawk rojo, aunque se desconoce si se trata de una afectación o no.",
        ["They are very fond of bananas and bitternuts, eating them in huge quantities whenever they can get their paws on them."] = "Les gustan mucho los plátanos y las nueces amargas y los comen en grandes cantidades siempre que pueden ponerles las patas encima.",
        ["The harmless monkeys of Mos Le'Harmless are a very similar, but in some ways entirely different, breed. They stand roughly the same size but are a lighter colour."] = "Los monos inofensivos de Mos Le'Harmless son una raza muy similar, pero en algunos aspectos completamente diferente. Son aproximadamente del mismo tamaño pero son de un color más claro.",
        ["Interestingly, Karamaja{{Sic}} monkeys have a deep dislike of seaweed, though this may stem from the actions of a number of irresponsible people."] = "Curiosamente, a los monos Karamaja{{Sic}} les desagradan profundamente las algas, aunque esto puede deberse a las acciones de varias personas irresponsables.",
        ["And this concludes my short lecture on monkeys. I hope you've enjoyed yourselves."] = "Y esto concluye mi breve conferencia sobre los monos. Espero que lo hayáis disfrutado.",
        ["Tell me about sea slugs."] = "Háblame de las babosas marinas.",
        ["Tell me about the sea slugs."] = "Háblame de las babosas marinas.",
        ["Ahh sea slugs, the cute crustaceans."] = "Ahh babosas de mar, los lindos crustáceos.",
        ["The term 'sea slug' is something of a misnomer. Whilst these small creatures have a soft body like that of a slug, they also possess a very hard shell like a snail."] = "El término \"babosa de mar\" es un nombre poco apropiado. Si bien estas pequeñas criaturas tienen un cuerpo blando como el de una babosa, también poseen un caparazón muy duro como el de un caracol.",
        ["Very little is actually known about the sea slug, as we have, as yet, been unable to procure a sample for observation and study."] = "En realidad, se sabe muy poco sobre la babosa marina, ya que hasta el momento no hemos podido conseguir una muestra para observación y estudio.",
        ["For some reason all expeditions we have sent have either vanished mysteriously, or those on the expedition have sent letters back announcing their desire to leave the Museum and go on to other things."] = "Por alguna razón, todas las expediciones que hemos enviado han desaparecido misteriosamente, o aquellos en la expedición han enviado cartas anunciando su deseo de abandonar el Museo y dedicarse a otras cosas.",
        ["It is presumed that the species is native to the very deep waters around the eastern Ardougne coastline."] = "Se presume que la especie es nativa de las aguas muy profundas alrededor de la costa oriental de Ardougne.",
        ["There must be some natural resources in the area that the sea slugs are using, as the underwater habitat there is much the same around many coastal areas on Gielinor."] = "Debe haber algunos recursos naturales en el área que utilizan las babosas marinas, ya que el hábitat submarino es muy similar en muchas áreas costeras de Gielinor.",
        ["Through looking at similar species we have determined that the sea slug is a harmless little creature. It spends much of its life grazing on seaweed and other plant life."] = "Al observar especies similares, hemos determinado que la babosa marina es una pequeña criatura inofensiva. Pasa gran parte de su vida pastando algas y otras plantas.",
        ["There are reports that these reclusive animals have two large fangs at their front, though this is assumed to be either for decorative or defensive purposes."] = "Hay informes de que estos animales solitarios tienen dos grandes colmillos en la parte delantera, aunque se supone que tienen fines decorativos o defensivos.",
        ["If they do follow the same pattern as other similar creatures, the shell will be nigh on impervious to most attacks. The exposed soft skin may have a number of nematocysts, or stinging organs, similar to jellyfish."] = "Si siguen el mismo patrón que otras criaturas similares, el caparazón será casi impermeable a la mayoría de los ataques. La piel blanda expuesta puede tener varios nematocistos u órganos urticantes, similares a los de las medusas.",
        ["It is typical of prey animals such as these to develop some kind of unique defence mechanism that allows them to survive."] = "Es típico de animales de presa como estos desarrollar algún tipo de mecanismo de defensa único que les permita sobrevivir.",
        ["If only we could acquire one for study. I'm sure we would find this mechanism to be truly unique."] = "Si tan solo pudiéramos adquirir uno para estudiar. Estoy seguro de que este mecanismo nos parecerá verdaderamente único.",
        ["And this concludes my short lecture on sea slugs. I hope you've enjoyed yourselves."] = "Y esto concluye mi breve conferencia sobre las babosas marinas. Espero que lo hayáis disfrutado.",
        ["Tell me about snakes."] = "Háblame de las serpientes.",
        ["Ahh snakes, the slithering squamata."] = "Ahh serpientes, las escamatas deslizantes.",
        ["Serpentes, or ophidia, is the suborder under squamata that snakes belong to, like a big family."] = "Serpentes, u ofidios, es el suborden de squamata al que pertenecen las serpientes, como una gran familia.",
        ["Unlike lizards, snakes have no limbs whatsoever; not that this limits them. Snakes live in or near every habitat in the world."] = "A diferencia de los lagartos, las serpientes no tienen extremidades; No es que esto los limite. Las serpientes viven en o cerca de todos los hábitats del mundo.",
        ["Found in nice tropical forests, temperate latitudes and even in the ocean - some have adapted specialised stomach juices that they inject into their prey as venom, while others prefer to grab and crush their food."] = "Se encuentran en bonitos bosques tropicales, latitudes templadas e incluso en el océano; algunos han adaptado jugos estomacales especializados que inyectan en sus presas como veneno, mientras que otros prefieren agarrar y triturar su comida.",
        ["While others still are fast hunters who use speed and strength to overcome their prey."] = "Mientras que otros siguen siendo cazadores rápidos que usan la velocidad y la fuerza para vencer a sus presas.",
        ["The sense of smell in snakes has been enhanced in an amazing way. With most animals, like you and me, tiny particles are filtered through the nose."] = "El sentido del olfato en las serpientes se ha mejorado de una manera asombrosa. En la mayoría de los animales, como tú y como yo, las partículas diminutas se filtran a través de la nariz.",
        ["However, instead of using just their nose, these animals use their tongues as well. When a lizard or a snake wants to smell it's surroundings, it will wave its tongue around and pick up the particles in the air."] = "Sin embargo, en lugar de usar solo la nariz, estos animales también usan la lengua. Cuando un lagarto o una serpiente quiere oler su entorno, agitará su lengua y recogerá las partículas del aire.",
        ["The tongue then returns to the mouth and the tips of the tongue are pushed up against two tiny pits in the roof of the snake's mouth."] = "La lengua luego regresa a la boca y las puntas de la lengua se empujan contra dos pequeños hoyos en el paladar de la serpiente.",
        ["Since these pits are split apart from each other, the tongue itself also has to split. This is why snakes have forked tongues."] = "Dado que estos hoyos están separados entre sí, la lengua misma también tiene que dividirse. Por eso las serpientes tienen la lengua bífida.",
        ["So the next time you see a snake sticking it's tongue out at you, remember, it's sniffing the air, not trying to bite you."] = "Entonces, la próxima vez que veas una serpiente sacándote la lengua, recuerda, está olfateando el aire, no tratando de morderte.",
        ["And this concludes my short lecture on snakes. I hope you've enjoyed yourselves."] = "Y esto concluye mi breve conferencia sobre las serpientes. Espero que lo hayáis disfrutado.",
        ["*South room:*"] = "*Habitación Sur:*",
        ["Tell me about natural history."] = "Háblame de historia natural.",
        ["Well, the field of natural history covers a wide range of sciences."] = "Bueno, el campo de la historia natural cubre una amplia gama de ciencias.",
        ["So we use biology, the study of living things, botany, the study of plants and zoology, the study of animals."] = "Entonces utilizamos la biología, el estudio de los seres vivos, la botánica, el estudio de las plantas y la zoología, el estudio de los animales.",
        ["Though the field is growing all the time and we're also using techniques from magic, astrology and numerology."] = "Aunque el campo está creciendo todo el tiempo y también utilizamos técnicas de magia, astrología y numerología.",
        ["A person interested in natural history is known as a naturalist."] = "Una persona interesada en la historia natural se conoce como naturalista.",
        ["Tell me about terrorbirds."] = "Háblame de los pájaros del terror.",
        ["Tell me about the terrorbirds."] = "Háblame de los pájaros del terror.",
        ["Ahh terrorbirds, the fastest bird on two legs."] = "Ahh terrorbirds, el pájaro más rápido sobre dos patas.",
        ["Terrorbirds live in nomadic groups of between five and fifty birds that often travel together with other grazing animals."] = "Los pájaros del terror viven en grupos nómadas de entre cinco y cincuenta aves que a menudo viajan junto con otros animales que pastan.",
        ["They mainly feed on seeds and other plants. They also eat insects such as locusts if they can catch them."] = "Se alimentan principalmente de semillas y otras plantas. También comen insectos como langostas si pueden atraparlas.",
        ["They have no teeth to chew with, so they swallow pebbles that help to grind the swallowed foods in the gizzard."] = "No tienen dientes para masticar, por lo que tragan guijarros que ayudan a triturar los alimentos ingeridos en la molleja.",
        ["They can go without water for a long time, exclusively living off the water in the plants. However, they enjoy water and frequently take baths when they can."] = "Pueden pasar mucho tiempo sin agua, viviendo exclusivamente del agua de las plantas. Sin embargo, disfrutan del agua y se bañan con frecuencia cuando pueden.",
        ["Terrorbirds are known to eat almost anything, particularly in captivity, where opportunity is increased."] = "Se sabe que los pájaros del terror comen casi cualquier cosa, especialmente en cautiverio, donde aumentan las oportunidades.",
        ["Terrorbirds usually weigh a little less than a small unicorn. The feathers of adult males are mostly green, with some white on the wings and tail."] = "Los pájaros del terror suelen pesar un poco menos que un pequeño unicornio. Las plumas de los machos adultos son en su mayoría verdes, con algo de blanco en las alas y la cola.",
        ["There are claws on two of the wings' fingers and their strong legs have no feathers. The bird stands on two toes, with the bigger one resembling a hoof. Its feet have no claws."] = "Hay garras en dos de los dedos de las alas y sus fuertes patas no tienen plumas. El pájaro se apoya en dos dedos, el más grande se asemeja a una pezuña. Sus pies no tienen garras.",
        ["This is an adaptation unique to terrorbirds that appears to aid in running. Their legs are powerful enough to kill even large animals."] = "Esta es una adaptación exclusiva de los terrorbirds que parece ayudar a correr. Sus patas son lo suficientemente poderosas como para matar incluso animales grandes.",
        ["The gnomes in particular, prize the terrorbird for its fast running speed, using them as mounts whenever possible."] = "Los gnomos en particular valoran al pájaro terrorífico por su rápida velocidad y lo utilizan como montura siempre que es posible.",
        ["There are a number of recorded incidents of people being attacked and killed. Big males can be very territorial and aggressive, and can attack and kick very powerfully with their legs."] = "Hay varios incidentes registrados de personas atacadas y asesinadas. Los machos grandes pueden ser muy territoriales y agresivos, y pueden atacar y patear muy poderosamente con las piernas.",
        ["A terrorbird is so fast, it can easily outrun any human athlete."] = "Un pájaro terrorífico es tan rápido que puede dejar atrás fácilmente a cualquier atleta humano.",
        ["And this concludes my short lecture on terrorbirds. I hope you've enjoyed yourselves."] = "Y esto concluye mi breve conferencia sobre los pájaros terroristas. Espero que lo hayáis disfrutado.",
        ["Tell me about the Kalphite Queen."] = "Cuéntame sobre el Kalphite Queen.",
        ["Ahh kalphites, the insectoid eating machines."] = "Ahh kalfitas, las máquinas devoradoras de insectoides.",
        ["The kalphites, otherwise known as the kalphiscarabeinae, are perhaps the largest species of insect on the face of Gielinor. Their queen is called kalphiscarabeinae pasha."] = "Los kalphites, también conocidos como kalphiscarabeinae, son quizás la especie de insecto más grande en the face de Gielinor. Su reina se llama kalphiscarabeinae pasha.",
        ["Most of the early documentation and research on this fearsome predatory species was performed by the noted bug hunter Iqbar Ali-Abdula."] = "La mayor parte de la documentación e investigación iniciales sobre esta temible especie depredadora fue realizada por el destacado cazador de insectos Iqbar Ali-Abdula.",
        ["This, of course, was before he was driven insane by his research and ran off into the desert, screaming."] = "Esto, por supuesto, fue antes de que su investigación lo volviera loco y huyera hacia el desierto, gritando.",
        ["Kalphites are related to beetles and scorpions; they are mainly green in colour. Some have remarkable antennae which can detect the slightest movement. Their carapace is composed of armoured plates called lamellae."] = "Los calfitos están relacionados con los escarabajos y los escorpiones; son principalmente de color verde. Algunos tienen antenas notables que pueden detectar el más mínimo movimiento. Su caparazón está compuesto por placas blindadas llamadas laminillas.",
        ["This shell can be compressed into a ball or fanned out like leaves, in order to sense odours. The front legs are adapted for digging the enormous tunnel systems that serve as their nests."] = "Esta cáscara se puede comprimir hasta formar una bola o desplegarse como hojas para detectar olores. Las patas delanteras están adaptadas para cavar los enormes sistemas de túneles que les sirven de nidos.",
        ["They exist in a caste-based society, with the soft shelled larvae at the bottom, up through the workers, soldiers and finally the queen."] = "Existen en una sociedad basada en castas, con las larvas de caparazón blando en la parte inferior, pasando por los trabajadores, los soldados y finalmente la reina.",
        ["Voracious carnivores, a pack of adult workers can strip the flesh from a full grown camel in a matter of seconds, leaving nothing but a few bones and strips of fur for other scavengers to pick over."] = "Carnívoros voraces, un grupo de trabajadores adultos pueden arrancar la carne de un camello adulto en cuestión de segundos, dejando nada más que unos pocos huesos y tiras de pelo para que otros carroñeros los recojan.",
        ["They typically live in large nests marked by the rock hard pillars found in hot, arid deserts, such as the one south-west of Al Kharid, which rise out of the sands like the tombs of desert pharaohs."] = "Por lo general, viven en grandes nidos marcados por pilares duros como rocas que se encuentran en desiertos cálidos y áridos, como el que se encuentra al suroeste de Al Kharid, que se elevan sobre las arenas como las tumbas de los faraones del desierto.",
        ["Indeed, there is some relationship between the Kalphite Queen and the desert god Scabaras, but no one is really sure what."] = "De hecho, existe cierta relación entre Kalphite Queen y el dios del desierto Scabaras, pero nadie está realmente seguro de qué.",
        ["During the early part of the fourth age, Scabaras proclaimed himself omnipotent and outlawed worship of all other gods save him."] = "Durante la primera parte de la cuarta edad, Scabaras se proclamó omnipotente y prohibió el culto a todos los demás dioses excepto él.",
        ["When the people eventually revolted against his repressive rule and banished Scabaras, it is said his blood washed over the scarabs and transformed them into the kalphites we know today."] = "Cuando el pueblo finalmente se rebeló contra su gobierno represivo y desterró a Scabaras, se dice que su sangre bañó a los escarabajos y los transformó en los calfitos que conocemos hoy.",
        ["Of course, any right-minded scientist discounts these myths as mere stories, with no historical basis in fact."] = "Por supuesto, cualquier científico con mentalidad correcta descarta estos mitos como meras historias, sin ninguna base histórica en los hechos.",
        ["And this concludes my short lecture on kalphites. I hope you've enjoyed yourselves."] = "Y esto concluye mi breve conferencia sobre los calfitos. Espero que lo hayáis disfrutado.",
        ["*West room:*"] = "*Habitación oeste:*",
        ["Tell me about camels."] = "Háblame de los camellos.",
        ["Tell me about the camels."] = "Háblame de los camellos.",
        ["Ahh camels, the ships of the desert."] = "Ahh camellos, los barcos del desierto.",
        ["The term camel refers to either of the two known species of camelid."] = "El término camello se refiere a cualquiera de las dos especies conocidas de camélidos.",
        ["There is the bactrian, which has two humps and can be found throughout Al Kharid. It also refers to the Ugthanki, or one-humped camel."] = "Está el bactriano, que tiene dos jorobas y se puede encontrar en todo Al Kharid. También se refiere al Ugthanki, o camello de una joroba.",
        ["Camels are ill-tempered beasts at the best of times, requiring a great deal of time and effort to tame."] = "Los camellos son bestias de mal genio en el mejor de los casos y requieren mucho tiempo y esfuerzo para domesticarlos.",
        ["This would explain why used camel salesmen are in such a hurry to be rid of them."] = "Esto explicaría por qué los vendedores de camellos usados tienen tanta prisa por deshacerse de ellos.",
        ["In the wild, camels have been known to lie in wait and ambush hapless travellers, before devouring them."] = "En la naturaleza, se sabe que los camellos acechan y tienden emboscadas a los desventurados viajeros antes de devorarlos.",
        ["This is quite surprising, as most domestic camels are happy eating nothing but vegetables."] = "Esto es bastante sorprendente, ya que la mayoría de los camellos domésticos son felices comiendo nada más que verduras.",
        ["Camel milk is much more nutritious than cow milk and goes well in the strong desert drink akin to tea."] = "La leche Camel es mucho más nutritiva que la leche de vaca y combina bien con la bebida fuerte del desierto similar al té.",
        ["Another useful camel by-product is dung. Their dung is very dry, due to the highly efficient metabolism of the camel."] = "Otro subproducto útil del camello es el estiércol. Su estiércol es muy seco debido al metabolismo altamente eficiente del camello.",
        ["Scientific research has also shown that chilli has a disastrous effect on a camel's digestive system, which produces toxic dung."] = "La investigación científica también ha demostrado que el chile tiene un efecto desastroso en el sistema digestivo de los camellos, que produce estiércol tóxico.",
        ["And this concludes my short lecture on camels. I hope you've enjoyed yourselves."] = "Y con esto concluye mi breve conferencia sobre los camellos. Espero que lo hayáis disfrutado.",
        ["Tell me about leeches."] = "Háblame de las sanguijuelas.",
        ["Ahh leeches, the haemophagic parasites."] = "Ahh sanguijuelas, los parásitos hemofágicos.",
        ["Leeches are fascinating creatures and are very similar to worms in most respects."] = "Las sanguijuelas son criaturas fascinantes y muy similares a los gusanos en muchos aspectos.",
        ["They like to inhabit streams, rivers and seas, but their preference is for stagnant pools of water."] = "Les gusta habitar arroyos, ríos y mares, pero prefieren los charcos de agua estancada.",
        ["One of the most common misconceptions is that all leeches feed on blood."] = "Uno de los conceptos erróneos más comunes es que todas las sanguijuelas se alimentan de sangre.",
        ["In fact, very, very few leeches are parasitic bloodsucking animals."] = "De hecho, muy, muy pocas sanguijuelas son animales parásitos chupadores de sangre.",
        ["Most leeches are meat eaters, feeding on a variety of invertebrates such as worms, snails, insect larvae and snails."] = "La mayoría de las sanguijuelas comen carne y se alimentan de una variedad de invertebrados como gusanos, caracoles, larvas de insectos y caracoles.",
        ["Those that do feed on blood have developed an amazing method of doing so. Firstly they latch onto the skin using a ring of tiny teeth, before injecting their prey with an anaesthetic."] = "Aquellos que se alimentan de sangre han desarrollado un método sorprendente para hacerlo. En primer lugar, se adhieren a la piel con un anillo de dientes diminutos, antes de inyectar un anestésico a sus presas.",
        ["Then they bite into the skin using a Y-shaped mouthpiece and introducing a chemical that stops the blood from clotting."] = "Luego muerden la piel usando una boquilla en forma de Y e introduciendo una sustancia química que impide que la sangre se coagule.",
        ["They will then feed until they are completely full, sometimes doubling in size!"] = "Luego se alimentarán hasta que estén completamente llenos, ¡a veces hasta duplicar su tamaño!",
        ["Most leeches are very small, measuring no more than the length of your middle finger. An exception to these are the leeches of Morytania, which can reach the size of a dog."] = "La mayoría de las sanguijuelas son muy pequeñas y no miden más que la longitud del dedo medio. Una excepción son las sanguijuelas de Morytania, que pueden alcanzar el tamaño de un perro.",
        ["They are much more mobile than their smaller cousins and are able to jump rather high when attacking."] = "Son mucho más móviles que sus primos más pequeños y pueden saltar bastante alto cuando atacan.",
        ["Quite how these leeches came to be so big is something of a mystery."] = "Cómo estas sanguijuelas llegaron a ser tan grandes es un misterio.",
        ["All we can assume is that there is some kind of environmental influence, which has governed their immense growth."] = "Todo lo que podemos suponer es que existe algún tipo de influencia ambiental que ha gobernado su inmenso crecimiento.",
        ["And this concludes my short lecture on leeches. I hope you've enjoyed yourselves."] = "Y con esto concluye mi breve conferencia sobre sanguijuelas. Espero que lo hayáis disfrutado.",
        ["Tell me about moles."] = "Háblame de los lunares.",
        ["Ahh moles, the mammalian mountain makers."] = "Ahh topos, los mamíferos hacedores de montañas.",
        ["Now, moles are small mammals of the talpidae family. These subterranean burrowers mainly live on a diet of slugs, snails and insects."] = "Ahora bien, los topos son pequeños mamíferos de la familia talpidae. Estos excavadores subterráneos se alimentan principalmente de babosas, caracoles e insectos.",
        ["They vary greatly in habitat and can be found in almost every part of Gielinor.  {{Sic}}Some species have even known to be aquatic."] = "Varían mucho en hábitat y se pueden encontrar en casi todas las partes de Gielinor.  {{Sic}}Incluso se sabe que algunas especies son acuáticas.",
        ["Male moles are known as boars with the females called sows. Should you come across a group of moles, you would call them a labour."] = "Los topos machos se conocen como verracos y las hembras se llaman cerdas. Si te encontraras con un grupo de topos, los llamarías mano de obra.",
        ["Moles are considered to be an agricultural pest in most places, digging up the ground and leaving molehills all over the place."] = "Los topos se consideran una plaga agrícola en la mayoría de los lugares, excavan el suelo y dejan toperas por todas partes.",
        ["This has been highlighted in Falador by Wyson the Gardener who, after using some Malignus Mortifer's Super Ultra Flora Growth Potion, managed to create Gielinor's only known species of giant mole."] = "Esto ha sido destacado en Falador por Wyson the Gardener quien, después de usar la poción de crecimiento Super Ultra Flora de Malignus Mortifer, logró crear la única especie conocida de topo gigante de Gielinor.",
        ["This fearsome beast has huge claws, wicked teeth and a penchant for shiny objects. It is a very tough animal with a thick protective hide and an ill temperament."] = "Esta temible bestia tiene enormes garras, dientes malvados y predilección por los objetos brillantes. Es un animal muy duro, con una piel protectora gruesa y de mal temperamento.",
        ["That said, they do benefit the soil by aerating and tilling it, adding to its fertility. Contrary to popular belief, moles don't eat plant roots."] = "Dicho esto, benefician el suelo al airearlo y labrarlo, lo que aumenta su fertilidad. Contrariamente a la creencia popular, los topos no comen raíces de plantas.",
        ["And this concludes my short lecture on moles. I hope you've enjoyed yourselves."] = "Y con esto concluye mi breve conferencia sobre los lunares. Espero que lo hayáis disfrutado.",
        ["Tell me about penguins."] = "Háblame de los pingüinos.",
        ["Ahh penguins, the cunning birds of the sea."] = "Ahh pingüinos, las astutas aves del mar.",
        ["This often-maligned aquatic bird is known to be native to the ice fields of Etceteria, although they have been known to live as far as the fields of Lumbridge."] = "Se sabe que esta ave acuática a menudo difamada es nativa de los campos de hielo de Etceteria, aunque se sabe que vive hasta los campos de Lumbridge.",
        ["These aquatic birds seem to spend the majority of their time eating and fostering their young."] = "Estas aves acuáticas parecen pasar la mayor parte de su tiempo comiendo y cuidando a sus crías.",
        ["Unlike most animals that prefer cold climes, these sphenisciformes work very well together in large groups, by watching for predators and caring for each other's young."] = "A diferencia de la mayoría de los animales que prefieren climas fríos, estos esfenisciformes trabajan muy bien juntos en grupos grandes, observando a los depredadores y cuidando a las crías de los demás.",
        ["For creatures with such small brains, they do seem to have a disproportionate capacity for forward thinking and planning. As this serves no natural purpose, scholars are divided as to how this evolved."] = "Para criaturas con cerebros tan pequeños, parecen tener una capacidad desproporcionada para pensar y planificar con anticipación. Como esto no tiene ningún propósito natural, los estudiosos están divididos sobre cómo evolucionó.",
        ["Their diet consists mainly of fish, squid and a small shrimp-like creature called krill. However, some have developed a taste for the mushrooms that grow around fairy rings."] = "Su dieta se compone principalmente de pescado, calamares y una pequeña criatura parecida a un camarón llamada krill. Sin embargo, algunos han desarrollado un gusto por los hongos que crecen alrededor de los anillos de hadas.",
        ["Penguins primarily rely on their vision while hunting. What we don't know is how penguins locate prey in the darkness, or at great depths."] = "Los pingüinos dependen principalmente de su visión cuando cazan. Lo que no sabemos es cómo los pingüinos localizan a sus presas en la oscuridad o a grandes profundidades.",
        ["Some theories suggest that penguins are helped by some sort of extra sensory perception; perhaps even precognition."] = "Algunas teorías sugieren que a los pingüinos les ayuda algún tipo de percepción sensorial adicional; tal vez incluso precognición.",
        ["Penguins spend a long time going without food when they are breeding. In fact, they won't even leave their nests if they can help it."] = "Los pingüinos pasan mucho tiempo sin comer cuando se reproducen. De hecho, ni siquiera abandonarán sus nidos si pueden evitarlo.",
        ["Fortunately, most penguins build up a layer of fat to keep them warm and provide energy until the moult is over."] = "Afortunadamente, la mayoría de los pingüinos acumulan una capa de grasa para mantenerse calientes y proporcionarles energía hasta que termina la muda.",
        ["And this concludes my short lecture on penguins. I hope you've enjoyed yourselves."] = "Y esto concluye mi breve conferencia sobre los pingüinos. Espero que lo hayáis disfrutado.",
        ["That's enough education for one day."] = "Ya es suficiente educación por un día.",
        ["Nonsense! There's always room for more. And remember, science isn't dull!"] = "¡Tonterías! Siempre hay espacio para más. Y recuerde, ¡la ciencia no es aburrida!",
        ["Hello again, sir, how can I help you on this fine day?"] = "Hola de nuevo señor, ¿en qué puedo ayudarle en este lindo día?",
    },
    ["Navigator Jemi"] = {
        ["Hi the- Oh, good Guthix...it's you! I mean, it's really you! I am such a fan! I've been following your adventures for - well, -forever! I'm an adventurer myself. Well, okay, I'm not a proper adventurer - certainly not of your calibre - but I've been on a couple of adventures. Okay, one. Okay, so I daydreamed about an adventure, but it's something I really want to do! I'm Jemi by the way... I..erm...already know your name."] = "Hola... Oh, buen Guthix... ¡eres tú! Quiero decir, ¡eres realmente tú! ¡Soy un gran admirador! He estado siguiendo tus aventuras durante... bueno, ¡desde siempre! Yo también soy un aventurero. Bueno, está bien, no soy un aventurero propiamente dicho, ciertamente no de tu calibre, pero he estado en un par de aventuras. Vale, uno. Vale, soñé despierto con una aventura, ¡pero es algo que realmente quiero hacer! Por cierto, soy Jemi... Yo... ejem... ya sé tu nombre.",
        ["Hi, it's so cool to see you again!"] = "Hola, ¡es genial verte de nuevo!",
        ["How are your adventures going?"] = "¿Cómo van tus aventuras?",
        ["Well, I was about to go on one...but I could use a little advice if you're up for it. I'll give you some of the treasure I find as a thank-you!"] = "Bueno, estaba a punto de participar en uno... pero me vendría bien un pequeño consejo si te apetece. ¡Te daré parte del tesoro que encuentre como agradecimiento!",
        ["Sure, ask away."] = "Claro, pregunta.",
        ["*Jemi asks three of her questions: *"] = "*Jemi hace tres de sus preguntas: *",
        ["*At each answer Jemi may respond with any one of the following: *"] = "*A cada respuesta, Jemi puede responder con cualquiera de las siguientes opciones: *",
        ["Good idea!"] = "¡Buena idea!",
        ["Gotcha! Thanks. One more...quick thing?"] = "¡Te tengo! Gracias. Una cosa más... ¿rápida?",
        ["Hrm... Are you sure? Wait, of course you're sure, you know your stuff! Thanks for the advice!"] = "Hrm... ¿Estás seguro? Espera, por supuesto que estás seguro, ¡sabes lo que haces! ¡Gracias por el consejo!",
        ["Is that right? It sounds... No, I'm sure it's right. You're never wrong!"] = "¿Es así? Suena... No, estoy seguro de que es correcto. ¡Nunca te equivocas!",
        ["Mhm, yep, got that. Just let me write that down...how do I spell that?"] = "Mhm, sí, lo tengo. Sólo déjame escribirlo... ¿cómo se deletrea?",
        ["Of course! Brilliant, thanks!"] = "¡Por supuesto! Brillante, gracias!",
        ["Oh, yeah that makes sense! Thanks!"] = "¡Oh, sí, eso tiene sentido! ¡Gracias!",
        ["Oh, okay. I think I can handle that."] = "Oh, está bien. Creo que puedo manejar eso.",
        ["*After all questions are answered Jemi may respond with any one of the following: *"] = "*Una vez respondidas todas las preguntas, Jemi puede responder con cualquiera de las siguientes opciones: *",
        ["Okay, that's everything. I can do it... With your advice, I can brace the terrors that await me. Wish me luck."] = "Está bien, eso es todo. Puedo hacerlo... Con tu consejo, puedo afrontar los terrores que me esperan. Deséame suerte.",
        ["Okay, that should be everything. I'll set off now and put your advice to good use."] = "Está bien, eso debería ser todo. Partiré ahora y haré buen uso de tus consejos.",
        ["Thanks for the advice you're the best. Okay, I shall try not to die!"] = "Gracias por el consejo, eres el mejor. ¡Está bien, intentaré no morir!",
        ["*After Jemi gives her response to your final answer: *"] = "*Después de que Jemi dé su respuesta a tu respuesta final: *",
        ["Not just yet."] = "Todavía no.",
        ["*(Returns to previous options)*"] = "*(Vuelve a opciones anteriores)*",
        ["How are you?"] = "¿Cómo estás?",
        ["*At Stage 1: *"] = "*En la Etapa 1: *",
        ["I'm okay, I guess. It's just...well, it's just that I know I'm not as good at this whole adventure thing as I could be. I mean, I try and slay a goblin and I end up stabbing myself in the leeg. That's why I need you - I mean, you can help me to not be so...so...well, bad!"] = "Supongo que estoy bien. Es sólo... bueno, es sólo que sé que no soy tan bueno en todo esto de la aventura como podría serlo. Quiero decir, intento matar a un duende y termino apuñalándome en la pierna. Por eso te necesito - Quiero decir, puedes ayudarme a no ser tan... tan... bueno, ¡malo!",
        ["*(Shows other options)*"] = "*(Muestra otras opciones)*",
        ["*At Stage 2: *"] = "*En la Etapa 2: *",
        ["I'm good...I think. I'm getting a little better at this whole adventurer gig. I mean, I still can't quite work out which way my sword's meant to go, but I'm getting there."] = "Estoy bien...creo. Estoy mejorando un poco en todo este trabajo de aventurero. Quiero decir, todavía no puedo descifrar en qué dirección debe ir mi espada, pero lo estoy logrando.",
        ["*At Stage 3: *"] = "*En la etapa 3: *",
        ["Pretty good, actually. I'm starting to get quite good at all of this. I mean, only yesterday I was attacked by a highwayman and I was able to keep almost all of my money. Well, half. Okay, I got to keep a couple of coins, but for me that's progress."] = "Bastante bien, en realidad. Estoy empezando a ser bastante bueno en todo esto. Quiero decir, ayer mismo fui atacado por un bandolero y pude quedarme con casi todo mi dinero. Bueno, la mitad. Vale, tengo que quedarme con un par de coins, pero para mí eso es un progreso.",
        ["*At Stage 4: *"] = "*En la etapa 4: *",
        ["I'm good thanks to you. I've just joined the Champions' Guild so I think I'm getting good at this. I always wanted to be an adventurer, and now - thanks to you - I am."] = "Estoy bien gracias a ti. Me acabo de unir a Champions' Guild así que creo que me estoy volviendo bueno en esto. Siempre quise ser un aventurero y ahora, gracias a ti, lo soy.",
        ["What can you tell me about yourself?"] = "¿Qué puedes decirme sobre ti?",
        ["You...you want to know about me? Oh, good Guthix! It's like all my dreams came true at once! Well, my name's Jemi - I mean, I think I told you that already - and I'm an adventurer. Well, I mean I'd like to be an adventurer. At the moment I'm more of a novice adventurer...but I'd like to be more."] = "¿Tú... quieres saber sobre mí? ¡Oh, buen Guthix! ¡Es como si todos mis sueños se hicieran realidad a la vez! Bueno, mi nombre es Jemi, quiero decir, creo que ya te lo dije, y soy una aventurera. Bueno, quiero decir que me gustaría ser un aventurero. Por el momento soy más bien un aventurero novato...pero me gustaría serlo más.",
        ["*At Stage 1, Stage 2, and Stage 3: *"] = "*En la Etapa 1, Etapa 2 y Etapa 3: *",
        ["Currently my adventurers have been less than successful. I tried to take an egg from a chicken's nest... it didn't go well. I ended up hiding in the river for a week, living off reeds and inseects. Those chickens were evil!"] = "Actualmente mis aventureros no han tenido mucho éxito. Intenté sacar un huevo del nido de una gallina... no salió bien. Terminé escondido en el río durante una semana, viviendo de juncos e insectos. ¡Esas gallinas eran malas!",
        ["My adventures have been more successful recently, thanks to you. I've started expanding my travels beyond Lumbridge and out into the wider world. Maybe one day I'll even be good enough to head out to the Eastern lands."] = "Mis aventuras han tenido más éxito últimamente gracias a ti. Comencé a expandir mis viajes más allá de Lumbridge y hacia el resto del mundo. Tal vez algún día sea lo suficientemente bueno como para dirigirme a las tierras del Este.",
        ["*If you meet at least one requirement for Player Owned Ports: *"] = "*Si cumples al menos un requisito para los puertos de propiedad de Player: *",
        ["Perhaps I'll be able to sail out on one of your ships."] = "Quizás pueda navegar en uno de tus barcos.",
        ["*If you do not yet meet any requirement for Player Owned Ports: *"] = "*Si aún no cumples con ningún requisito para los puertos propios de Player: *",
        ["I've heard some amazing things about them."] = "He oído algunas cosas asombrosas sobre ellos.",
        ["Shut up Jemi"] = "Cállate Jemi",
        ["OK!"] = "¡Está bien!",
        ["*Jemi may greet you with any one of the following: *"] = "*Jemi puede saludarte con cualquiera de los siguientes: *",
        ["Oh, wow! I can't believe how amazing that was. Nothing went wrong. I didn't fall over my feet - not that I do that much - and no one threw rocks at me or anything like that. I even found some amazing treasure. Here, you deserve a big share, I couldn't have done it without you!"] = "¡Oh, guau! No puedo creer lo asombroso que fue eso. Nada salió mal. No me caí (no es que haga mucho) y nadie me arrojó piedras ni nada por el estilo. Incluso encontré un tesoro increíble. Aquí te mereces una gran parte, ¡no podría haberlo hecho sin ti!",
        ["Oh, it was amazing. I followed your advice and - while I did encounter a few problems - I prevailed. I brought you back a share of my treasure, just as I promised."] = "Oh, fue increíble. Seguí tu consejo y, aunque encontré algunos problemas, prevalecí. Te traje una parte de mi tesoro, tal como te prometí.",
        ["That did not go as well as I expected. Im sorry, but I wasn't able to get the loot that I intended to. Here's what I did find, though. I'll do better next time."] = "Eso no salió tan bien como esperaba. Lo siento, pero no pude conseguir el botín que pretendía. Sin embargo, esto es lo que encontré. Lo haré mejor la próxima vez.",
        ["Oh, good Guthix, it was horrible! I barely escaped with my life. I-I must have gotten your advice mixed up, I'm so sorry. Oh, I'm such a fool. I'll do better next time, I really will. Please, don't give up on me - I know I can be a better adventurer. I just need practice."] = "¡Oh, buen Guthix, fue horrible! Apenas escapé con vida. Debo haber confundido tus consejos, lo siento mucho. Oh, soy un tonto. Lo haré mejor la próxima vez, de verdad que lo haré. Por favor, no te rindas; sé que puedo ser un mejor aventurero. Sólo necesito práctica.",
        ["*After Jemi greets you:  *"] = "*Después de que Jemi te salude:  *",
        ["Jemi gives you a chest filled with spoils of her last adventure."] = "Jemi te regala un cofre lleno del botín de su última aventura.",
        ["Ready to set sail whenever you are, cap'n! Y'arr, and all that!"] = "¡Listo para zarpar cuando lo desees, capitán! ¡Ay y todo eso!",
        ["Oh, hey, have you met Boni yet? She sells all sorts of things in Waiko market."] = "Oh, oye, ¿ya conoces a Boni? Vende todo tipo de cosas en el mercado de Waiko.",
        ["You know each other? What sort of stuff does she sell?"] = "¿Se conocen? ¿Qué tipo de cosas vende?",
        ["Well, she's not part of my pod, but we did train to be seasingers together on Tuai Leit. She's nice, you'll like her!"] = "Bueno, ella no es parte de mi grupo, pero entrenamos juntos para ser cantantes marinos en Tuai Leit. ¡Es agradable, te gustará!",
        ["Just don't stare at her eyepatch. There was an accident during our training involving some whale blubber, a rotten old cork and a narwhal. She's still embarrassed by it."] = "Simplemente no mires fijamente su parche. Durante nuestro entrenamiento hubo un accidente que involucró grasa de ballena, un corcho viejo podrido y un narval. Ella todavía está avergonzada por eso.",
        ["What sort of stuff does she sell?"] = "¿Qué tipo de cosas vende?",
        ["She's in with all the traders here, and can get you better deals with them, and she carries an array of souvenirs and cosmetic items for tourists. She also sells experience lamps, if that's your thing. Oh, and just a few specialist"] = "Ella está con todos los comerciantes aquí y puede conseguir mejores ofertas con ellos, y lleva una gran variedad de recuerdos y artículos cosméticos para turistas. También vende lámparas de experiencia, si eso es lo que te gusta. Ah, y solo algunos especialistas.",
        ["items..."] = "artículos...",
        ["I expect she'll have even more to choose from in a few months, too, from what she tells me."] = "Por lo que me cuenta, espero que ella también tenga más para elegir en unos meses.",
        ["There is so much life out there, in the sea. I can hear so many voices."] = "Hay tanta vida ahí fuera, en el mar. Puedo escuchar tantas voces.",
        ["Sea creatures?"] = "¿Criaturas marinas?",
        ["Uh huh."] = "Ajá.",
        ["Do you have one of your own?"] = "¿Tienes uno propio?",
        ["Not yet. Not all seasingers bond with a sea creature. It's like any relationships - some people make friends easy, others end up alone."] = "Todavía no. No todos los cantores marinos se vinculan con una criatura marina. Es como cualquier relación: algunas personas hacen amigos fácilmente, otras terminan solas.",
        ["In my case, though, I've barely started looking. I'm hoping to find a creature to bond with in my journies with you, captain."] = "En mi caso, sin embargo, apenas comencé a buscar. Espero encontrar una criatura con quien vincularme en mis viajes con usted, capitán.",
        ["Let me know if I can help."] = "Déjame saber si puedo ayudarte.",
        ["This island is so beautiful."] = "Esta isla es tan hermosa.",
        ["Don't let the size and manner of the cyclopes skew your judgement, captain. They have a richer culture than some give them credit. Let's not offend the locals."] = "No dejes que el tamaño y los modales de los cíclopes distorsionen tu juicio, capitán. Tienen una cultura más rica de lo que algunos creen. No ofendamos a los lugareños.",
        ["Ah, Tuai Leit. How I've missed you. I wonder how much has changed since last I was here."] = "Ah, Tuai Leit. Cómo te he echado de menos. Me pregunto cuánto ha cambiado desde la última vez que estuve aquí.",
        ["I hear the voice of the oceans here, captain, and they cry out in sorrow and pain. There has been great loss here, and much suffering."] = "Escucho la voz de los océanos aquí, capitán, y gritan de tristeza y dolor. Ha habido grandes pérdidas aquí y mucho sufrimiento.",
        ["*(Before Final Destination:)*"] = "*(Antes del destino final:)*",
        ["The sea cries out a warning to us, captain. There is danger here. Great danger. The dead have an insatiable hunger for the living. Get ready to run."] = "El mar nos grita una advertencia, capitán. Hay peligro aquí. Gran peligro. Los muertos tienen un hambre insaciable por los vivos. Prepárate para correr.",
        ["*(After Final Destination:)*"] = "*(Después del destino final:)*",
        ["The khan of Goshima is dead, as are her citizens. It should be safe to travel here now, though I see no reason to linger."] = "El khan de Goshima está muerto, al igual que sus ciudadanos. Debería ser seguro viajar hasta aquí ahora, aunque no veo ninguna razón para demorarme.",
        ["This place is a nice change of pace from the east, captain. I like it here."] = "Este lugar es un buen cambio de ritmo desde el este, capitán. Me gusta aquí.",
        ["Any issues from the locals?"] = "¿Algún problema por parte de los lugareños?",
        ["Oh, of course not. Seasingers are no stranger to Menaphos...though it has probably been a good number of years since any of my kind have visited."] = "Oh, por supuesto que no. Los Seasingers no son ajenos a Menaphos... aunque probablemente han pasado muchos años desde que alguien de mi especie lo visitó.",
        ["I got some funny looks at first, but everyone's used to me now. Well, everyone in the ports districts, at least."] = "Al principio recibí algunas miradas raras, pero ahora todos están acostumbrados a mí. Bueno, al menos todos en los distritos portuarios.",
    },
    ["Necronium fanatic (upgraded)"] = {
        ["color=yellow"] = "color=amarillo",
        ["Wow, what is that you are wearing?"] = "Vaya, ¿qué es lo que llevas puesto?",
        ["I'm wearing fully upgraded necronium armour. You will be able to smith it yourself in the upcoming Mining and Smithing rework."] = "Llevo una armadura de necronio completamente mejorada. Podrás crearlo tú mismo en las próximas modificaciones de Mining y Smithing.",
        ["To smith it, first you'll need to mine some necrite ore and phasmatite, which requires 70 Mining and an appropriate pickaxe."] = "Para forjarlo, primero necesitarás extraer algo de mineral de necrita y fasmatita, lo que requiere 70 Mining y un pico adecuado.",
        ["Then with 70 Smithing, you'll be able to smelt the ores into necronium bars, and smith necronium armour and weapons."] = "Luego, con 70 Smithing, podrás fundir los minerales en barras de necronio y forjar armaduras y armas de necronio.",
        ["Oh wow! Do you have more information about the rework?"] = "¡Oh, vaya! ¿Tienes más información sobre el retrabajo?",
        ["*(If you have at least one inventory space:)*"] = "*(Si tienes al menos un espacio de inventario:)*",
        ["You're handed a flyer{{Sic}}"] = "Te entregaron un folleto{{Sic}}",
        ["*(If your inventory is full:)*"] = "*(Si tu inventario está lleno:)*",
        ["If you've got a free space, I can give you a flyer{{Sic}}"] = "Si tienes un espacio libre, puedo darte un folleto{{Sic}}",
    },
    ["Necronium fanatic"] = {
        ["color=yellow"] = "color=amarillo",
        ["Wow, what is that you are wearing?"] = "Vaya, ¿qué es lo que llevas puesto?",
        ["I'm wearing necronium armour. You will be able to smith it yourself in the upcoming Mining and Smithing rework."] = "Llevo una armadura de necronio. Podrás crearlo tú mismo en las próximas modificaciones de Mining y Smithing.",
        ["To smith it, first you'll need to mine some necrite ore and phasmatite, which requires 70 Mining and an appropriate pickaxe."] = "Para forjarlo, primero necesitarás extraer algo de mineral de necrita y fasmatita, lo que requiere 70 Mining y un pico adecuado.",
        ["Then with 70 Smithing, you'll be able to smelt the ores into necronium bars, and smith necronium armour and weapons."] = "Luego, con 70 Smithing, podrás fundir los minerales en barras de necronio y forjar armaduras y armas de necronio.",
        ["Oh wow! Do you have more information about the rework?"] = "¡Oh, vaya! ¿Tienes más información sobre el retrabajo?",
        ["*(If you have at least one inventory space:)*"] = "*(Si tienes al menos un espacio de inventario:)*",
        ["You're handed a flyer{{Sic}}"] = "Te entregaron un folleto{{Sic}}",
        ["*(If your inventory is full:)*"] = "*(Si tu inventario está lleno:)*",
        ["If you've got a free space, I can give you a flyer{{Sic}}"] = "Si tienes un espacio libre, puedo darte un folleto{{Sic}}",
    },
    ["Necrovarus"] = {
        ["Select an Option"] = "Selecciona una opción",
        ["What is this place?"] = "¿Qué es este lugar?",
        ["I do not answer questions, mortal fool!!"] = "¡¡No respondo preguntas, mortal tonto!!",
        ["I will answer questions when you are dead!!"] = "¡¡Responderé preguntas cuando estés muerto!!",
        ["Nobody speaks to me unless I speak to them!!!"] = "¡¡¡Nadie me habla a menos que yo les hable!!!",
        ["Speak to me again and I will rend the soul from your flesh."] = "Háblame de nuevo y arrancaré el alma de tu carne.",
        ["You dare to speak to me??? Have you lost your wits????"] = "¿¿Te atreves a hablar conmigo??? ¿Has perdido el juicio????",
        ["What happened to everyone here?"] = "¿Qué pasó con todos aquí?",
        ["How do I get into the town?"] = "¿Cómo llego al pueblo?",
        ["Told you I'd defeat you, Necrovarus. My advice to you is to pass over to the next world yourself with everybody else."] = "Te dije que te derrotaría, Necrovarus. Mi consejo para ti es que pases al otro mundo junto con todos los demás.",
        ["I should fry you for what you have done..."] = "Debería freírte por lo que has hecho...",
        ["Quiet, evil priest!! If you try anything I will command you again, but this time it will be to throw yourself into the Endless Void for the rest of eternity."] = "¡¡Sacerdote tranquilo y malvado!! Si intentas algo te volveré a ordenar, pero esta vez será que te arrojes al Vacío Sin Fin por el resto de la eternidad.",
        ["Please no! I will do whatever you say!!"] = "¡Por favor, no! ¡¡Haré lo que tu digas!!",
        ["Still licking your wounds?"] = "¿Sigues lamiendo tus heridas?",
        ["Rasial! The cheek of him!"] = "¡Racial! ¡La mejilla de él!",
        ["I hope you wipe that smug off his bony little face, Player."] = "Espero que borres esa presunción de su carita huesuda, Player.",
        ["Don't worry, he'll get what's coming to him. I just need a bit more time to prepare..."] = "No te preocupes, él recibirá su merecido. Sólo necesito un poco más de tiempo para prepararme...",
        ["You might be pleased to hear that I defeated him."] = "Te alegrará saber que lo derroté.",
        ["Wonderful. You no doubt succeeded due to my supreme efforts in aiding your necromancer studies."] = "Maravilloso. Sin duda lo lograste gracias a mis supremos esfuerzos para ayudarte en tus estudios de nigromante.",
        ["Oh gods, more of you blasted adventurers here to foil my plans!"] = "¡Oh dioses, hay más aventureros aquí para frustrar mis planes!",
        ["Oh gods, you again! Here to try and foil my plans no doubt."] = "¡Oh dioses, tú otra vez! Estoy aquí para intentar frustrar mis planes, sin duda.",
        ["What is this thing?"] = "¿Qué es esto?",
        ["It's my new and improved ectofuntus. Just look at it, it's glorious!"] = "Es mi nuevo y mejorado ectofuntus. ¡Míralo, es glorioso!",
        ["How do I use it?"] = "¿Cómo lo uso?",
        ["You mean you've never used an ectofuntus before? Hah! I'd rather not waste my time explaining, but if you must know I've actually made some ingenious improvements! For starters, you now only need to bring bones to use it. No buckets or pots necessary. Now, listen up because I only want to explain this once."] = "¿Quieres decir que nunca antes has usado un ectofuntus? ¡Ja! Preferiría no perder el tiempo explicando, pero si quieres saberlo, ¡he hecho algunas mejoras ingeniosas! Para empezar, ahora sólo necesitas traer huesos para usarlo. No se necesitan cubos ni macetas. Ahora escuchen atentamente porque sólo quiero explicar esto una vez.",
        ["Step one! Crush those remains into a fine dust at the bone grinder just to the west of me. This will get you pots of bonemeal."] = "¡Paso uno! Triture esos restos hasta convertirlos en polvo fino en la trituradora de huesos que está justo al oeste de mí. Con esto obtendrás ollas de harina de huesos.",
        ["Step two! Scoop buckets of ectoplasm from the pool of slime located at the top of the stairs to the east of me. As I said, no buckets required."] = "¡Paso dos! Saque cubos de ectoplasma del charco de baba ubicado en la parte superior de las escaleras al este de mí. Como dije, no se necesitan baldes.",
        ["Step three! Bring your bonemeal and your ectoplasm here - to the ectofuntus = and pray."] = "¡Paso tres! Trae tu harina de huesos y tu ectoplasma aquí - al ectofuntus = y reza.",
        ["The more you honour the dead, the more skilled you will become."] = "Cuanto más honres a los muertos, más hábil te volverás.",
        ["How does it work?"] = "¿Cómo funciona?",
        ["How does it work? What is this, amateur hour? Here, take a copy of my notes and educate yourself. I do not have time to explain the intricacies of prayer to every dull adventurer that comes my way!"] = "¿Cómo funciona? ¿Qué es esto, hora de aficionado? Toma, toma una copia de mis notas e infórmate. ¡No tengo tiempo para explicar las complejidades de la oración a cada aventurero aburrido que se me cruza en el camino!",
        ["Why are you here?"] = "¿Por qué estás aquí?",
        ["I'm a ghost of course! I can come and go as I please thank you very much."] = "¡Soy un fantasma, por supuesto! Puedo entrar y salir cuando quiera muchas gracias.",
        ["Yes, but why have you chosen to come here and set up your ectofuntus?"] = "Sí, pero ¿por qué has elegido venir aquí y montar tu ectofuntus?",
        ["I thought I told you already? It's the perfect place! So much ectoplasm! Such a strong connection between the realms of the living and the dead!"] = "¿Pensé que ya te lo había dicho? ¡Es el lugar perfecto! ¡Cuánto ectoplasma! ¡Qué conexión tan fuerte entre los reinos de los vivos y los muertos!",
        ["Why do you need the ectofuntus though?"] = "¿Por qué necesitas el ectofuntus?",
        ["Well of course, I do have my plans... But I would never share them with such a simpleton!"] = "Bueno, por supuesto, tengo mis planes... ¡Pero nunca los compartiría con un tonto así!",
        ["Comment on his appearance."] = "Comenta sobre su apariencia.",
        ["Do they have doctors in the Underworld?"] = "¿Tienen médicos en el Inframundo?",
        ["What kind of ridiculous question is that?"] = "¿Qué clase de pregunta ridícula es esa?",
        ["I just thought you might need to see someone. Your complexion is a bit... green."] = "Pensé que quizá necesitarías ver a alguien. Tu tez es un poco... verde.",
        ["There's nothing wrong with my complexion. I'm a ghost!"] = "No hay nada malo en mi cutis. ¡Soy un fantasma!",
        ["You look like someone sneezed..."] = "Parece que alguien estornudó...",
        ["You'll regret speaking to me like that you petulant wretch!"] = "¡Te arrepentirás de haberme hablado así, desgraciado petulante!",
        ["Goodbye."] = "Adiós.",
    },
    ["Ned (Ashdale)"] = {
        ["What do you want?"] = "¿Qué quieres?",
        ["Select an Option"] = "Selecciona una opción",
        ["That's not very friendly."] = "Eso no es muy amigable.",
        ["What are you doing?"] = "¿Qué estás haciendo?",
        ["I'm catching fairies with an invisible net! What's it look like I'm doing? I'm sitting here by the fire and trying to enjoy some peace and quiet."] = "¡Estoy atrapando hadas con una red invisible! ¿Qué parece que estoy haciendo? Estoy sentado aquí junto al fuego tratando de disfrutar de un poco de paz y tranquilidad.",
        ["Who are you?"] = "¿Quién eres?",
        ["Don't play fool with me, young [miss/man]. You know full well who I am!"] = "No te hagas el tonto conmigo, joven [miss/man]. ¡Sabes muy bien quién soy!",
        ["There's only one Ned Swarbrick on this island, and that's me. My family has been in Ashdale since the very beginning, and don't you forget it!"] = "Solo hay un Swarbrick Ned en esta isla, y ese soy yo. Mi familia ha estado en Ashdale desde el principio y ¡no lo olvides!",
        ["Goodbye."] = "Adiós.",
        ["Hello."] = "Hola.",
        ["Hello yourself."] = "Hola a ti mismo.",
        ["Alright, alright, don't get too familiar. You might have saved the town, but you should still show your elders the proper respect!"] = "Está bien, está bien, no te familiarices demasiado. Es posible que hayas salvado la ciudad, ¡pero aún así debes mostrar a tus mayores el debido respeto!",
    },
    ["Ned"] = {
        ["What would you like to talk about?"] = "¿De qué te gustaría hablar?",
        ["I've completed all the Medium Tasks in the Lumbridge set."] = "He completado todas las tareas medianas del conjunto Lumbridge.",
        ["I can imagine! I'll expect you'll be wanting a reward, eh?"] = "¡Me lo imagino! Supongo que querrás una recompensa, ¿eh?",
        ["Yes, please."] = "Sí, por favor.",
        ["It looks as though you've done a large amount of exploring, so I'll reward you well for your work."] = "Parece que has explorado mucho, así que te recompensaré bien por tu trabajo.",
        ["Great! Thanks."] = "¡Genial! Gracias.",
        ["Ned hands you a brighter, gold version of the Explorer's Ring."] = "Ned te entrega una versión dorada más brillante del Anillo del Explorador.",
        ["Now, as before, this ring will retain all the functions of your last two rings, however, this one is better."] = "Ahora, como antes, este anillo conservará todas las funciones de tus dos últimos anillos, sin embargo, este es mejor.",
        ["Not only do you get a third and final run energy charge, but this particular ring was blessed by the Farming patch spirit herself! You might see her if you hang around Farming patches for a little while."] = "¡No solo obtienes una tercera y última carga de energía, sino que este anillo en particular fue bendecido por la propia Farming patch spirit! Es posible que la veas si te quedas con los parches de Farming por un tiempo.",
        ["She gets anxious about people loitering or something odd like that."] = "Le pone ansiosa la gente merodeando o algo así de extraño.",
        ["Anyway, this ring allows you to travel on the dual-cabbageway!"] = "De todos modos, ¡este anillo te permite viajar por el camino de doble repollo!",
        ["Travel on the what?"] = "¿Viajar en qué?",
        ["Dual-cabbageway. It's a very secret method of travel not widely known across these lands. Using this ring will allow you to travel to the cabbage fields south of Falador."] = "Camino de repollo doble. Es un método de viaje muy secreto y poco conocido por estas tierras. Usar este anillo te permitirá viajar a los campos de col al sur de Falador.",
        ["That sounds amazing."] = "Eso suena increíble.",
        ["Well, you deserve it. Congratulations on completing all your tasks, my friend."] = "Bueno, te lo mereces. Felicitaciones por completar todas tus tareas, amigo mío.",
        ["Wow, thanks!"] = "¡Vaya, gracias!",
        ["You can also have this old lamp. I don't need it any more - I'm getting too old for adventuring myself. Now, if you should happen to lose that ring, you may come back to me to reclaim it. Anything else?"] = "También puedes quedarte con esta lámpara antigua. Ya no lo necesito. Me estoy haciendo demasiado mayor para aventurarme. Ahora, si pierdes ese anillo, puedes volver a reclamarlo. ¿Algo más?",
        ["I've completed all the hard tasks in the Lumbridge set."] = "He completado todas las tareas difíciles del conjunto Lumbridge.",
        ["My warmest congratulations! I expect you'll be wanting a reward, eh?"] = "¡Mis más sinceras felicitaciones! Supongo que querrás una recompensa, ¿eh?",
        ["Well, it looks like you've explored pretty much everywhere! A suitable reward is in order."] = "Bueno, ¡parece que has explorado prácticamente todos lados! Es necesaria una recompensa adecuada.",
        ["Ned hands you a brighter, shinier version of the Explorer's Ring."] = "Ned te entrega una versión más brillante y brillante del Anillo del Explorador.",
        ["Now, as before, this ring will retain all the functions of your last three rings, however, this one is the best of them all."] = "Ahora, como antes, este anillo conservará todas las funciones de tus últimos tres anillos, sin embargo, este es el mejor de todos.",
        ["I got a few wizards to help with it, so it can now give you a few free casts of the High-Alchemy and Superheat Item spells."] = "Tengo algunos magos que me ayudaron, por lo que ahora puedo darte algunos lanzamientos gratuitos de los hechizos de objetos de alta alquimia y sobrecalentamiento.",
        ["Ahh, you also have a chance of not using runes when casting Bones to Bananas, but you don't need the ring for that. Oh, and a hamper has been donated by Lumbridge Castle's cook - you can get that daily."] = "Ahh, también tienes la posibilidad de no usar runas al lanzar Bones to Bananas, pero no necesitas el anillo para eso. Ah, y el cocinero del castillo Lumbridge ha donado una cesta; puedes conseguirla todos los días.",
        ["Wow!"] = "¡Guau!",
        ["Where is the ring that I gave you, Player?"] = "¿Dónde está el anillo que te regalé, Player?",
        ["I lost it; I'm not sure where."] = "Lo perdí; No estoy seguro de dónde.",
        ["Yes, I thought so. The look on your face told me as much. I have another one that you may have."] = "Sí, eso pensé. La expresión de tu cara me lo dijo. Tengo otro que quizás tengas.",
        ["[Ned hands you another ring.]"] = "[Ned te entrega otro anillo.]",
        ["Choose an option:"] = "Elige una opción:",
        ["Tell me about the Achievement System."] = "Háblame del Sistema de Logros.",
        ["Very well: the Achievement System is a collection of deeds you may wish to complete while adventuring around the world."] = "Muy bien: el Sistema de Logros es una colección de hazañas que quizás desees completar mientras viajas por el mundo.",
        ["You can earn special rewards for completing certain achievements; at the very least, each is worth a cash bounty from Explorer Jack in Lumbridge."] = "Puedes ganar recompensas especiales por completar ciertos logros; como mínimo, cada uno vale una recompensa en efectivo de Explorer Jack en Lumbridge.",
        ["Some also give items that will help complete other achievements, and many count as progress towards the set for the area they're in."] = "Algunos también ofrecen elementos que ayudarán a completar otros logros y muchos cuentan como progreso hacia el conjunto del área en la que se encuentran.",
        ["Tell me about the set reward for this locality."] = "Cuéntame sobre la recompensa establecida para esta localidad.",
        ["For completing the Lumbridge and Draynor set, you are presented with an explorer's ring."] = "Por completar el conjunto Lumbridge y Draynor, se te presenta un anillo de explorador.",
        ["This ring will become increasingly useful with each difficulty level of the set that you complete."] = "Este anillo será cada vez más útil con cada nivel de dificultad del conjunto que completes.",
        ["When you are presented with your rewards, you will be told of their uses."] = "Cuando se le presenten sus recompensas, se le informará sobre sus usos.",
        ["You may also see what rewards a set item provides by hovering over the Rewards icon for its Exploration Achievement set in the Achievements interface."] = "También puedes ver qué recompensas proporciona un elemento determinado al pasar el cursor sobre el ícono de Recompensas de su Logro de exploración establecido en la interfaz de Logros.",
        ["How do I claim these rewards?"] = "¿Cómo reclamo estas recompensas?",
        ["You need to complete all Tasks in the set of a particular difficulty, then you can claim your reward. Most of the Lumbridge set's Tasks are straightforward, although you might find some require quests to be started, if not finished."] = "Debes completar todas las tareas del conjunto de una dificultad particular y luego podrás reclamar tu recompensa. La mayoría de las tareas del conjunto Lumbridge son sencillas, aunque es posible que algunas requieran que se inicien, si no se terminan.",
        ["To claim the Lumbridge set rewards, speak to Bob in Bob's Axes in Lumbridge, Explorer Jack in Lumbridge, or myself."] = "Para reclamar las recompensas del conjunto Lumbridge, habla con Bob en Bob's Axes en Lumbridge, Explorer Jack en Lumbridge o conmigo mismo.",
        ["Sorry, I was just leaving."] = "Lo siento, me estaba yendo.",
        ["Could I buy a spare of the reward?"] = "¿Puedo comprar un repuesto de la recompensa?",
        ["Explorer's ring 1"] = "Anillo del explorador 1",
        ["Explorer's ring 1? Yes, but I'm afraid it would cost you 500 coins."] = "¿Anillo 1 del explorador? Sí, pero me temo que te costaría 500 coins.",
        ["Purchase another for 500 coins?"] = "¿Comprar otro por 500 coins?",
        ["Yes"] = "si",
        ["[You're handed another Explorer's ring 1.]"] = "[Te entregan el anillo de otro Explorador 1.]",
        ["No thanks."] = "No, gracias.",
        ["Explorer's ring 2"] = "Anillo del explorador 2",
        ["Explorer's ring 2? Yes, but I'm afraid it would cost you 1,000 coins."] = "¿Anillo del explorador 2? Sí, pero me temo que te costaría 1.000 coins.",
        ["Purchase another for 1,000 coins?"] = "¿Comprar otro por 1.000 coins?",
        ["[You're handed another Explorer's ring 2.]"] = "[Te entregan el anillo de otro Explorador 2.]",
        ["Explorer's ring 3"] = "Anillo del explorador 3",
        ["Explorer's ring 3? Yes, but I'm afraid it would cost you 2,000 coins."] = "¿Anillo del explorador 3? Sí, pero me temo que te costaría 2000 coins.",
        ["Purchase another for 2,000 coins?"] = "¿Comprar otro por 2000 coins?",
        ["[You're handed another Explorer's ring 3.]"] = "[Te entregan el anillo de otro Explorador 3.]",
        ["Explorer's ring 4"] = "Anillo del explorador 4",
        ["Explorer's ring 4? Yes, but I'm afraid it would cost you 10,000 coins."] = "¿Anillo del explorador 4? Sí, pero me temo que te costaría 10.000 coins.",
        ["Purchase another for 10,000 coins?"] = "¿Comprar otro por 10.000 coins?",
        ["[You're handed another Explorer's ring 4.]"] = "[Te entregan el anillo de otro Explorador 4.]",
        ["Talk about something else."] = "Habla de otra cosa.",
        ["Why, hello there, [lad/lass]. Me friends call me Ned. I was a man of the sea, but it's past me now. Could I be making or selling you some rope?"] = "Hola, [lad/lass]. Mis amigos me llaman Ned. Yo era un hombre de mar, pero ya no lo sé. ¿Podría estar fabricándote o vendiéndote alguna cuerda?",
        ["Yes, I would like some rope."] = "Sí, me gustaría un poco de cuerda.",
        ["Well, I can sell you some rope for 15 coins. Or I can be making you some if you gets me 4 balls of wool. I strands them together I does, makes them strong."] = "Bueno, te puedo vender una cuerda por 15 coins. O puedo hacerte algunos si me consigues 4 ovillos de lana. Los entrelazo, los hago fuertes.",
        ["You make rope from wool?"] = "¿Haces cuerdas con lana?",
        ["Of course you can!"] = "¡Por supuesto que puedes!",
        ["I thought you needed hemp or jute."] = "Pensé que necesitabas cáñamo o yute.",
        ["Do you want some rope or not?"] = "¿Quieres un poco de cuerda o no?",
        ["Select an Option"] = "Selecciona una opción",
        ["Okay, please sell me some rope."] = "Está bien, por favor véndeme un poco de cuerda.",
        ["You can not afford that."] = "No puedes permitirte eso.",
        ["You don't have enough coins to buy any rope!"] = "¡No tienes suficiente coins para comprar ninguna cuerda!",
        ["There you go. <br>Finest rope in Gielinor."] = "Ahí lo tienes. <br>La mejor cuerda de Gielinor.",
        ["You hand Ned 15 coins. Ned gives you a coil of rope."] = "Entregas Ned 15 coins. Ned te regala un rollo de cuerda.",
        ["Thanks. Hmmm, do you know something? This rope has a funny smell."] = "Gracias. Mmmmm ¿sabes algo? Esta cuerda tiene un olor raro.",
        ["Really?"] = "¿En serio?",
        ["Yes, It reminds me of...yaks. I was travelling in the Fremennik Isles recently and, do you know what? They made rope out of yak's hair."] = "Sí, me recuerda a... los yaks. Estuve viajando recientemente por las islas Fremennik y, ¿sabes qué? Hicieron cuerdas con pelo de yak.",
        ["What a coincidence?"] = "¿Qué coincidencia?",
        ["There was a lady over there who sold wool, she said she traded rope for the wool."] = "Había una señora allí que vendía lana, dijo que cambiaba cuerda por lana.",
        ["Who would have thought it?"] = "¿Quién lo hubiera pensado?",
        ["I don't think you make rope at all. I think you trade balls of wool for rope."] = "No creo que hagas cuerdas en absoluto. Creo que cambias ovillos de lana por cuerda.",
        ["Oh, I confess. You have found the truth. I used to make the rope myself, but my fingers aren't as nimble as they used to be and so many people wanted my rope. Demand was so high I had to find another source. But I couldn't tell anyone since Ned's Handmade Rope (100% Wool) is a high profile brand now."] = "Oh, lo confieso. Has encontrado la verdad. Solía ​​hacer la cuerda yo mismo, pero mis dedos ya no son tan ágiles como antes y mucha gente quería mi cuerda. La demanda era tan alta que tuve que buscar otra fuente. Pero no pude decírselo a nadie ya que la cuerda hecha a mano (100% lana) de Ned es ahora una marca de alto perfil.",
        ["Yes, well, the wool is still pretty good, though yak hair makes fine rope. I don't suppose any harm will come of it."] = "Sí, bueno, la lana sigue siendo bastante buena, aunque el pelo de yak sirve como cuerda fina. No creo que esto resulte perjudicial.",
        ["Thanks. Here take this, a free sample! Please, don't tell anyone."] = "Gracias. Toma esto, ¡una muestra gratis! Por favor, no se lo digas a nadie.",
        ["Well, it's always good to keep on the good side of a sailor. Your secret is safe with me."] = "Bueno, siempre es bueno estar del lado bueno de un marinero. Tu secreto está a salvo conmigo.",
        ["Oh, if you're in the Isles again, tell Jofridr that her Neddie will be there soon."] = "Oh, si estás otra vez en las Islas, dile a Jofridr que su Neddie estará allí pronto.",
        ["I will do that!"] = "¡Lo haré!",
        ["I have some balls of wool. Could you make me some rope?"] = "Tengo unos ovillos de lana. ¿Podrías hacerme una cuerda?",
        ["I have some balls of wool. <br>Could you make me some rope?"] = "Tengo unos ovillos de lana. <br>¿Podrías hacerme una cuerda?",
        ["Sure I can."] = "Claro que puedo.",
        ["You hand over 4 balls of wool. Ned gives you a coil of rope."] = "Entregas 4 ovillos de lana. Ned te regala un rollo de cuerda.",
        ["That's a little more than I want to pay."] = "Eso es un poco más de lo que quiero pagar.",
        ["Well, if you ever need rope that's the price. Sorry. An old sailor needs money for a little drop o' rum."] = "Bueno, si alguna vez necesitas una cuerda, ese es el precio. Lo siento. Un viejo marinero necesita dinero para una gota de ron.",
        ["I will go and get some wool."] = "Iré a buscar lana.",
        ["Aye, you do that. Remember, it takes 4 balls of wool to make strong rope."] = "Sí, haz eso. Recuerde, se necesitan 4 ovillos de lana para hacer una cuerda fuerte.",
        ["No thanks Ned, I don't need any."] = "No, gracias Ned, no necesito ninguno.",
        ["No thanks Ned, I don't need any. {{anchor|nothanks}}"] = "No, gracias Ned, no necesito ninguno. {{anchor|nothanks}}",
        ["Well, old Neddy is always here if you do. Tell your friends. I can always be using the business."] = "Bueno, el viejo Neddy siempre está aquí si lo haces. Cuéntaselo a tus amigos. Siempre puedo estar usando el negocio.",
        ["Well, there's a nasty vampyre causing a ruckus every night. I s'pose that's interesting."] = "Bueno, hay un vampyre desagradable que causa alboroto todas las noches. Supongo que eso es interesante.",
        ["You seem pretty calm about it."] = "Pareces bastante tranquilo al respecto.",
        ["[Laddy/Girly] after everything I've seen in my life, a vampyre doesn't ruffle my feathers. Long as I stay inside after dark, I'm fine."] = "[Laddy/Girly] después de todo lo que he visto en mi vida, un vampyre no me altera las plumas. Mientras me quede adentro después del anochecer, estoy bien.",
        ["So, I hear you managed to kill that vampyre. Good on yah."] = "Entonces, escuché que lograste matar a ese vampyre. Bien por ti.",
        ["Thanks, Ned."] = "Gracias, Ned.",
        ["About the Task System..."] = "Acerca del sistema de tareas...",
        ["Hello again, [lad/lass]. Something I can help you with? Want to buy some rope perhaps?"] = "Hola de nuevo, [lad/lass]. ¿Algo en lo que pueda ayudarte? ¿Quizás quieras comprar algo de cuerda?",
        ["How did you get back from Crandor?"] = "¿Cómo volviste de Crandor?",
        ["I got towed back by a friendly passing whale."] = "Una ballena amigable que pasaba me remolcó de regreso.",
        ["Anyway, would you like me to make some rope while you're here?"] = "De todos modos, ¿te gustaría que haga un poco de cuerda mientras estás aquí?",
        ["Can you take me back to Crandor again?"] = "¿Puedes llevarme de regreso a Crandor otra vez?",
        ["Can you find some other way? I think that voyage is cursed!"] = "¿Puedes encontrar alguna otra manera? ¡Creo que ese viaje está maldito!",
        ["Now that you mention it, I found a secret door that led into a cave inside Karamja volcano."] = "Ahora que lo mencionas, encontré una puerta secreta que conducía a una cueva dentro del volcán Karamja.",
        ["That's a relief. You can go and use that instead."] = "Eso es un alivio. Puedes ir y usarlo en su lugar.",
        ["Aye, that I could. I'll meet you at the Port Sarim docks again. I'll try to steer a bit better this time!"] = "Sí, eso podría. Nos vemos nuevamente en los muelles de Port Sarim. ¡Esta vez intentaré conducir un poco mejor!",
        ["Anything interesting happening in Draynor Village?"] = "¿Pasa algo interesante en Draynor Village?",
        ["Talk about Vampyre Slayer"] = "Hablar de Vampyre Slayer",
        ["Ask about contracts."] = "Pregunta por contracts.",
        ["What do you need repairing?"] = "¿Qué necesitas reparar?",
        ["Let me see, right now I need you to repair the following pieces of furniture."] = "Déjame ver, ahora mismo necesito que repares el siguiente pieces of furniture.",
        ["What materials do I need?"] = "¿Qué materiales necesito?",
        ["You need: Planks x [number], Steel nails x [number], [Additional material] x [number]"] = "Necesitas: Planks x [número], Steel nails x [número], [Additional material] x [número]",
        ["Leave"] = "salir",
        ["Ask about something else."] = "Pregunta por otra cosa.",
        ["[Ned has given you your next clue scroll.]"] = "[Ned te ha dado tu siguiente pergamino de pistas.]",
        ["[You've found a casket!]"] = "[¡Has encontrado un ataúd!]",
        ["Good job."] = "Buen trabajo.",
        ["Well, there's a great ruddy crater on the old battlefield to the east. I s'pose that might be interesting."] = "Bueno, hay un gran cráter rojizo en el antiguo campo de batalla al este. Supongo que eso podría ser interesante.",
        ["Well, there's a battle going on to the east between two gods. I s'pose that's interesting."] = "Bueno, hay una batalla en el este entre dos dioses. Supongo que eso es interesante.",
        ["[Laddy/Girly] after everything I've seen in my life, a mere battle between gods doesn't ruffle my feathers. I just keep away and I'm fine."] = "[Laddy/Girly] después de todo lo que he visto en mi vida, una simple batalla entre dioses no me altera las plumas. Simplemente me mantengo alejado y estoy bien.",
        ["Now I see why all the other captains said I'd be mad to go near Crandor. It looks like we're stranded."] = "Ahora entiendo por qué todos los demás capitanes dijeron que estaría loco si me acercara a Crandor. Parece que estamos varados.",
        ["Don't worry about that. I found a secret passage in the dragon's lair that leads off the island!"] = "No te preocupes por eso. ¡Encontré un pasaje secreto en la guarida del dragón que sale de la isla!",
        ["Oh, that's good. I'll be able to get back to Draynor somehow, if I can sneak past all the skeletons and demons on this island!"] = "Oh, eso es bueno. ¡Podré regresar a Draynor de alguna manera, si puedo escabullirme de todos los esqueletos y demonios de esta isla!",
    },
    ["Ned's wife"] = {
        ["Hello! Ned was just telling me how some of his best rope went missing."] = "¡Hola! Ned me estaba contando cómo se perdió parte de su mejor cuerda.",
        ["Nothing looked out of place this morning, but the crate containing the rope that we store over there was empty!"] = "Nada parecía fuera de lugar esta mañana, ¡pero la caja que contenía la cuerda que guardamos allí estaba vacía!",
        ["I'm here all the time and I didn't see anything. It's a mystery to me! It must have happened at night while I was sleeping."] = "Estoy aquí todo el tiempo y no vi nada. ¡Es un misterio para mí! Debió haber sucedido por la noche mientras dormía.",
        ["I have some additional reports of some strange noises being heard last night in the vicinity of your house."] = "Tengo algunos informes adicionales de algunos ruidos extraños que se escucharon anoche en las cercanías de su casa.",
        ["Sorry, I didn't see or hear anything. They would have had some gall to sneak in while I was sleeping in there, though! Terrifying if you think about it."] = "Lo siento, no vi ni oí nada. ¡Sin embargo, habrían tenido algo de descaro para colarse mientras yo dormía allí! Aterrador si lo piensas.",
        ["Instead, I had a lovely dream about sitting in a field, with a slight breeze rustling the wheat and trees around me."] = "En cambio, tuve un hermoso sueño en el que estaba sentado en un campo, con una ligera brisa haciendo crujir el trigo y los árboles a mi alrededor.",
        ["Thinking about it, I had left the window on the landing a jar. But we're on the first floor! Unless they can fly, they wouldn't have been able to get in!"] = "Pensando en ello, había dejado la ventana del rellano como un frasco. ¡Pero estamos en el primer piso! ¡A menos que pudieran volar, no habrían podido entrar!",
    },
    ["Nefertari"] = {
        ["Welcome to my stall! Would you like some bread?"] = "¡Bienvenido a mi puesto! ¿Quieres un poco de pan?",
        ["Welcome to my stall! Would you like some bread? Actually...could you help me please?"] = "¡Bienvenido a mi puesto! ¿Quieres un poco de pan? En realidad... ¿podrías ayudarme por favor?",
        ["Would you like to help?"] = "¿Quieres ayudar?",
        ["Yes."] = "Sí.",
        ["Thank you!"] = "¡Gracias!",
        ["Not right now."] = "No ahora mismo.",
        ["Nevermind."] = "No importa.",
        ["So, I have an acquaintance whom I regularly deliver bones to. They rely on me to make deliveries on a regular schedule."] = "Tengo un conocido al que le entrego huesos con regularidad. Dependen de mí para realizar las entregas según un cronograma regular.",
        ["I have no idea why it is always bones that are requested. I'm not going to question why someone needs some regular old bones, dropped from creatures."] = "No tengo idea de por qué siempre se solicitan huesos. No voy a preguntar por qué alguien necesita algunos huesos viejos y normales, caídos de criaturas.",
        ["So, I have an acquaintance whom I regularly deliver fire battlestaves to. They rely on me to make deliveries on a regular schedule."] = "Tengo un conocido a quien le entrego regularmente bastones de fuego. Dependen de mí para realizar las entregas según un cronograma regular.",
        ["I have no idea why it is always fire battlestaves that are requested. I'm not going to question why someone needs a staff infused with fire magic."] = "No tengo idea de por qué siempre se solicitan bastones de batalla de fuego. No voy a preguntar por qué alguien necesita un staff con magia de fuego.",
        ["Could you please bring me [number] [item]?"] = "¿Podrías traerme [número] [item]?",
        ["Select an option"] = "Selecciona una opción",
        ["Okay, then."] = "Bien, entonces.",
        ["No, sorry."] = "No, lo siento.",
        ["Would you like to abandon this city quest?"] = "¿Te gustaría abandonar esta búsqueda de la ciudad?",
        ["Are you sure you wish to abandon this city quest?"] = "¿Estás seguro de que deseas abandonar esta búsqueda de la ciudad?",
        ["A new Menaphos city quest is now available."] = "Ya está disponible una nueva misión de ciudad Menaphos.",
        ["Talk about your current task."] = "Hable sobre su tarea actual.",
        ["Do you have [number] [item]? I'm a bit pushed for time. ([number] remaining)"] = "¿Tienes [número] [item]? Estoy un poco presionado por el tiempo. ([número] restantes)",
        ["Abandon this city quest."] = "Abandona esta búsqueda de la ciudad.",
        ["Number of [item] given to Nefertari ([number]/[number])"] = "Número de [item] dado a Nefertari ([número]/[número])",
        ["Just one for now. Take it. I'll be back."] = "Sólo uno por ahora. Tómalo. Vuelvo enseguida.",
        ["I have some. Take them. I'll be back."] = "Tengo algunos. Tómelos. Vuelvo enseguida.",
        ["Great. Thank you."] = "Genial. Gracias.",
        ["Yes, I have the [item]."] = "Sí, tengo el [item].",
        ["While you were off gathering [item], I remembered that my cart has a broken wheel, and I need to get it fixed before I can even begin to think abut making a delivery."] = "Mientras estabas recogiendo [item], recordé que mi carrito tiene una rueda rota y necesito arreglarla antes de poder empezar a pensar en hacer una entrega.",
        ["The wheelwright in the port district doesn't accept gold coins as payment, and I'll need to trade goods with her to get my wheel fixed."] = "El carretero del distrito portuario no acepta gold coins como pago y tendré que intercambiar bienes con ella para que me arreglen la rueda.",
        ["What do you need to trade her?"] = "¿Qué necesitas para intercambiarla?",
        ["In order for me to get the wheelwright to fix my wheels, I often need to trade her a load of [item]."] = "Para poder conseguir que el carretero arregle mis ruedas, a menudo necesito cambiarle una carga de [item].",
        ["Right. Why [item]?"] = "Correcto. ¿Por qué [item]?",
        ["I have no idea. Who am I to ask why a wheelwright needs rocks rich in copper?"] = "No tengo idea. ¿Quién soy yo para preguntar por qué un carretero necesita rocas ricas en cobre?",
        ["I have no idea. Who am I to ask why a wheelwright needs a leathery fish, ready to be cooked?"] = "No tengo idea. ¿Quién soy yo para preguntar por qué un carretero necesita un pescado correoso, listo para ser cocinado?",
        ["If you could please fetch me [number] [item], then I will make sure to reimburse you for your time."] = "Si pudieras traerme [número] [item], me aseguraré de reembolsarte tu tiempo.",
        ["Sure thing."] = "Claro.",
        ["I'm hoping to get my wheel fixed sooner rather than later, Player. Do you have [number] [item]? ([number] remaining)"] = "Espero que me arreglen la rueda lo antes posible, Player. ¿Tienes [número] [item]? ([número] restantes)",
        ["I am grateful. Helping me with the [item 1] and now some [item 2], I appreciate it."] = "Estoy agradecido. Ayudándome con el [item 1] y ahora un poco de [item 2], se lo agradezco.",
        ["It seems like my cart will meander through the sand for many more days to come."] = "Parece que mi carrito seguirá serpenteando por la arena durante muchos días más.",
        ["Now all that is left is to get some supplies for the journey."] = "Ahora lo único que queda es conseguir algunos suministros para el viaje.",
        ["No kidding. What do you need?"] = "No es broma. ¿Qué necesitas?",
        ["I have everything I need except for seeds that grow into barberry bushes."] = "Tengo todo lo que necesito excepto las semillas que se convierten en arbustos de agracejo.",
        ["I have everything I need except for some nicely cooked sharks."] = "Tengo todo lo que necesito excepto unos tiburones bien cocinados.",
        ["If you could please obtain [number] [item] for me, then I can be on my way."] = "Si pudieras conseguirme [número] [item], entonces puedo seguir mi camino.",
        ["Sure, fine, whatever."] = "Claro, está bien, lo que sea.",
        ["Nope."] = "No.",
        ["I am grateful. The [item] are packed and ready to go, and now I have some [item] for the journey."] = "Estoy agradecido. Los [item] están empacados y listos para funcionar, y ahora tengo algunos [item] para el viaje.",
        ["Thank you so much for helping me!"] = "¡Muchas gracias por ayudarme!",
    },
    ["Neferti the Camel"] = {
        ["Ask the camel about its dung."] = "Pregúntale al camello por su estiércol.",
        ["I'm sorry to bother you, but could you spare me a little dung?"] = "Lamento molestarte, pero ¿podrías ahorrarme un poco de estiércol?",
        ["Are you serious?"] = "¿Hablas en serio?",
        ["Oh yes. If you'd be so kind."] = "Ah, sí. Si fueras tan amable.",
        ["Well, just you close your eyes first. I'm not doing it while you're watching me!"] = "Bueno, primero cierra los ojos. ¡No lo haré mientras me miras!",
        ["I hope that's what you wanted!"] = "¡Espero que eso sea lo que querías!",
        ["Ohhh yes. Lovely."] = "Ohhh, sí. Hermoso.",
        ["Say something unpleasant."] = "Di algo desagradable.",
        ["I wonder if that camel has fleas..."] = "Me pregunto si ese camello tendrá pulgas...",
        ["What was that?"] = "¿Qué fue eso?",
        ["Er, nothing important."] = "Er, nada importante.",
        ["Wait, you're a human, aren't you? Have you come from outside this town?"] = "Espera, eres un humano, ¿no? ¿Has venido de fuera de este pueblo?",
        ["Yes, I have."] = "Sí, lo he hecho.",
        ["Oh, how wonderful! Does that mean I can finally leave this place and see the world outside?"] = "¡Oh, qué maravilloso! ¿Eso significa que finalmente puedo dejar este lugar y ver el mundo exterior?",
        ["Wouldn't your master have to take you?"] = "¿No tendría que llevarte tu maestro?",
        ["My master has the plague, so he can't leave this town. Nor can anyone else. It's so boring here, and I'd like to travel."] = "Mi amo tiene la peste, por lo que no puede salir de esta ciudad. Nadie más puede hacerlo. Es muy aburrido aquí y me gustaría viajar.",
        ["Travelling's what camels do best, you know."] = "Viajar es lo que mejor hacen los camellos, ¿sabes?",
        ["I don't suppose you could take me with you, could you?"] = "Supongo que no podrías llevarme contigo, ¿verdad?",
        ["Don't you have the plague as well?"] = "¿No tienes la peste también?",
        ["Well, I haven't turned funny colours yet, so probably not. Will you take me with you?"] = "Bueno, todavía no he adquirido colores divertidos, así que probablemente no. ¿Me llevarás contigo?",
        ["I don't really have space for a camel, sorry."] = "Realmente no tengo espacio para un camello, lo siento.",
        ["Oh, well.  Come back some time and bring me news of the rest of the world."] = "Oh, bueno.  Vuelve algún día y tráeme noticias del resto del mundo.",
        ["Neither - I'm a polite person."] = "Ninguno de los dos, soy una persona educada.",
    },
    ["Neil"] = {
        ["Hello there! Are you interested in buying one of my special team capes?"] = "¡Hola! ¿Estás interesado en comprar una de mis capas especiales del equipo?",
        ["What do team capes do?"] = "¿Qué hacen las capas del equipo?",
        ["If you and your friends all wear the same team cape, you'll be less likely to attack your friends by accident, and you'll find it easier to attack everyone else."] = "Si tú y tus amigos usan la misma capa del equipo, será menos probable que ataques a tus amigos por accidente y te resultará más fácil atacar a todos los demás.",
        ["They're very useful in the Wilderness and other player-vs-player combat areas where you might come across friends you don't want to harm."] = "Son muy útiles en Wilderness y otras áreas de combate jugador contra jugador donde puedes encontrarte con amigos a los que no quieres hacer daño.",
        ["So would you like to buy one?"] = "Entonces, ¿te gustaría comprar uno?",
        ["Yes please!"] = "¡Sí, por favor!",
        ["No thanks."] = "No, gracias.",
    },
    ["Neite"] = {
        ["<!-- Anchors"] = "<!-- Anclas",
        ["kin"] = "parientes",
        ["What's new?"] = "¿Qué hay de nuevo?",
        ["When you get to my age, very little seems new anymore."] = "Cuando llegas a mi edad, ya muy pocas cosas parecen nuevas.",
        ["What age are you?"] = "¿Qué edad tienes?",
        ["You should never ask a lady her age!"] = "¡Nunca debes preguntarle a una dama su edad!",
        ["But you're not... I mean..."] = "Pero no lo eres... quiero decir...",
        ["Where's Bob?"] = "¿Dónde está Bob?",
        ["Hey, Neite, where's Bob?"] = "Hola, Neite, ¿dónde está Bob?",
        ["Out gallivanting, hunting noobs in the Wilderness. You know what he's like."] = "Deambulando y cazando novatos en el Wilderness. Ya sabes cómo es.",
        ["So why aren't you out there with him?"] = "Entonces, ¿por qué no estás con él?",
        ["I like to roam as next as the next cat, but, every so often, I do like to come home."] = "Me gusta deambular tan cerca como cualquier gato, pero, de vez en cuando, me gusta volver a casa.",
        ["So, you and Bob haven't had an argument?"] = "Entonces, ¿tú y Bob no habéis tenido una discusión?",
        ["Who told you that?"] = "¿Quién te dijo eso?",
        ["Umm...nobody."] = "Umm...nadie.",
        ["What are you doing?{{anchor|questions}}"] = "¿Qué estás haciendo?{{anchor|questions}}",
        ["What are you doing, then?"] = "¿Qué estás haciendo entonces?",
        ["I'm hunting frogs and locusts."] = "Estoy cazando ranas y langostas.",
        ["Why? Do they taste good?"] = "¿Por qué? ¿Saben bien?",
        ["Wayuckk! No, I would never debase myself to eat such filth."] = "¡Wayuckk! No, nunca me rebajaría a comer semejante porquería.",
        ["I see you're a cat of taste then."] = "Entonces veo que eres un gato de buen gusto.",
        ["I am a cat of high breeding. My family tree dates back to days before any sultan or king of Gielinor."] = "Soy un gato de alta crianza. Mi árbol genealógico se remonta a días anteriores a cualquier sultán o rey de Gielinor.",
        ["Whose cat are you then?"] = "¿De quién eres entonces el gato?",
        ["I am my own cat. I'm not owned by anyone, although I do permit the high priest of Icthlarin to feed me."] = "Soy mi propio gato. No soy propiedad de nadie, aunque permito que el sumo sacerdote de Icthlarin me alimente.",
        ["So what's he like then?"] = "Entonces, ¿cómo es él?",
        ["The old high priest was a vindictive and cranky old man. If he ever didn't get his way, he would make everyone suffer until someone crumbled and gave into his will. I must say that I respected that in him."] = "El viejo sumo sacerdote era un old man vengativo y malhumorado. Si alguna vez no se salía con la suya, haría sufrir a todos hasta que alguien se desmoronara y cediera a su voluntad. Debo decir que respetaba eso en él.",
        ["The new high priest is a bit of a wet towel. He is very unsure of himself and had little respect from the people of the town."] = "El nuevo sumo sacerdote es un poco una toalla mojada. Es muy inseguro de sí mismo y tiene poco respeto por parte de la gente del pueblo.",
        ["That's strange. Nobody I talked to had a bad word to say about him."] = "Eso es extraño. Nadie con quien hablé tenía nada malo que decir sobre él.",
        ["That's probably because most of the townsfolk fled as soon as the plague broke out. They had no confidence in him to fix things. Though, I must say, he treats me much better than the old high priest."] = "Eso probablemente se debe a que la mayoría de la gente del pueblo huyó tan pronto como estalló la plaga. No tenían confianza en él para arreglar las cosas. Aunque debo decir que me trata mucho mejor que el viejo sumo sacerdote.",
        ["The new high priest used to be a bit of a wet towel. He was very unsure of himself and had little respect from the people of the town."] = "El nuevo sumo sacerdote solía ser una toalla un poco mojada. Era muy inseguro de sí mismo y tenía poco respeto por parte de la gente del pueblo.",
        ["You're speaking in past tense."] = "Estás hablando en tiempo pasado.",
        ["Yes, well, since the townspeople have returned, they've a lot more confidence in him and I think he may have gained some more self-belief."] = "Sí, bueno, desde que la gente del pueblo regresó, tienen mucha más confianza en él y creo que puede haber ganado algo más de confianza en sí mismo.",
        ["It's been nice talking, but I have to go."] = "Ha sido agradable hablar, pero tengo que irme.",
        ["It's been nice talking to you, but I really have to go now."] = "Ha sido un placer hablar contigo, pero realmente tengo que irme ahora.",
        ["Goodbye."] = "Adiós.",
        ["I'd like to ask you about something else."] = "Me gustaría preguntarte algo más.",
        ["What do you do with the frogs and locusts?"] = "¿Qué haces con las ranas y las langostas?",
        ["What do you mean by 'do'?"] = "¿Qué quieres decir con \"hacer\"?",
        ["Well, seeing as you're hunting them, I thought you'd eat them too."] = "Bueno, ya que los estás cazando, pensé que también te los comerías.",
        ["No, no, I just hunt them, play with them for a bit and then kill them."] = "No, no, solo los cazo, juego con ellos un rato y luego los mato.",
        ["Isn't that a little evil?"] = "¿No es eso un poco malvado?",
        ["What's evil about a little destruction?"] = "¿Qué tiene de malo un poco de destrucción?",
        ["What isn't? You destroy and take away life. What good is there in that?"] = "¿Qué no lo es? Destruyes y quitas la vida. ¿Qué hay de bueno en eso?",
        ["Hssss. Life can come from destruction too. Take a volcano; It will destroy all life that surrounds it, but it will also fertilise and enrich the surrounding earth. From that earth, more life will spring forth than there was in the first place."] = "Hsss. La vida también puede surgir de la destrucción. Tomemos un volcán; Destruirá toda la vida que lo rodea, pero también fertilizará y enriquecerá la tierra circundante. De esa tierra brotará más vida de la que había en un principio.",
        ["Your ideas disgust me..."] = "Tus ideas me disgustan...",
        ["Your ideas disgust me. I don't want to talk with you anymore."] = "Tus ideas me disgustan. No quiero hablar más contigo.",
        ["Hiss!! Suit yourself, human."] = "¡¡Silbido!! Haz lo que quieras, humano.",
        ["I can see where you're coming from..."] = "Puedo ver de dónde vienes...",
        ["I can see where you're coming from, but how do you compare killing frogs to a volcano?"] = "Puedo ver de dónde vienes, pero ¿cómo se compara matar ranas con un volcán?",
        ["A volcano has no choice whether it explodes or not, but I think you do."] = "Un volcán no tiene opción de explotar o no, pero creo que tú sí.",
        ["I disagree. It's in my nature to prey on smaller, pathetic life forms in the same way as it is in the volcanoes nature to explode."] = "No estoy de acuerdo. Está en mi naturaleza aprovecharme de formas de vida más pequeñas y patéticas de la misma manera que está en la naturaleza de los volcanes explotar.",
        ["I must say, I strongly disagree with your views."] = "Debo decir que estoy totalmente en desacuerdo con tus puntos de vista.",
        ["What you choose to believe in is the illusion of choice?"] = "¿Lo que eliges creer es la ilusión de la elección?",
        ["It's not an illusion."] = "No es una ilusión.",
        ["I suppose you've never heard of the phrase, 'that's the nature of the beast'? Or maybe you were too busy pretending to decide to breathe."] = "Supongo que nunca has oído hablar de la frase \"esa es la naturaleza de the beast\". O tal vez estabas demasiado ocupado fingiendo decidirte a respirar.",
        ["Oh, get away from me."] = "Oh, aléjate de mí.",
        ["You know, you remind me of someone."] = "Sabes, me recuerdas a alguien.",
        ["Who? Someone glamourous, I'd bet, or perhaps regal."] = "¿Quién? Alguien glamoroso, apuesto, o tal vez majestuoso.",
        ["Neither! i was thinking you reminded me of The Devourer."] = "¡Tampoco! Estaba pensando que me recordabas a El Devorador.",
        ["Hisss!!! What? Hiss!!!"] = "¡¡¡Silbido!!! ¿Qué? ¡¡¡Silbido!!!",
        ["I've had enough of your company."] = "Ya tuve suficiente de tu compañía.",
        ["I've had enough of your company. Goodbye."] = "Ya tuve suficiente de tu compañía. Adiós.",
        ["Pah! The Wanderer! Keh! Do you know who you remind me of?"] = "¡Pah! ¡El Errante! ¡Keh! ¿Sabes a quién me recuerdas?",
        ["Goodbye, little cat."] = "Adiós, gatito.",
        ["It's kind of ironic, isn't it?"] = "Es algo irónico, ¿no?",
        ["What is?"] = "¿Qué es?",
        ["Well, the fact that you are in direct conflict with a deity that really seems quite matched to your beliefs."] = "Bueno, el hecho de que estés en conflicto directo con una deidad que realmente parece coincidir bastante con tus creencias.",
        ["Not to mention you work for or with a half-dog god."] = "Sin mencionar que trabajas para o con un dios mitad perro.",
        ["Don't mock me. I do that to seek vengeance."] = "No te burles de mí. Lo hago para buscar venganza.",
        ["What did you say?"] = "¿Qué dijiste?",
        ["Hiss, nothing."] = "Silbido, nada.",
        ["You're seeking revenge on the Wanderer?"] = "¿Buscas vengarte del Errante?",
        ["It's a long story."] = "Es una larga historia.",
        ["Maybe we can talk about it another time."] = "Quizás podamos hablar de ello en otro momento.",
        ["I have no real wish to discuss it with you."] = "No tengo ningún deseo real de discutirlo contigo.",
        ["Fine, maybe we won't discuss it, then."] = "Bien, tal vez no lo hablemos entonces.",
        ["I have time; will you tell me?"] = "Tengo tiempo; ¿me lo dirás?",
        ["Hmm... Maybe... Why not. Do you know what The Wanderer's true form is?"] = "Hmm... Quizás... ¿Por qué no? ¿Sabes cuál es la verdadera forma de The Wanderer?",
        ["Yes. She has dark skin, red hair and red eyes."] = "Sí. Tiene piel oscura, cabello rojo y ojos rojos.",
        ["No, that's not her true form. She has only taken to adopting a form similar to this recently, although she's has many forms since we rose up against her."] = "No, esa no es su verdadera forma. Ella solo ha adoptado una forma similar a esta recientemente, aunque tiene muchas formas desde que nos levantamos contra ella.",
        ["Who's we?"] = "¿Quiénes somos?",
        ["Her acolytes and her priestesses."] = "Sus acólitos y sus sacerdotisas.",
        ["Were all her priestesses and acolytes cats then?"] = "¿Entonces todas sus sacerdotisas y acólitos eran gatos?",
        ["No; I wasn't always a cat."] = "No; No siempre fui un gato.",
        ["You weren't?"] = "¿No lo estabas?",
        ["No, I used to be human. In fact, I was one of her chief priestesses...but that was before we rose up."] = "No, yo solía ser humano. De hecho, yo era una de sus principales sacerdotisas... pero eso fue antes de que nos levantáramos.",
        ["Why did you do that?"] = "¿Por qué hiciste eso?",
        ["The Devourer was so in love with death and destruction that she even started destroying her own worshippers. We tolerated this until she even started to destroy her own temples and clergy."] = "La Devoradora estaba tan enamorada de la muerte y la destrucción que incluso comenzó a destruir a sus propios adoradores. Toleramos esto hasta que ella incluso comenzó a destruir sus propios templos y clero.",
        ["So what did you do?"] = "Entonces, ¿qué hiciste?",
        ["The last of her priestesses gathered and cursed her. Unfortunately she also cast a spell of her own, condemning us to an eternity of walking Gielinor in her form."] = "La última de sus sacerdotisas se reunió y la maldijo. Desafortunadamente, ella también lanzó su propio hechizo, condenándonos a una eternidad caminando por Gielinor en su forma.",
        ["So she's a cat then?"] = "¿Entonces ella es un gato?",
        ["She's as much a cat as Icthlarin is a dog."] = "Ella es tanto un gato como Icthlarin es un perro.",
        ["What curse did you cast upon her?"] = "¿Qué maldición le lanzaste?",
        ["We cursed her so that her name would be forgotten, that any corporeal body she adopted would soon cast her out and never again would she gather willing worshippers."] = "La maldijimos para que su nombre fuera olvidado, que cualquier cuerpo corpóreo que adoptara pronto la expulsaría y nunca más reuniría adoradores dispuestos.",
        ["Why didn't you just destroy her outright, there and then?"] = "¿Por qué no la destruiste directamente, en ese mismo momento?",
        ["We could have, but at that point, our thirst for destruction was well sated."] = "Podríamos haberlo hecho, pero en ese momento, nuestra sed de destrucción estaba bien saciada.",
        ["Your curse seems not to have worked as well as you'd planned. She is still remembered, she can still adopt a form and she can still recruit supporters."] = "Tu maldición parece no haber funcionado tan bien como habías planeado. Todavía se la recuerda, todavía puede adoptar una forma y todavía puede reclutar seguidores.",
        ["Hmm... She is not remembered; only her foul deeds are. As for adopting a form, I believe the next time you come across her, she will have been forced to find a new host."] = "Hmm... No la recuerdan; sólo lo son sus malas acciones. En cuanto a adoptar una forma, creo que la próxima vez que te encuentres con ella, se habrá visto obligada a buscar un nuevo anfitrión.",
        ["She is still able to recruit followers."] = "Todavía puede reclutar seguidores.",
        ["Well, the quality of help she has been forced to take has been quite poor recently; you failed in the simple task of retrieving a jar for her."] = "Bueno, la calidad de la ayuda que se ha visto obligada a recibir ha sido bastante pobre recientemente; fallaste en la simple tarea de recuperar un frasco para ella.",
        ["Excuse me! I had to fight through hordes of mummies, scarabs, fiendish traps and more to get that jar. Besides that, my extra-ordinary level of willpower won out."] = "¡Disculpe! Tuve que luchar contra hordas de momias, escarabajos, trampas diabólicas y más para conseguir ese frasco. Además de eso, ganó mi extraordinario nivel de fuerza de voluntad.",
        ["I'm sure your cat did most of the hard work."] = "Estoy seguro de que tu gato hizo la mayor parte del trabajo duro.",
        ["So why is the Wanderer still scared of cats then?"] = "Entonces, ¿por qué el Errante todavía tiene miedo de los gatos?",
        ["Well, because the few remaining of us still possess some degree of the powers she gave us."] = "Bueno, porque los pocos que quedamos todavía poseemos cierto grado de los poderes que ella nos dio.",
        ["So are there many of you left?"] = "Entonces, ¿quedan muchos de ustedes?",
        ["I refuse to answer that; the less people know about this; the safer I am."] = "Me niego a responder eso; cuanto menos sepa la gente sobre esto; más seguro estoy.",
        ["Recently I have noticed that The Devourer has focused her attentions more on cats. I think she might believe that if all of her original followers die, the curse will lift."] = "Recientemente he notado que The Devourer ha centrado más su atención en los gatos. Creo que podría creer que si todos sus seguidores originales mueren, la maldición desaparecerá.",
        ["Surely all she has to do is to wait until you all die of natural causes?"] = "¿Seguramente todo lo que ella tiene que hacer es esperar hasta que todos mueran por causas naturales?",
        ["It is not in Icthlarin's best interest to let us die, so we will never die of natural causes."] = "No es lo mejor para Icthlarin dejarnos morir, por lo que nunca moriremos por causas naturales.",
        ["Oh! It must become a bit of a drag just hanging around."] = "¡Oh! Debe ser un poco pesado estar por ahí.",
        ["Spite sustains me."] = "El rencor me sostiene.",
        ["Gulp! I hope I never get on your bad side."] = "¡Trago! Espero nunca ponerme en tu lado malo.",
        ["What's your name?"] = "¿Cómo te llamas?",
        ["I sssshouldn't talk to strangers."] = "No debería hablar con extraños.",
        ["Well, my name is Player and I'm pleased to meet you. So, now I'm not a stranger anymore, what's your name?"] = "Bueno, mi nombre es Player y estoy encantado de conocerte. Entonces, ahora ya no soy un extraño, ¿cómo te llamas?",
        ["Purrr... Nice to meet you, Player. My name is Neite."] = "Ronroneo... Encantado de conocerte, Player. Mi nombre es Neite.",
        ["Have you ever heard of a cat called Bob?"] = "¿Alguna vez has oído hablar de un gato llamado Bob?",
        ["A large black cat, purrr?"] = "Un gato negro grande, ¿ronroneo?",
        ["Yes, that's the one. You know him, then?"] = "Sí, ese es el indicado. ¿Lo conoces entonces?",
        ["I don't know if you could ever get to know that cat. He is a bit of an enigma...always wandering but no one knows what he's looking for. He's quite a handsome beast, though!"] = "No sé si algún día podrás llegar a conocer a ese gato. Es un poco enigma... siempre deambula pero nadie sabe lo que está buscando. ¡Pero es una bestia bastante guapa!",
        ["Oh, I see, romance is in the air is it?"] = "Oh, ya veo, el romance está en el aire, ¿verdad?",
        ["Well, life here in the desert can be a lonely existence, even with all my busy work...and he is the most eligible bachelor around. When I hear about him, it makes my whisker tingle... But, to be honest, he worries me."] = "Bueno, la vida aquí en el desierto puede ser una existencia solitaria, incluso con todo mi trabajo ocupado... y él es el soltero más codiciado que existe. Cuando oigo hablar de él, se me eriza el bigote... Pero, la verdad, me preocupa.",
        ["In what way?"] = "¿De qué manera?",
        ["Well, I pride myself on the knowledge of the family lines in cats. Obviously, Bob features quite heavily in most cats' family trees, but he himself has none!"] = "Bueno, me enorgullezco del conocimiento de las líneas familiares de los gatos. Obviamente, Bob aparece bastante en los árboles genealógicos de la mayoría de los gatos, ¡pero él mismo no tiene ninguno!",
        ["What do you mean?"] = "¿Qué quieres decir?",
        ["I mean, nobody is sure where he came from. Not even the Sssphinx knows. It's just one of those mysteries. There are even ancient drawings and ssstories that talk of a warrior known as 'Robert' and his ssstruggles against the"] = "Quiero decir, nadie está seguro de dónde vino. Ni siquiera la Sssfinge lo sabe. Es sólo uno de esos misterios. Incluso hay dibujos e historias antiguas que hablan de un guerrero conocido como 'Robert' y sus luchas contra el",
        ["dragon-kin. He fought with a ferocious black panther who could swallow houses in one gulp!"] = "parientes dragón. ¡Luchó con una feroz pantera negra que podía tragarse casas de un solo trago!",
        ["Dragon-kin? What are they?"] = "¿Parientes de dragón? ¿Cuáles son?",
        ["<span id=\"kin\">The kin? Well mostly it's just stories. Some say they were the first - the true ancient race of this world. They were supposed to have harnessed the power of dragons, making the wild creatures do their bidding. Somehow they"] = "<span id=\"kin\">¿El parentesco? Bueno, en su mayoría son solo historias. Algunos dicen que fueron los primeros: la verdadera raza antigua de este mundo. Se suponía que habían aprovechado el poder de los dragones, haciendo que las criaturas salvajes cumplieran sus órdenes. De alguna manera ellos",
        ["manipulated the dragons' eggs and made them their own! Then the ssstories just end as if they disappeared into sssmoke.</span>"] = "¡manipuló los huevos de los dragones y los hizo suyos! Entonces las historias simplemente terminan como si desaparecieran en sssmoke.</span>",
        ["Fascinating..."] = "Fascinante...",
        ["Well, like I say, they are just stories. Probably some tale a gnomish mother invented to keep her little tykes from running off into the forest alone!"] = "Bueno, como digo, son solo historias. ¡Probablemente algún cuento que una madre gnoma inventó para evitar que sus pequeños huyeran solos al bosque!",
        ["Well, if you ever hear anything more concrete, will you let me know? These dragon-kin sound worth investigating, even if it's just a story."] = "Bueno, si alguna vez escuchas algo más concreto, ¿me lo harás saber? Parece que vale la pena investigar a estos dragones, incluso si es solo una historia.",
        ["It would be my pleasure. I don't like riddles at the best of times! Now, if you'll excuse me, I have some washing to do."] = "Sería un placer. ¡No me gustan los acertijos en el mejor de los casos! Ahora, si me disculpan, tengo algo que lavar.",
        ["Are you one of the Sphinx's friends?"] = "¿Eres uno de los amigos de Sphinx?",
        ["The Sphinx has no friends. She is too wrapped up in preserving her own immortality for friends."] = "El Sphinx no tiene amigos. Está demasiado absorta en preservar su propia inmortalidad para sus amigos.",
        ["So you don't like her then?"] = "¿Entonces no te gusta?",
        ["Nothing of the sorts. I have nothing but respect for her."] = "Nada de eso. No tengo nada más que respeto por ella.",
        ["Why is that?"] = "¿Por qué?",
        ["Well, because her immortality is based on the fact that she keeps us cats safe, so her whole existence is dedicated to protecting us."] = "Bueno, porque su inmortalidad se basa en que ella nos mantiene a los gatos a salvo, por lo que toda su existencia está dedicada a protegernos.",
        ["That doesn't seem like much of a life."] = "Eso no parece una gran vida.",
        ["True, life shouldn't be hoarded but lived...but don't tell her that; otherwise I'd have to be on the lookout for a new guardian."] = "Es cierto, la vida no debe atesorarse sino vivirse... pero no le digas eso; De lo contrario, tendría que buscar un nuevo tutor.",
        ["Can you tell me about the Sect of Scabaras?"] = "¿Puedes hablarme sobre la Secta de Scabaras?",
        ["Do you know anything about the Sect of Scabaras?"] = "¿Sabes algo sobre la Secta de Scabaras?",
        ["Hah! Those insane earth burrowers! They got their comeuppance!"] = "¡Ja! ¡Esos locos excavadores de tierra! ¡Recibieron su merecido!",
        ["What happened to them?"] = "¿Qué les pasó?",
        ["They thought they could undermine the mighty Elidinis so she buried them. They have never been seen around here since."] = "Pensaron que podrían socavar a los poderosos Elidinis, así que ella los enterró. Nunca más se los ha vuelto a ver por aquí desde entonces.",
        ["Where did she bury the sect?"] = "¿Dónde enterró a la secta?",
        ["Under herself."] = "Debajo de ella misma.",
        ["What do you mean 'under herself'?"] = "¿Qué quieres decir con 'debajo de ella'?",
        ["Pah! Stupid human. I don't know why I bother to talk to you."] = "¡Pah! Humano estúpido. No sé por qué me molesto en hablar contigo.",
        ["What do you mean by 'undermine'?"] = "¿Qué quieres decir con \"socavar\"?",
        ["To dig under."] = "Para cavar debajo.",
        ["How do you dig under a goddess?"] = "¿Cómo se excava debajo de una diosa?",
        ["I don't know. I'm not stupid enough to try."] = "No lo sé. No soy tan estúpido como para intentarlo.",
        ["Oh, stop being so condescending, you silly human, or I'll rip your face off."] = "Oh, deja de ser tan condescendiente, humano tonto, o te arrancaré la cara.",
        ["Easy there, tiger! I was only trying to be nice."] = "¡Tranquilo, tigre! Sólo intentaba ser amable.",
        ["Hiss!!"] = "¡¡Silbido!!",
    },
    ["Nen"] = {
        ["If only they had trained Invention, you think to yourself. They could build a machine that would save them all this manual labour. Oh well."] = "Si tan solo hubieran entrenado a Invention, piensas para ti mismo. Podrían construir una máquina que les ahorraría todo este trabajo manual. Ah, bueno.",
        ["Sweat drips down the worker's face. It is quite hot, and you wonder how they haven't yet fainted."] = "El sudor gotea por la cara del trabajador. Hace bastante calor y uno se pregunta cómo es que todavía no se han desmayado.",
        ["The worker glares at you, as if to wonder why you are just staring at them instead of helping them out."] = "El trabajador te mira fijamente, como preguntándose por qué simplemente lo miras fijamente en lugar de ayudarlo.",
        ["You shock the poor worker, and cause them to nearly fall over."] = "Sorprendes al pobre trabajador y haces que casi se caiga.",
        ["Hey, thanks! I appreciate the help."] = "¡Oye, gracias! Agradezco la ayuda.",
        ["No problem!"] = "¡No hay problema!",
        ["Congratulations! You have completed: 'Primitive Technology' - Help out Nen with delivering water to Naida."] = "¡Felicitaciones! Has completado: 'Tecnología primitiva' - Ayuda a Nen a entregar agua a Naida.",
    },
