        ["**WHAT WOULD YOU LIKE TO SAY?**"] = "**¿QUÉ TE GUSTARÍA DECIR?**",
        ["What tools can you store?"] = "¿Qué herramientas puedes almacenar?",
        ["Open your tool store, please."] = "Abre tu tienda de herramientas, por favor.",
        ["Actually, I'm fine."] = "En realidad, estoy bien.",
        ["Winkin's Farm."] = "La granja de Winkin.",
        ["Can you take me to Winkin's Farm?"] = "¿Puedes llevarme a Winkin's Farm?",
        ["Composting."] = "Compostaje.",
        ["Can you compost patches for me?"] = "¿Pueden hacerme abono con parches?",
        ["Wow, someone's lazy... I'll do it, but it'll cost you."] = "Vaya, alguien es un vago... Lo haré, pero te costará.",
        ["500 gold for regular compost, 1,500 gold for supercompost or 2,500 gold for ultracompost. Pay for up to 60,000 upfront, but no refunds."] = "500 de oro para abono normal, 1500 de oro para supercompost o 2500 de oro para ultracompost. Paga hasta 60.000 por adelantado, pero no hay reembolsos.",
        ["Can you stop composting patches for me?"] = "¿Puedes dejar de hacer abono con parches por mí?",
