        ["We'll use [number] regular, [number] supercompost and [number] ultracompost. Want to top up?"] = "Usaremos [número] regular, supercompost [número] y ultracompost [número]. ¿Quieres recargar?",
        ["**SELECT AN OPTION**"] = "**SELECCIONA UNA OPCIÓN**",
        ["Yes."] = "Sí.",
        ["Can I change which patches you compost?"] = "¿Puedo cambiar qué parches compostas?",
