        ["[Previous options]"] = "[Opciones anteriores]",
        ["Other topics."] = "Otros temas.",
        ["Aren't you bit tall for a leprechaun?"] = "¿No eres un poco alto para ser un duende?",
        ["What?<br>Aren't you a bit old for such stupid questions?"] = "¿Qué? <br>A ¿No eres un poco mayor para preguntas tan estúpidas?",
        ["Well, you're looking after tools like leprechauns do."] = "Bueno, estás cuidando las herramientas como lo hacen los duendes.",
        ["I swear to Guthix I'm getting too old for this. Now, do you want me to look after your farming tools?"] = "Le juro por Guthix que me estoy haciendo demasiado mayor para esto. Ahora, ¿quieres que cuide tus herramientas agrícolas?",
        ["Yes, please."] = "Sí, por favor.",
        ["What can you store?"] = "¿Qué puedes almacenar?",
        ["I didn't think this was complicated... I can hold onto a rake, seed dibber, spade, secateurs, watering can and trowel - but not those dodgy archaeology ones."] = "No pensé que esto fuera complicado... Puedo agarrar un rastrillo, un sembrador, una pala, unas tijeras de podar, una regadera y una paleta, pero no esos de arqueología poco fiables.",
        ["I can also store some buckets and scarecrows, as well as compost, supercompost and ultracompost."] = "También puedo guardar algunos cubos y espantapájaros, además de compost, supercompost y ultracompost.",
        ["I've also been told that if you give me your farming produce, I should swap it for these banknotes."] = "También me han dicho que si me das tus productos agrícolas, debería cambiarlos por estos billetes.",
        ["So, do you want me to look after your farming tools?"] = "Entonces, ¿quieres que cuide tus herramientas agrícolas?",
        ["What do you do with the tools you're storing?"] = "¿Qué haces con las herramientas que estás almacenando?",
        ["What do you do with the tools you're storing?<br>They can't possibly all fit in your pockets!"] = "¿Qué haces con las herramientas que guardas?<br>¡No es posible que quepan todas en tus bolsillos!",
        ["What...Well obviously I don't keep them in my pockets, look, I tend to just throw them behind the old compost bin there with the other adventurer's tools."] = "Qué... Bueno, obviamente no los guardo en mis bolsillos, mira, tiendo a tirarlos detrás del viejo contenedor de abono que hay allí con las herramientas del otro aventurero.",
        ["Now, do you want me to look after your tools or not?"] = "Ahora, ¿quieres que cuide tus herramientas o no?",
        ["No thanks, I'll keep hold of my stuff."] = "No, gracias, guardaré mis cosas.",
        ["Alright? Your loss."] = "¿Está bien? Tu pérdida.",
        ["Do you want to change some more?"] = "¿Quieres cambiar algo más?",
        ["Here's your banknotes."] = "Aquí están tus billetes.",
        ["There's nothing for me to exchange."] = "No hay nada que pueda intercambiar.",
        ["**WHAT DO YOU WANT TO TOP UP?**"] = "**¿QUÉ QUIERES RECARGAR?**",
        ["Normal compost."] = "Abono normal.",
        ["Nothing."] = "Nada.",
        ["**WHAT DO YOU WANT TO REFUND?**"] = "**¿QUÉ QUIERES REEMBOLSAR?**",
        ["Looks like you're not actually owed a refund anyway."] = "Parece que de todos modos no se te debe ningún reembolso.",
        ["**PAY [NUMBER] COINS? YOU WILL NOT BE ABLE TO RECLAIM THEM.**"] = "**¿PAGAR [número] COINS? NO PODRÁS RECUPERARLOS.**",
        ["Very well, I'll keep your patches composted. Just keep your storage topped up."] = "Muy bien, mantendré tus parches en abono. Simplemente mantenga su almacenamiento lleno.",
        ["You've not got enough gold, I'm not doing it for free!"] = "No tienes suficiente oro, ¡no lo haré gratis!",
        ["There you go!"] = "¡Ahí lo tienes!",
    },
    ["Niamh"] = {
        ["How are you doing, Niamh?"] = "¿Cómo estás, Niamh?",
        ["HI Player!"] = "¡Hola Player!",
        ["SORRY, indoor voices! Indoor voices."] = "¡LO SIENTO, voces interiores! Voces interiores.",
        ["I'm doing some deep meditation right now. Pixies are prone to overexcitement, which can be not-so-helpful when we're trying to perform intricate tasks like crafting toys."] = "Estoy haciendo una meditación profunda ahora mismo. Los duendes son propensos a la sobreexcitación, lo que puede no ser tan útil cuando intentamos realizar tareas complejas como fabricar juguetes.",
        ["I haven't seen any accidents happen so far."] = "No he visto ningún accidente hasta ahora.",
        ["The rest of the pixies have much more experience than me, so they've learned to get it under control for the most part! Except for when a snow impling wanders in. We love those little guys."] = "El resto de los duendes tienen mucha más experiencia que yo, ¡así que han aprendido a tenerlo bajo control en su mayor parte! Excepto cuando entra un snow impling. Amamos a esos pequeños.",
        ["Maeve has been teaching me some breathing techniques, so hopefully I can be just as cool and collected as everyone else in no time!"] = "Maeve me ha estado enseñando algunas técnicas de respiración, así que espero poder ser tan tranquilo y sereno como todos los demás en poco tiempo.",
        ["Well, good luck with that!"] = "Bueno, ¡buena suerte con eso!",
        ["Thanks for your help this year, Player!"] = "¡Gracias por tu ayuda este año, Player!",
    },
    ["Nic the trader"] = {
        ["Greetings traveller..."] = "Saludos viajero...",
        ["Who are you?"] = "¿Quién eres?",
        ["I am Nic, the superior brother."] = "Soy Nic, el hermano superior.",
        ["Brother?"] = "¿Hermano?",
        ["Yes, you may have met my older brother Vic who turns up once in a while to trade his stock of rare items. Similar to my brother, I can take your bonus experience and offer you compensation in the form of various rare objects. You could say that I've acquired some of his rare items and I'm willing to trade them myself at a much better price. I've also gotten my hands on some items from Alice's dungeon that I'll happily trade... If you see anything you like, I recommend snapping it up as I can't guarantee I'll have it next time I'm trading."] = "Sí, es posible que hayas conocido a mi hermano mayor, Vic, que aparece de vez en cuando para intercambiar sus existencias de artículos raros. Al igual que mi hermano, puedo aprovechar tu experiencia adicional y ofrecerte una compensación en forma de varios objetos raros. Se podría decir que adquirí algunos de sus artículos raros y estoy dispuesto a cambiarlos yo mismo a un precio mucho mejor. También tengo en mis manos algunos artículos de la mazmorra de Alice que felizmente intercambiaré... Si ves algo que te guste, te recomiendo que lo compres, ya que no puedo garantizar que lo tendré la próxima vez que lo intercambie.",
        ["*(Shows initial options)*"] = "*(Muestra opciones iniciales)*",
        ["I would like to trade in some bonus experience."] = "Me gustaría intercambiar alguna experiencia adicional.",
        ["*(If on a member's world:)*"] = "*(Si está en el mundo de un miembro:)*",
        ["*(Opens the credit exchange interface)*"] = "*(Abre la interfaz de intercambio de créditos)*",
        ["*(If on a free-to-play world:)*"] = "*(Si estás en un mundo gratuito:)*",
        ["Sorry, I can't trade here."] = "Lo siento, no puedo comerciar aquí.",
        ["You'll need to be on a member's world to interact with the trader."] = "Necesitarás estar en el mundo de un miembro para interactuar con the trader.",
        ["I would like to buy something."] = "Me gustaría comprar algo.",
        ["*(Opens Nic's Store's interface)*"] = "*(Abre la interfaz de la tienda de Nic)*",
        ["Goodbye."] = "Adiós.",
        ["*(Ends dialogue)*"] = "*(Termina el diálogo)*",
        ["Greetings, traveller."] = "Saludos viajero.",
        ["**SELECT AN OPTION**"] = "**SELECCIONA UNA OPCIÓN**",
        ["Yes, you may have met my older brother Vic who turns up once in a while to trade his stock of rare items."] = "Sí, es posible que hayas conocido a mi hermano mayor, Vic, que aparece de vez en cuando para intercambiar sus existencias de artículos raros.",
        ["I'm trying out a new venture, I can take your Double XP Live time and offer you compensation in the form of credits that can be used to buy my wares."] = "Estoy probando una nueva empresa. Puedo aprovechar tu tiempo de Double XP Live y ofrecerte una compensación en forma de créditos que puedo usar para comprar mis productos.",
        ["I'll give you 250 credits in return for 1 hour of your Double XP Live time but you will only trade once per day."] = "Te daré 250 créditos a cambio de 1 hora de tu tiempo de Doble XP en vivo, pero solo operarás una vez al día.",
        ["If you're interesed in any of my wares, I recommend snapping it up as I can't guarantee I'll have it the next time I'm trading."] = "Si está interesado en alguno de mis productos, le recomiendo comprarlo ya que no puedo garantizar que lo tendré la próxima vez que haga trading.",
        ["I want to sell some Double XP Live time."] = "Quiero vender algo de tiempo de Double XP Live.",
        ["Nic the Traded has been spotted all around Gielinor!"] = "¡Nic the Traded ha sido visto por todo Gielinor!",
        ["I'm trying out a new venture, I can take your Double XP time and offer you compensation in the form of credits that can be used to buy my wares."] = "Estoy probando una nueva empresa. Puedo aprovechar tu tiempo de Doble XP y ofrecerte una compensación en forma de créditos que puedo usar para comprar mis productos.",
        ["I'll give you 250 credits in return for 1 hour of your Double XP time but you will only trade once per day."] = "Te daré 250 créditos a cambio de 1 hora de tu tiempo de Doble XP, pero solo operarás una vez al día.",
        ["I want to sell some Double XP time."] = "Quiero vender algo de tiempo de Doble XP.",
        ["I'm afraid I'm unable to offer my Double XP services to ironmen."] = "Me temo que no puedo ofrecer mis servicios de Doble XP a los ironmen.",
        ["So, you want to sell me your Double XP?"] = "Entonces, ¿quieres venderme tu Doble XP?",
        ["**DO YOU WANT TO CONVERT 1 HOUR OF DOUBLE XP FOR 250 CREDITS?**"] = "**¿QUIERES CONVERTIR 1 HORA DE DOBLE XP POR 250 CRÉDITOS?**",
        ["Yes."] = "Sí.",
        ["Nic takes 1 hour of your Double XP and hands over 250 credits."] = "Nic toma 1 hora de tu Doble XP y entrega 250 créditos.",
        ["Nice doing business with you!"] = "¡Qué bueno hacer negocios contigo!",
        ["You have already exchanged Double XP today."] = "Ya has intercambiado Doble XP hoy.",
        ["You don't have enough time left to exchange for credits."] = "No te queda suficiente tiempo para canjear por créditos.",
        ["You cannot exchange Double XP now."] = "No puedes intercambiar Doble XP ahora.",
        ["Come back if you change your mind."] = "Vuelve si cambias de opinión.",
    },
    ["Nicholas Angle"] = {
        ["I'm not surprised you want to fish. Fishing is great!"] = "No me sorprende que quieras pescar. ¡Fishing es genial!",
        ["Select an Option"] = "Selecciona una opción",
        ["I need fishing bait."] = "Necesito cebo de pesca.",
        ["Tell me about Fishing."] = "Háblame de Fishing.",
        ["Fishing is more than a method of gathering food. It's more than a profession. It's a way of life!"] = "Fishing es más que un método para recolectar alimentos. Es más que una profesión. ¡Es una forma de vida!",
        ["Fish makes good eating, especially when you need to recover after battle."] = "El pescado es un buen alimento, especialmente cuando necesitas recuperarte después de la batalla.",
        ["Tell me about other survival skills."] = "Cuéntame sobre otras habilidades de supervivencia.",
        ["Tell me about Woodcutting."] = "Háblame de Woodcutting.",
        ["Well, what it's really about is maintaining the natural balance and that. See, trees in Gielinor grow pretty wicked fast, and without us to trim them we'd soon be overrun!"] = "Bueno, de lo que realmente se trata es de mantener el equilibrio natural y eso. Mira, los árboles en Gielinor crecen bastante rápido y, sin nosotros para podarlos, ¡pronto seríamos invadidos!",
        ["Course it doesn't hurt that you get useful logs in a wide variety of qualities that you can use for making stuff, or even setting light to, if that's your thing."] = "Por supuesto, no está de más que obtengas logs útil en una amplia variedad de cualidades que puedes usar para hacer cosas, o incluso iluminar, si eso es lo tuyo.",
        ["Tell me about Firemaking."] = "Háblame de Firemaking.",
        ["When you chop down trees, all you're left with are useless logs. BURN THEM TO RELEASE THEIR FIERY HUMOURS!"] = "Cuando talas árboles, lo único que te queda son logs inútiles. ¡QUÉMALOS PARA LIBERAR SUS HUMORES ARDIENTES!",
        ["You can also cook food on a fire."] = "También puedes cocinar comida al fuego.",
        ["You just put your sticks together AND STEAL THE POWER OF THE FLAME FROM THE GODS THEMSELVES!"] = "¡Simplemente juntas tus palos Y ROBAS EL PODER DE LA LLAMA DE LOS MISMOS DIOSES!",
        ["The world is filled with flammable objects straining for release! Join me - we can rebuild this world in flames!"] = "¡El mundo está lleno de objetos inflamables que luchan por liberarse! Únase a mí: ¡podemos reconstruir este mundo en llamas!",
        ["Tell me about Cooking."] = "Háblame de Cooking.",
        ["Cooking is how you turn all of your fine but inedible ingredients into something you can eat. Eating is important, especially when you've been wounded in battle."] = "Cooking es la forma de convertir todos tus ingredientes finos pero no comestibles en algo que puedas comer. Comer es importante, especialmente cuando has resultado herido en batalla.",
        ["You'll find a lot of food items in the world. Cook everything you find! Cook things that seem like no one would ever eat them."] = "Encontrarás muchos alimentos en el mundo. ¡Cocina todo lo que encuentres! Cocine cosas que parezca que nadie se las comería jamás.",
        ["The only way to get better at it is to practice. So cook all the fish you catch, all the potatoes you grow, and your skill will improve."] = "La única manera de mejorar es practicando. Así que cocina todo el pescado que pesques, todas las patatas que cultives y tu habilidad mejorará.",
        ["Better cooks make better food, but of course you need better ingredients. Fishing and farming can help you with that."] = "Los mejores cocineros preparan mejores comidas, pero, por supuesto, necesitas mejores ingredientes. Fishing y la agricultura pueden ayudarte con eso.",
        ["(back)"] = "(atrás)",
        ["Tell me about the skills menu."] = "Cuéntame sobre el menú de habilidades.",
        ["You have many skills you can train. The more you practice a skill, the better it gets. Higher skill levels unlock new activities: equipment to craft, locations to explore, quests to complete, and much more."] = "Tienes muchas habilidades que puedes entrenar. Cuanto más practicas una habilidad, mejor se vuelve. Los skill levels superiores desbloquean nuevas actividades: equipos para crear, lugares para explorar, misiones para completar y mucho más.",
        ["Perform actions associated with a skill to earn experience points (XP) in that skill. Earn enough XP and you'll gain a level in that skill."] = "Realiza acciones asociadas con una habilidad para ganar puntos de experiencia (XP) en esa habilidad. Gana suficiente XP y ganarás un nivel en esa habilidad.",
        ["Most skills start at level 1, and you unlock all their benefits by leveling the skill to 99. (Some skills have unlocks up to level 120.)"] = "La mayoría de las habilidades comienzan en el nivel 1 y desbloqueas todos sus beneficios al subir la habilidad al nivel 99. (Algunas habilidades se pueden desbloquear hasta el nivel 120).",
        ["The bottom number next to a skill icon is your base level in that skill (un-modified by buffs or debuffs). It is used for most requirement checks."] = "El número inferior al lado del ícono de una habilidad es tu nivel base en esa habilidad (sin modificar por ventajas o desventajas). Se utiliza para la mayoría de las comprobaciones de requisitos.",
        ["The top number is your modified skill level (temporarily boosted or drained by skill buffs and debuffs - such as potions or spells). It is used for most skill checks."] = "El número superior es tu skill level modificado (impulsado o agotado temporalmente por mejoras y desventajas de habilidades, como pociones o hechizos). Se utiliza para la mayoría de las pruebas de habilidades.",
        ["Achieve 99 in all your skills to earn the coveted Max Cape!"] = "¡Consigue 99 en todas tus habilidades para ganar la codiciada capa Max!",
        ["Farewell."] = "Adiós.",
    },
    ["Nickolaus"] = {
        ["Hello."] = "Hola.",
        ["Shhhh!  You'll scare the kebbits."] = "¡Shhhh!  Asustarás a los kebbits.",
        ["Hello again Nickolaus."] = "Hola de nuevo Nickolaus.",
        ["Ah, hello again. Can I help at all?"] = "Ah, hola de nuevo. ¿Puedo ayudar en algo?",
        ["Select an Option"] = "Selecciona una opción",
        ["I was just wondering how you got on with those eagles."] = "Me preguntaba cómo te llevabas con esas águilas.",
        ["Ah wonderfully. They're actually most cooperative creatures once they get used to you. With some rope I'm sure you could find some way to tame them... maybe even fly on them."] = "Ah, maravillosamente. En realidad, son criaturas muy cooperativas una vez que se acostumbran a ti. Con un poco de cuerda, estoy seguro de que podrías encontrar alguna manera de domesticarlos... tal vez incluso volar sobre ellos.",
        ["No thanks. I was just dropping by."] = "No gracias. Sólo estaba pasando por aquí.",
        ["No thanks. I was just dropping by, wanted to make sure you hadn't been abducted again."] = "No, gracias. Estaba de paso, quería asegurarme de que no te habían secuestrado otra vez.",
        ["No such luck I'm afraid, but I'm sure I'll make another discovery soon enough. I always seem to."] = "Me temo que no tuve tanta suerte, pero estoy seguro de que pronto haré otro descubrimiento. Parece que siempre lo hago.",
    },
    ["Nicoleta"] = {
        ["*(Before River of Blood:)*"] = "*(Antes de Río de Sangre:)*",
        ["Hey it's the hero! Wow, you're amazing! How on earth did you manage to tackle those two juvinates and Gadderanks? And the town is lovely - you've done a great job!"] = "¡Oye, es el héroe! ¡Guau, eres increíble! ¿Cómo diablos lograste enfrentarte a esos dos juvinates y Gadderanks? Y la ciudad es preciosa. ¡Has hecho un gran trabajo!",
        ["*(After River of Blood:)*"] = "*(Después de Río de Sangre :)*",
        ["Hey it's the hero! Wow, you're amazing! How did you manage to return all the villagers? Things feel so much safer around here now too - great job!"] = "¡Oye, es el héroe! ¡Guau, eres increíble! ¿Cómo conseguiste devolver a todos los aldeanos? Ahora las cosas también se sienten mucho más seguras por aquí: ¡excelente trabajo!",
        ["You're more than welcome."] = "De nada.",
        ["Select an option"] = "Selecciona una opción",
        ["What do you do here?"] = "¿Qué haces aquí?",
        ["I'm Nicoleta. I'm trying to stay warm by this fire."] = "Soy Nicoleta. Estoy tratando de mantenerme caliente junto a este fuego.",
        ["How do you like your town?"] = "¿Qué te parece tu ciudad?",
        ["It's just perfect, thanks so much for your efforts."] = "Es simplemente perfecto, muchas gracias por tus esfuerzos.",
        ["What's happening around here?"] = "¿Qué está pasando por aquí?",
        ["Oh, not much really, we're all still hiding from the vampyres and eking out a living from this terrible place, hopefully soon we'll be strong enough to make the journey to the temple on the Salve."] = "Oh, no mucho en realidad, todos todavía nos estamos escondiendo del vampyres y ganándonos la vida a duras penas en este terrible lugar, con suerte pronto seremos lo suficientemente fuertes para hacer el viaje al templo en la Salve.",
        ["Oh, not much really, we're all just trying to eke out a living in this place. Some of us still want to head for the Salve and into Misthalin, but honestly, it's not so bad here anymore...in spite of how it might look."] = "Oh, no mucho en realidad, todos estamos tratando de ganarnos la vida a duras penas en este lugar. Algunos de nosotros todavía queremos dirigirnos a la Salve y a Misthalin, pero, sinceramente, ya no está tan mal aquí... a pesar de cómo pueda parecer.",
        ["Is there anything I can do to help out?"] = "¿Hay algo que pueda hacer para ayudar?",
        ["Not as far as I know, we have some basic amenities now which is so very useful, we're all incredibly grateful to you. I've never really seen or known a hero before, so I have nothing to compare one to, but I suspect in most people's judgement, you would be one! I for one am very pleased to have met you."] = "No que yo sepa, ahora contamos con algunos servicios básicos que son muy útiles y todos te estamos increíblemente agradecidos. Nunca antes había visto o conocido a un héroe, así que no tengo nada con qué compararlo, pero sospecho que, a juicio de la mayoría de la gente, ¡tú serías uno! Por mi parte, estoy muy contento de haberte conocido.",
        ["Okay, thanks."] = "Está bien, gracias.",
    },
    ["Nigel"] = {
        ["Select an Option"] = "Selecciona una opción",
        ["What's going on here?"] = "¿Qué está pasando aquí?",
        ["I'm enjoying the glorious summer sunshine and barbecuing the tasty tropical trout from the rock pools."] = "Estoy disfrutando del glorioso sol del verano y asando las sabrosas truchas tropicales de los estanques de rocas.",
        ["[Using the barbecues gives you Cooking experience.]"] = "[Usar las barbacoas te brinda la experiencia Cooking.]",
        ["How are things going?"] = "¿Cómo van las cosas?",
        ["What do you think would go better with that beauty of a creature that keeps coming out of the crater; garlic sauce or a creamy one?"] = "¿Qué crees que iría mejor con esa belleza de criatura que sigue saliendo del cráter? ¿Salsa de ajo o una cremosa?",
        ["Garlic sauce!"] = "Salsa de ajo!",
        ["I can see what you mean, it would be piquant and I imagine it would complement the flavours perfectly."] = "Entiendo lo que quieres decir, sería picante e imagino que complementaría los sabores a la perfección.",
        ["Creamy sauce!"] = "Salsa cremosa!",
        ["Mmm, interesting choice. Just the thing to go with seafood. Or crater food come to that."] = "Mmm, elección interesante. Ideal para acompañar mariscos. O, llegado el caso, comida de cráter.",
        ["You shouldn't be trying to eat it!"] = "¡No deberías intentar comértelo!",
        ["Now, now, it's only in my imagination. For now."] = "Ahora, ahora, está sólo en mi imaginación. Por ahora.",
        ["Bye."] = "Adiós.",
        ["Enjoy your time on the beach."] = "Disfruta de tu tiempo en la playa.",
    },
    ["Nikita"] = {
        ["*One of the following dialogues plays at random:*"] = "*Uno de los siguientes diálogos se reproduce aleatoriamente:*",
        ["*Dialogue 1*"] = "*Diálogo 1*",
        ["Out of my way, punk."] = "Fuera de mi camino, punk.",
        ["*Dialogue 2*"] = "*Diálogo 2*",
        ["I have no interest in talking to a pathetic meat bag like yourself."] = "No tengo ningún interés en hablar con un patético bolsa de carne como tú.",
        ["*Dialogue 3*"] = "*Diálogo 3*",
        ["If I were as ugly as you I would not dare to show my face in public!"] = "¡Si fuera tan feo como tú no me atrevería a mostrar mi cara en público!",
