    ["Niles"] = {
        ["Hello, [sir/madam]. My name is Niles. Would you like to learn about bank notes?"] = "Hola, [sir/madam]. Mi nombre es Niles. ¿Quieres aprender sobre los billetes de banco?",
        ["Would you like to learn about bank notes?"] = "¿Quieres aprender sobre los billetes de banco?",
        ["Yes."] = "Sí.",
        ["Very good, [sir/madam]."] = "Muy bien, [sir/madam].",
        ["Bank notes are pieces of paper that represent an item that can be bought or sold."] = "Los billetes de banco son trozos de papel que representan un artículo que se puede comprar o vender.",
        ["[For example, this on the left is an actual cabbage. You can eat a cabbage.]"] = "[Por ejemplo, esto de la izquierda es un repollo real. Puedes comer un repollo.]",
        ["[But this is not a cabbage - it is a bank note of a cabbage. You cannot eat this.]"] = "[Pero esto no es un repollo, es un billete de repollo. No puedes comer esto.]",
        ["You can withdraw many items from your own bank in note form, so long as that item can be traded and does not normally stack."] = "Puedes retirar muchos artículos de tu propio banco en forma de billetes, siempre y cuando ese artículo pueda intercambiarse y normalmente no se acumule.",
        ["To do so, click in the bank note toggle button and then withdraw your items as normal."] = "Para hacerlo, haga clic en el botón de alternancia de billetes y luego retire sus artículos como de costumbre.",
        ["[This is what the bank note toggle button looks like. It's at the bottom right of the bank interface.]"] = "[Así es como se ve el botón de alternancia de billetes. Está en la parte inferior derecha de la interfaz del banco.]",
        ["Conversely, you can move any bank notes from your inventory back into your bank. The simple act of doing so will store the actual item in your bank."] = "Por el contrario, puedes mover cualquier billete de tu inventario a tu banco. El simple hecho de hacerlo almacenará el artículo real en su banco.",
        ["Okay, so bank notes are just representations of objects?"] = "Bien, ¿entonces los billetes de banco son sólo representaciones de objetos?",
        ["Indeed! Now, these 'noted' versions of items cannot be used as could the item itself be - they are, after all, just pieces of paper."] = "¡Efectivamente! Ahora bien, estas versiones \"anotadas\" de elementos no se pueden utilizar como lo haría el elemento en sí; después de todo, son sólo trozos de papel.",
        ["So what are bank notes good for, then?"] = "Entonces, ¿para qué sirven los billetes de banco?",
        ["Mostly for moving items around in bulk. You see, with some items, you are only able to carry as many as will fit in your inventory - for example, you can typically only carry twenty-eight logs, fish or pieces of ore at a time."] = "Principalmente para mover artículos a granel. Verá, con algunos artículos, solo puede llevar tantos como quepan en su inventario; por ejemplo, normalmente solo puede llevar veintiocho logs, pescado o piezas de mineral a la vez.",
        ["But bank notes stack, so you are able to carry hundreds, thousands or even millions of the same item at once, and all taking up just one space in your inventory."] = "Pero los billetes de banco se apilan, por lo que puedes llevar cientos, miles o incluso millones del mismo artículo a la vez, y todos ocupan solo un espacio en tu inventario.",
        ["Bank notes can be traded with other adventurers or sold on the Grand Exchange; moved back and forth between your inventory and bank as you see fit, or even just dropped if you're cleaning your bank of junk."] = "Los billetes de banco se pueden intercambiar con otros aventureros o venderse en Grand Exchange; se mueve de un lado a otro entre su inventario y el banco como mejor le parezca, o incluso simplemente se deja caer si está limpiando su banco de basura.",
        ["Even some monsters are known to drop certain items in bank note form."] = "Incluso se sabe que algunos monstruos dejan caer ciertos artículos en forma de billetes de banco.",
        ["Anything else I should know?"] = "¿Algo más que deba saber?",
        ["Just one more point - because noted items hold the same value as the items they represent, you will find that you can trade them for certain goods and services."] = "Sólo un punto más: debido a que los artículos destacados tienen el mismo valor que los artículos que representan, descubrirá que puede intercambiarlos por ciertos bienes y servicios.",
        ["For example, farming patch gardeners will accept crop-tending payments in the form of bank notes, and you can use noted ore to load the smelter in the Artisan's Workshop in Falador."] = "Por ejemplo, los jardineros de parcelas agrícolas aceptarán pagos por cuidar los cultivos en forma de billetes de banco, y puedes usar el mineral anotado para cargar la fundición en el taller de Artisan en Falador.",
        ["You can even cast the Low and High-Level Alchemy spells on bank notes and you'll create the same amount of coins as you'd have got from casting the spell on the item itself!"] = "¡Incluso puedes lanzar hechizos de alquimia de bajo y alto nivel en billetes de banco y crearás la misma cantidad de coins que habrías obtenido al lanzar el hechizo en el propio objeto!",
        ["Wow, they sound pretty useful. Thanks for the info!"] = "Vaya, suenan bastante útiles. ¡Gracias por la información!",
        ["You are most welcome, [sir/madam]. Good day to you."] = "De nada, [sir/madam]. Buen día para ti.",
    },
