        ["Congratulations on finding me!"] = "¡Felicitaciones por encontrarme!",
        ["*If the player lacks a training card, skip to after the stamp line.*"] = "*Si el player no tiene una tarjeta de entrenamiento, pasa a después de la línea del sello.*",
        ["I see that you have a training card there for me to sign! Let's get the menial stuff out of the way."] = "¡Veo que tienes una tarjeta de entrenamiento ahí para que la firme! Dejemos de lado las cosas menores.",
        ["The Ninja Master has stamped a task for you."] = "El Ninja Master ha creado una tarea para usted.",
