        ["There are two phases to Secret Santa."] = "Hay dos fases para Secret Santa.",
        ["Phase one: Donate. Individuals can donate their hard-earned items into my bag. I will distribute them in phase two."] = "Fase uno: Donar. Las personas pueden donar los artículos que tanto les costó ganar en mi bolso. Los distribuiré en la fase dos.",
        ["We don't want any tat, so there is a minimum donation value. Whatever you give must be worth at least 50,000 coins on the Grand Exchange."] = "No queremos ningún tatuaje, por lo que hay un valor mínimo de donación. Todo lo que des debe valer al menos 50.000 coins en Grand Exchange.",
        ["I've got special rewards too - for anyone going above and beyond. Each day I can give you a medium prismatic lamp for donations totalling 100,000 coins in value."] = "También tengo recompensas especiales para cualquiera que vaya más allá. Cada día puedo regalarles una lámpara prismática mediana por donaciones por un valor total de 100.000 coins.",
        ["If you do this 15 times, I can give you the title of Secret Santa!"] = "¡Si haces esto 15 veces, puedo darte el título de Secret Santa!",
        ["There is a special title for those that donate 200,000,000 coins in one go: the Top Secret Santa!"] = "Hay un título especial para aquellos que donan 200.000.000 coins de una vez: ¡el Papá Noel ultrasecreto!",
        ["Phase two: Gift. Anyone can ask me for a present, and I will randomly select an item from my stores to give them."] = "Fase dos: Regalo. Cualquiera puede pedirme un regalo y seleccionaré aleatoriamente un artículo de mis tiendas para entregárselo.",
        ["Don't get greedy though, eh? I'll only let you take a gift once every 3 hours."] = "Pero no te pongas codicioso, ¿eh? Sólo te dejaré recibir un regalo una vez cada 3 horas.",
        ["I'd like to donate to the Secret Santa."] = "Me gustaría hacer una donación al Santa Secreto.",
        ["I'd like to claim a gift from the Secret Santa."] = "Me gustaría reclamar un regalo del Papá Noel secreto.",
        ["Can you tell me about my daily reward progress?"] = "¿Puedes contarme sobre el progreso de mi recompensa diaria?",
        ["You need to donate items totalling at least a value of [number] coins to receive a daily reward."] = "Debes donar artículos por un valor total de al menos [número] coins para recibir una recompensa diaria.",
        ["You have donated enough wealth to receive your daily reward today. If you haven't collected it from me you can claim it like you would claim a standard Secret Santa gift."] = "Has donado suficiente riqueza para recibir tu recompensa diaria hoy. Si no lo has recibido de mí, puedes reclamarlo como reclamarías un regalo estándar de Secret Santa.",
        ["You need to donate enough to claim a daily reward on [number] more days to receive the Secret Santa title."] = "Debes donar lo suficiente para reclamar una recompensa diaria en [número] días más para recibir el título de Papá Noel Secreto.",
        ["You have donated items of high enough value on enough days to receive the Secret Santa title already."] = "Has donado artículos de valor suficiente en suficientes días para recibir el título de Papá Noel Secreto.",
        ["[You have rewards you must claim or abandon before you can donate any more items.]"] = "[Tienes recompensas que debes reclamar o abandonar antes de poder donar más artículos.]",
        ["You cannot donate items that are worth less than 50,000 coins."] = "No puedes donar artículos que valgan menos de 50.000 coins.",
        ["For donating 100,000 coins worth of items today, you have been awarded a medium prismatic lamp."] = "Por donar hoy artículos por valor de 100.000 coins, se le ha concedido una lámpara prismática mediana.",
        ["The chest is now empty."] = "El cofre ahora está vacío.",
        ["The item could not be added to your bank."] = "El artículo no se pudo agregar a su banco.",
        ["Are you sure you want to discard this item?"] = "¿Estás seguro de que deseas descartar este artículo?",
        ["YES"] = "SI",
        ["BANK ALL"] = "BANCO TODO",
        ["TAKE ALL"] = "TOMAR TODO",
        ["All the items were moved to your inventory."] = "Todos los artículos fueron movidos a su inventario.",
        ["Abandon all remaining items in the chest?"] = "¿Abandonar todos los elementos restantes en el cofre?",
        ["As an Ironman you cannot partake in the greatest joy of all - gift giving. All donations from Ironmen will be destroyed in a controlled explosion in accordance with standard Ironman rules of engagement. Any remaining residue will be destroyed in a second, larger, explosion. Your wealth will not be transferred to other players, but you will be able to receive cosmetic titles for your donations, and progress for related yak track tasks."] = "Como Ironman no puedes participar de la mayor alegría de todas: dar regalos. Todas las donaciones de Ironmen serán destruidas en una explosión controlada de acuerdo con las reglas de enfrentamiento estándar de Ironman. Cualquier residuo restante será destruido en una segunda explosión, más grande. Tu riqueza no se transferirá a otros jugadores, pero podrás recibir títulos cosméticos por tus donaciones y progreso en tareas relacionadas con la pista de yak.",
        ["Would you still like to donate items?"] = "¿Aún te gustaría donar artículos?",
        ["Yes."] = "Sí.",
        ["Yes and don't ask me again."] = "Sí y no me vuelvas a preguntar.",
        ["All of the items were moved to your bank."] = "Todos los artículos fueron trasladados a su banco.",
        ["ABANDON ALL"] = "ABANDONAR TODO",
        ["You can collect another gift in [time]."] = "Puedes recoger otro regalo en [time].",
    },
    ["Noterazzo"] = {
        ["Hey, wanna trade? I'll give the best deals you can find."] = "Oye, ¿quieres intercambiar? Te daré las mejores ofertas que puedas encontrar.",
        ["Yes, please."] = "Sí, por favor.",
        ["No, thanks."] = "No, gracias.",
        ["How can you afford to give such good deals?"] = "¿Cómo puedes darte el lujo de ofrecer ofertas tan buenas?",
        ["The general stores in Asgarnia and Misthalin are heavily taxed. It really makes it hard for them to run an effective business. For some reason taxmen don't visit my store."] = "Los almacenes generales de Asgarnia y Misthalin están sujetos a fuertes impuestos. Realmente les resulta difícil administrar un negocio eficaz. Por alguna razón, los recaudadores de impuestos no visitan mi tienda.",
        ["Goodbye."] = "Adiós.",
        ["People like you are not welcome here, come back when you can show off your bloodlust!"] = "Gente como tú no es bienvenida aquí, ¡vuelve cuando puedas mostrar tu sed de sangre!",
    },
    ["Nougat Bunny"] = {
        ["Hey there, Player! Did you know you're talking to Uncle's new egg hunt supervisor for this year?"] = "¡Hola, Player! ¿Sabías que estás hablando con el nuevo supervisor de búsqueda de huevos del tío para este año?",
        ["Egg hunt? There's an egg hunt this year!?"] = "¿Búsqueda de huevos? ¿¡Hay una búsqueda de huevos este año!?",
        ["This isn't just any egg hunt, this is the Hunt for the Golden Eggs! I've set up three different egg hunts for adventurers to tackle this year."] = "¡Esta no es una búsqueda de huevos cualquiera, es la búsqueda de los huevos de oro! He organizado tres búsquedas de huevos diferentes para que los aventureros las realicen este año.",
        ["But I'm not sure you're ready to tackle all three just yet."] = "Pero no estoy seguro de que estés listo para abordar los tres todavía.",
        ["You'll have to prove your egg hunting prowess by completing a Blooming Burrow egg hunt first!"] = "¡Tendrás que demostrar tu destreza en la búsqueda de huevos completando primero una búsqueda de huevos en Blooming Burrow!",
        ["This sounds interesting, could you tell me about the Blooming Burrow egg hunt then?"] = "Esto suena interesante, ¿podrías hablarme entonces de la búsqueda de huevos de Blooming Burrow?",
        ["The egg hunts are back this year!?"] = "¿¡La búsqueda de huevos ha vuelto este año!?",
        ["They sure are! You'll have to prove your egg hunting skills are still sharp by completing the Blooming Burrow egg hunt first, but then you'll be ready to take on this year's other hunts."] = "¡Seguro que lo son! Tendrás que demostrar que tus habilidades para buscar huevos aún son buenas completando primero la búsqueda de huevos de Blooming Burrow, pero luego estarás listo para afrontar las otras cacerías de este año.",
        ["Could you remind me about the Blooming Burrow egg hunt then?"] = "¿Entonces podrías recordarme sobre la búsqueda de huevos de Blooming Burrow?",
        ["Choose an option:"] = "Elige una opción:",
        ["Talk about the Blooming Burrow Egg Hunt."] = "Habla sobre la búsqueda de huevos de Blooming Burrow.",
        ["The Blooming Burrow egg hunt takes place right here, where I'll hide a batch of golden eggs around the burrow for you to find."] = "La búsqueda de huevos de Blooming Burrow se lleva a cabo aquí mismo, donde esconderé un lote de huevos dorados alrededor de la madriguera para que los encuentres.",
        ["Each day, if you can find all 12 of the hidden eggs, and bring them back to me..."] = "Cada día, si puedes encontrar los 12 huevos escondidos y traérmelos...",
        ["Then I'll give you a special, egg seekers approved, prize!"] = "¡Entonces te daré un premio especial aprobado por buscadores de huevos!",
        ["I've just finished hiding today's batch, so take a look around and see if you can find them all."] = "Acabo de terminar de ocultar el lote de hoy, así que echa un vistazo a tu alrededor y trata de encontrarlos todos.",
        ["I've hidden another set of eggs for you to find around the burrow today, good luck!"] = "He escondido otro juego de huevos para que los encuentres hoy en la madriguera, ¡buena suerte!",
        ["It looks like you're in the middle of a burrow egg hunt already. Good luck finding the rest of the eggs!"] = "Parece que ya estás en medio de una búsqueda de huevos en una madriguera. ¡Buena suerte para encontrar el resto de los huevos!",
        ["Eggs found: [number]/12"] = "Huevos encontrados: [número]/12",
        ["You've already completed the hunt for today. Come back tomorrow and I'll have hidden a new batch of eggs for you to find."] = "Ya has completado la búsqueda de hoy. Vuelve mañana y habré escondido un nuevo lote de huevos para que los encuentres.",
        ["Talk about the Gielinor Egg Hunt."] = "Hable sobre la búsqueda de huevos de Gielinor.",
        ["To keep you busy during the Easter celebrations, I've hidden a bunch of golden eggs all over Gielinor!"] = "Para mantenerte ocupado durante las celebraciones de Pascua, ¡he escondido un montón de huevos de oro por todo Gielinor!",
        ["To help point you in their direction, I've put together a book of clues."] = "Para ayudarte a orientarte en su dirección, he elaborado un libro de pistas.",
        ["You'll earn spring tokens for any of these golden eggs you're able to find around Gielinor."] = "Ganarás fichas de primavera por cualquiera de estos huevos de oro que podrás encontrar en Gielinor.",
        ["But I'm not giving clue books out to just anyone. You'll have to prove your egg hunting prowess by completing a Blooming Burrow egg hunt first!"] = "Pero no le daré libros de pistas a cualquiera. ¡Tendrás que demostrar tu destreza en la búsqueda de huevos completando primero una búsqueda de huevos en Blooming Burrow!",
        ["You add the additional clues to your egg hunt clue book."] = "Agrega las pistas adicionales a su libro de pistas de búsqueda de huevos.",
        ["The second week of eggs for the Gielinor egg hunt are now ready to find, here are your clues. Best of luck!"] = "La segunda semana de huevos para la búsqueda de huevos de Gielinor ya están listos para encontrarlos, aquí están sus pistas. ¡Toda la suerte!",
        ["The third week of eggs for the Gielinor egg hunt are now ready to find, here are your clues. Best of luck!"] = "La tercera semana de huevos para la búsqueda de huevos de Gielinor ya están listos para encontrarlos, aquí están tus pistas. ¡Toda la suerte!",
        ["Reclaim Egg Hunt clue book."] = "Recupera el libro de pistas de Egg Hunt.",
        ["Nougat, I've unfortunately misplaced my egg hunt clue book. Do you happen to have any spare ones?"] = "Nougat, lamentablemente perdí mi libro de pistas para la búsqueda de huevos. ¿Tienes alguno de repuesto?",
        ["No need to worry, with so much activity around the burrow this year I made plenty to go around."] = "No hay necesidad de preocuparse, con tanta actividad en la madriguera este año, hice mucho para todos.",
        ["Oh, I'm afraid you need at least 1 backpack space free for your clue book. Come and speak to me again when you have the space."] = "Oh, me temo que necesitas al menos 1 espacio backpack libre para tu libro de pistas. Ven y habla conmigo nuevamente cuando tengas espacio.",
        ["[Nougat Bunny hands you a new Egg hunt clue book.]"] = "[Nougat Bunny te entrega un nuevo libro de pistas para la búsqueda de huevos.]",
        ["Thanks, I'll try to keep track of this one."] = "Gracias, intentaré realizar un seguimiento de este.",
        ["Farewell."] = "Adiós.",
        ["Take care, Nougat."] = "Cuídate, Turrón.",
        ["You too! Remember to keep an eye out for any of those golden eggs!"] = "¡Tú también! ¡Recuerda estar atento a cualquiera de esos huevos de oro!",
        ["Welcome back, Player. It looks like you've still got some eggs left to find around the burrow."] = "Bienvenido de nuevo, Player. Parece que todavía te quedan algunos huevos por encontrar en la madriguera.",
        ["Come speak with me again once you've found them all and I'll share the details of the other egg-citing hunts!"] = "¡Ven a hablar conmigo nuevamente una vez que los hayas encontrado todos y compartiré los detalles de las otras búsquedas de huevos!",
        ["Congratulations on finding all 12 eggs, please take this reward for your eagle-eyed effort."] = "Felicitaciones por encontrar los 12 huevos. Reciba esta recompensa por su esfuerzo con vista de águila.",
        ["Oh, I'm afraid you need at least 2 backpack spaces for your reward and clue book. Come and speak to me again when you have the space."] = "Oh, me temo que necesitas al menos 2 espacios backpack para tu libro de recompensas y pistas. Ven y habla conmigo nuevamente cuando tengas espacio.",
        ["[Nougat Bunny hands you an Egg hunt clue book and a Holiday reward casket (free).]"] = "[Nougat Bunny te entrega un libro de pistas para la búsqueda de huevos y un cofre de recompensa navideña (gratis).]",
        ["[Nougat Bunny hands you an Egg hunt clue book and a Holiday reward casket.]"] = "[Nougat Bunny te entrega un libro de pistas para la búsqueda de huevos y un cofre de recompensa navideña.]",
        ["That's your very own egg hunt clue book. Now that you've proven yourself as an expert egg hunter, you're ready to take on the Gielinor egg hunt."] = "Ese es tu propio libro de pistas para la búsqueda de huevos. Ahora que has demostrado ser un experto cazador de huevos, estás listo para emprender la búsqueda de huevos Gielinor.",
        ["The first week of eggs are ready to find - don't forget you can read the clues in your egg hunt clue book. Best of luck!"] = "La primera semana de huevos está listo para encontrar. No olvides que puedes leer las pistas en tu libro de pistas de búsqueda de huevos. ¡Toda la suerte!",
        ["Oh, I'm afraid you need at least 1 backpack space for your reward. Come and speak to me again when you have the space."] = "Oh, me temo que necesitas al menos 1 espacio backpack para tu recompensa. Ven y habla conmigo nuevamente cuando tengas espacio.",
        ["[Nougat Bunny hands you a Holiday reward casket (free).]"] = "[Nougat Bunny te entrega un cofre de recompensa navideña (gratis).]",
        ["[Nougat Bunny hands you a Holiday reward casket.]"] = "[Nougat Bunny te entrega un cofre de recompensa navideña.]",
        ["The following has been added to your currency pouch: 5 x Treasure Trail Points."] = "Se ha agregado lo siguiente a su bolsa de divisas: 5 x Puntos Treasure Trail.",
        ["You have reached the Spring token soft cap of 30,000. You need to spend some tokens in Gummy's store before you can earn more."] = "Ha alcanzado el límite flexible del token Spring de 30 000. Debes gastar algunas fichas en la tienda de Gummy antes de poder ganar más.",
        ["Now that you've proven yourself to still be an expert egg hunter, you're ready to take on this {{Sic|years}} Gielinor egg hunt. Check out the clues in this book and see if you can crack where the eggs have been hidden this year."] = "Ahora que has demostrado que sigues siendo un experto cazador de huevos, estás listo para emprender esta búsqueda de huevos {{Sic|years}} Gielinor. Echa un vistazo a las pistas de este libro y trata de descubrir dónde se escondieron los huevos este año.",
        ["The first week of eggs are ready to find - don't forget you can ready the clues in your egg hunt clue book. Best of luck!"] = "La primera semana de huevos está listo para encontrar. No olvides que puedes preparar las pistas en tu libro de pistas de búsqueda de huevos. ¡Toda la suerte!",
        ["That title suits you! Are you going to go hide with the other eggs?"] = "¡Ese título te queda bien! ¿Vas a esconderte con los otros huevos?",
        ["You've unlocked the 'Yolk' colour for the 'the Egg' title!"] = "¡Has desbloqueado el color 'Yema' para el título 'El Huevo'!",
        ["Just make sure you're careful, or you'll end up scrambled!"] = "¡Solo asegúrate de tener cuidado o terminarás revuelto!",
    },
    ["Nulodion"] = {
        ["Hello."] = "Hola.",
        ["Hello traveller, how's things?"] = "Hola viajero, ¿cómo van las cosas?",
        ["Not bad thanks, yourself?"] = "No está mal, ¿gracias?",
        ["I'm good, just working hard as usual..."] = "Estoy bien, solo estoy trabajando duro como siempre...",
        ["Select an option"] = "Seleccione una opción",
        ["I was hoping you might sell me a cannon?"] = "¿Esperaba que pudieras venderme un cañón?",
        ["I was hoping you might sell me a cannon."] = "Esperaba que pudieras venderme un cañón.",
        ["Hmmmmmm... I shouldn't really, but as you helped us so much, well, I could sort something out. I'll warn you though, they don't come cheap!"] = "Hmmmmmm... Realmente no debería, pero como nos ayudaste tanto, bueno, podría arreglar algo. Pero te lo advierto: ¡no son baratos!",
        ["How much?"] = "¿Cuánto?",
        ["For the full setup, 750,000 coins. Or I can sell you the separate parts... but it'll cost extra!"] = "Para la configuración completa, 750.000 coins. O puedo venderte las piezas por separado... ¡pero costará más!",
        ["That's not cheap!"] = "¡Eso no es barato!",
        ["Okay, I'll take a cannon please."] = "Está bien, llevaré un cañón, por favor.",
        ["Okay then, but keep it quiet... This thing's top secret!"] = "Está bien, pero mantenlo en secreto... ¡Esto es ultrasecreto!",
        ["Oops, I don't have enough money."] = "Vaya, no tengo suficiente dinero.",
        ["Sorry, I can't go any lower than that."] = "Lo siento, no puedo bajar más que eso.",
        ["750,000 coins have been removed from your money pouch."] = "Se han eliminado 750.000 coins de su bolsa de dinero.",
        ["You give the Cannon engineer 750,000 coins."] = "Le das al ingeniero de Cannon 750.000 coins.",
        ["He gives you the four parts that make the cannon, plus an ammo mould and an instruction manual."] = "Te entrega las cuatro piezas que componen el cañón, además de un molde de munición y un manual de instrucciones.",
        ["There you go, you be careful with that thing."] = "Ahí tienes, ten cuidado con esa cosa.",
        ["Will do, take care mate."] = "Lo haré, cuídate amigo.",
        ["Take care adventurer."] = "Cuídate aventurero.",
        ["Can I look at the separate parts please?"] = "¿Puedo ver las partes separadas, por favor?",
        ["Of course!"] = "¡Por supuesto!",
        ["Sorry, that's too much for me."] = "Lo siento, eso es demasiado para mí.",
        ["Fair enough, it's too much for most of us."] = "Es cierto, es demasiado para la mayoría de nosotros.",
        ["Have you any ammo or instructions to sell?"] = "¿Tienes munición o instrucciones para vender?",
        ["Well, take care of yourself then."] = "Bueno, entonces cuídate.",
        ["Indeed I will adventurer."] = "De hecho, seré un aventurero.",
        ["I want to know more about the cannon."] = "Quiero saber más sobre el cañón.",
        ["There's only so much I can tell you, adventurer. We've been working on this little beauty for some time now."] = "Hay mucho que puedo decirte, aventurero. Llevamos algún tiempo trabajando en esta pequeña belleza.",
        ["Is it effective?"] = "¿Es efectivo?",
        ["It short bursts it's very effective, the most destructive weapon to date. The cannon automatically targets monsters close by. You just have to make the ammo and let rip."] = "Tiene ráfagas cortas, es muy eficaz y es el arma más destructiva hasta la fecha. El cañón apunta automáticamente a los monstruos cercanos. Sólo tienes que hacer la munición y soltarla.",
        ["I've lost my cannon."] = "He perdido mi cañón.",
        ["Keep that quiet or I'll be in real trouble!"] = "¡Mantén eso en silencio o estaré en un verdadero problema!",
        ["The dwarf gives you anew [cannon variant]."] = "El enano te regala un nuevo [cannon variant].",
        ["Of course."] = "Por supuesto.",
        ["Oh dear, I'm only allowed to replace cannons that were stolen in action. I'm sorry, but you'll have to buy a new set."] = "Dios mío, solo puedo reemplazar cañones que fueron robados en acción. Lo siento, pero tendrás que comprar un juego nuevo.",
        ["It looks like your made your last cannon using odd parts. I can't replace it. Maybe you should go make another one."] = "Parece que hiciste tu último cañón usando piezas extrañas. No puedo reemplazarlo. Quizás deberías ir a hacer otro.",
    },
    ["Nung"] = {
        ["Hey fishy. If you's a good fishy I might sell yous bitses of skippy skin clothes."] = "Hola, sospechoso. Si eres un buen pescador, podría venderte trozos de ropa de piel.",
        ["But Nung needs time to makes them first."] = "Pero Nung necesita tiempo para hacerlos primero.",
        ["Can I have one of your crabs please? I have this token..."] = "¿Me puedes dar uno de tus cangrejos, por favor? Tengo esta ficha...",
        ["Where did a fishy get this? It's my writings about giving out baby crunchy claws."] = "¿De dónde sacó esto un sospechoso? Son mis escritos sobre cómo regalar garras crujientes a los bebés.",
        ["I, err, found it lying about."] = "Yo, err, lo encontré tirado por ahí.",
        ["Oh wells, it not matter, here is da little crunchy claw for da fishy."] = "Oh, bueno, no importa, aquí tienes una pequeña garra crujiente para el pescado.",
        ["Thanks!"] = "¡Gracias!",
    },
    ["Nurmof"] = {
        ["Greetings and welcome to my pickaxe shop. Do you want to buy my premium quality pickaxes?"] = "Saludos y bienvenidos a mi tienda de picos. ¿Quieres comprar mis picos de primera calidad?",
        ["Select an Option"] = "Selecciona una opción",
        ["Yes, please."] = "Sí, por favor.",
        ["No, thank you."] = "No, gracias.",
        ["Are your pickaxes better than other pickaxes, then?"] = "¿Entonces tus picos son mejores que otros picos?",
        ["Of course they are! My pickaxes are made of higher grade metal than your ordinary bronze pickaxes, allowing you to mine ore just that little bit faster."] = "¡Por supuesto que lo son! Mis picos están hechos de metal de mayor calidad que los picos de bronce comunes, lo que te permite extraer mineral un poco más rápido.",
        ["What's that machine?"] = "¿Qué es esa máquina?",
        ["That, my friend, is the latest marvel of dwarven engineering. It's my pickaxe-making machine!"] = "Esa, amigo mío, es la última maravilla de la ingeniería enana. ¡Es mi máquina para hacer picos!",
        ["How does it work?"] = "¿Cómo funciona?",
        ["Sorry, I can't say. I'm not going to tell just anyone."] = "Lo siento, no puedo decirlo. No se lo voy a decir a cualquiera.",
        ["Is this to do with the power station?"] = "¿Tiene esto que ver con la central eléctrica?",
        ["As a matter of fact, it is. I needed a power source for the pickaxe machine and Drorkar from Keldagrim came up with the best solution."] = "De hecho, lo es. Necesitaba una fuente de energía para la máquina pico y Drorkar de Keldagrim encontró la mejor solución.",
        ["I'm sure, as more of the mine gets automated, the power station can be made larger."] = "Estoy seguro de que a medida que se automatice más parte de la mina, la central eléctrica podrá hacerse más grande.",
        ["Why do you need a machine?"] = "¿Por qué necesitas una máquina?",
        ["I suppose it wouldn't have affected you, since humans don't get through enough pickaxes like dwarves do, but, until recently, there was a large pickaxe shortage in the Dwarven Mine."] = "Supongo que no te habría afectado, ya que los humanos no utilizan suficientes picos como lo hacen los enanos, pero, hasta hace poco, había una gran escasez de picos en la Mina Enana.",
        ["When the new regulations came through saying that I had to stock more pickaxes, I had trouble keeping up."] = "Cuando llegaron las nuevas regulaciones que decían que tenía que almacenar más picos, tuve problemas para mantener el ritmo.",
        ["People were even starting to import pickaxes from Keldagrim - inferior quality pickaxes made by Tati."] = "La gente incluso estaba empezando a importar picos de Keldagrim, picos de calidad inferior fabricados por Tati.",
        ["So, I built the machine. Mechanisation is the only way I can meet demand while maintaining my high standards. Every pickaxe that comes from the machine is exactly right."] = "Entonces, construí la máquina. La mecanización es la única manera de satisfacer la demanda y al mismo tiempo mantener mis altos estándares. Cada pico que sale de la máquina es exactamente correcto.",
        ["Oh, right."] = "Ah, claro.",
        ["How is the wind power station working out?"] = "¿Cómo va la central eólica?",
        ["Very well, thank you. I had been worried about supply cutting out when the wind drops, but Bordiss has installed some kind of device to store power for those times."] = "Muy bien, gracias. Me preocupaba que el suministro se cortara cuando amaina el viento, pero Bordiss ha instalado algún tipo de dispositivo para almacenar energía para esos momentos.",
        ["It's far less smelly than the old power station, too! It almost makes me want to go for a walk on the surface, and few things make an old dwarf like me want to go to the surface!"] = "¡Además huele menos que la antigua central eléctrica! Casi me dan ganas de dar un paseo por la superficie, ¡y pocas cosas hacen que un viejo enano como yo quiera ir a la superficie!",
        ["I'm afraid you can't use that ladder. Drorkar is very strict; it's for power station workers only."] = "Me temo que no puedes usar esa escalera. Drorkar es muy estricto; es sólo para trabajadores de centrales eléctricas.",
    },
    ["Nurse Sarah"] = {
        ["Hello there."] = "Hola.",
        ["Hello my dear, how are you feeling?"] = "Hola querida, ¿cómo te sientes?",
        ["I'm ok thanks."] = "Estoy bien, gracias.",
        ["Well in that case I'd better get back to work. Take care."] = "Bueno, en ese caso será mejor que vuelva al trabajo. Cuidarse.",
        ["You too."] = "Tú también.",
        ["The plague itself was a fake, but the image of West Ardougne as a plague city wasn't too far from the truth. Malnutrition, poor sanitation... it's no wonder these people aren't healthy. Now that we can get in and out again, people are getting healthier, but it'll be a long time before West Ardougne is really a nice place to live."] = "La plaga en sí era falsa, pero la imagen de West Ardougne como plague city no estaba muy lejos de la verdad. Desnutrición, malas condiciones sanitarias... no es de extrañar que estas personas no estén sanas. Ahora que podemos entrar y salir nuevamente, la gente está cada vez más sana, pero pasará mucho tiempo antes de que West Ardougne sea realmente un lugar agradable para vivir.",
    },
    ["Nurse"] = {
        ["Hello there."] = "Hola.",
        ["Can't this wait? I'm trying to tend to these soldiers. {{Audio button|Nurse - Can't this wait.ogg}}"] = "¿Esto no puede esperar? Estoy tratando de atender a estos soldados. {{Audio button|Nurse - Can't this wait.ogg}}",
        ["These leeches won’t distribute themselves, you know. {{Audio button|Nurse - These leeches won't distribute themselves.ogg}}"] = "Estas sanguijuelas no se distribuyen solas, ¿sabes? {{Audio button|Nurse - These leeches won't distribute themselves.ogg}}",
        ["Sorry, I'll leave you to it."] = "Lo siento, te dejo con eso.",
        ["Did you know there is a wounded soldier up by Death Plateau?"] = "¿Sabías que hay un wounded soldier en Death Plateau?",
        ["No, I didn't. I'll send a stretcher team out right away. {{Audio button|Nurse - No, I didn't.ogg}}"] = "No, no lo hice. Enviaré un equipo de camillas ahora mismo. {{Audio button|Nurse - No, I didn't.ogg}}",
        ["Great, I'm sure he'll be in good hands now."] = "Genial, estoy seguro de que ahora estará en buenas manos.",
    },
}

dialogues.all = {
    ["You seem to like playing with danger, there."] = "Parece que te gusta jugar con el peligro.",
    ["They don't call me 'No-fingers' for nothing!"] = "¡No me llaman 'Sin dedos' por nada!",
    ["Well, correct me if I'm wrong, but you seem to have all your fingers."] = "Bueno, corrígeme si me equivoco, pero parece que tienes todos los dedos.",
    ["It may seem that way, but I think you'll find I don't have any."] = "Puede que lo parezca, pero creo que descubrirás que no tengo ninguno.",
    ["What?"] = "¿Qué?",
    ["These not be fingers. These 'ere be wooden fingers."] = "Estos no son dedos. Estos son dedos de madera.",
    ["Wooden fingers?"] = "¿Dedos de madera?",
    ["Yep."] = "Sí.",
    ["That's not possible, how could you move them?"] = "Eso no es posible, ¿cómo podrías moverlos?",
    ["Magic wood."] = "Magic madera.",
    ["Yes, well I think I'd better be going now."] = "Sí, bueno, creo que será mejor que me vaya ahora.",
    ["Hi."] = "Hola.",
    ["Don't suppose you've seen any boots around here? Size nine, steel toed, brown leather..."] = "¿No habrás visto botas por aquí? Talla nueve, puntera de acero, cuero marrón...",
    ["Nope, not at all. I'd best be going. Have a nice day. Bye!"] = "No, en absoluto. Será mejor que me vaya. Que tenga un lindo día. ¡Adiós!",
    ["Telepathically speak with a selection of useful NPCs."] = "Habla telepáticamente con una selección de NPC útiles.",
    ["Hello?"] = "¿Hola?",
    ["Huh, who's there?"] = "Eh, ¿quién está ahí?",
    ["It's Player. I'm using my magick to communicate to you. Don't worry."] = "Soy Player. Estoy usando mi magia para comunicarme contigo. No te preocupes.",
    ["I figured, seeing as I can see you over there! I don't make deals like this."] = "¡Me lo imaginé, ya que puedo verte allí! No hago tratos como este.",
    ["The sooner you get out of my head the better. So, you here for the...information?"] = "Cuanto antes salgas de mi cabeza, mejor. Entonces, ¿estás aquí por... información?",
    ["The information?"] = "¿La información?",
    ["Look pal, you interrupted me for a reason, you must be after something."] = "Mira amigo, me interrumpiste por una razón, debes estar buscando algo.",
    ["Select an option."] = "Seleccione una opción.",
    ["How much time till the next game of Trouble Brewing starts?"] = "¿Cuánto falta para que comience el próximo juego de Trouble Brewing?",
    ["Ah, that's information I can help yer with."] = "Ah, esa es información con la que puedo ayudarte.",
    ["A game is ready to start just as soon as there are enough people."] = "Un juego está listo para comenzar tan pronto como haya suficientes personas.",
    ["And how many people are there?"] = "¿Y cuántas personas hay?",
    ["There are X people on Dan's team, and Y on San's. There needs to be three on each in order for a game to start."] = "Hay X personas en el equipo de Dan e Y en el de San. Es necesario que haya tres en cada uno para que comience el juego.",
    ["Oh, okay. Thanks."] = "Oh, está bien. Gracias.",
    ["Anything else?"] = "¿Algo más?",
    ["How many people are waiting for a game to start?"] = "¿Cuántas personas están esperando que comience un juego?",
    ["No one's waiting at the moment. Perhaps you can get some people interested."] = "Nadie está esperando en este momento. Quizás puedas interesar a algunas personas.",
    ["Hmmm...maybe."] = "Mmmm... tal vez.",
    ["I have no idea what you're talking about."] = "No tengo idea de qué estás hablando.",
    ["I have no idea what you are talking about."] = "No tengo idea de qué estás hablando.",
    ["Then sling yer 'ook!"] = "¡Entonces tira el gancho!",
    ["Hi there, Bert."] = "Hola, Bert.",
    ["Huh? What tha' doin' in marn 'ed?"] = "¿Eh? ¿Qué haces en Marn 'ed?",
    ["This is the voice of your conscience. Hand all your money to Player! Wooo wooo!"] = "Esta es la voz de tu conciencia. ¡Entrega todo tu dinero a Player! ¡Guau, guau!",
    ["Be away wit' ya!"] = "¡Aléjate de ti!",
    ["Just kidding, I'm using magic to talk to you. I'm totally 'armless."] = "Es broma, estoy usando magia para hablar contigo. Estoy totalmente \"sin brazos\".",
    ["Oh ar. Hey, then why ya standon' so close? Speak in person please!"] = "Oh, amigo. Oye, entonces ¿por qué estás tan cerca? ¡Habla en persona por favor!",
    ["Oh ar. So wha' do thee want?"] = "Oh, amigo. Entonces, ¿qué quieres?",
    ["Could you hand some sand into my bank?"] = "¿Podrías pasarme un poco de arena a mi banco?",
    ["Ah, keep yer 'air on, I'll leg I' to tha bank wit' some sand fer ya."] = "Ah, mantén el aire encendido, iré al banco con un poco de arena para ti.",
    ["Thanks!"] = "¡Gracias!",
    ["I be a wee bi' busy to 'elp wit' yon sand, come back tomorra."] = "Estaré un poquito ocupado para \"ayudar con\" esa arena, vuelvo mañana.",
    ["Okay, Bert, I'll come back for my sand a bit later on."] = "Está bien, Bert, volveré por mi arena un poco más tarde.",
    ["Good day, Ghrim!"] = "¡Buenos días, Ghrim!",
    ["What? Who is this?"] = "¿Qué? ¿Quién es?",
    ["Aha, you've gone crazy, Ghrim. I am your alternate personality...Ghrom!"] = "Ajá, te has vuelto loco, Ghrim. Soy tu personalidad alternativa... ¡Ghrom!",
    ["Very amusing, your Royal Highness. I can see you talking."] = "Muy divertido, Su Alteza Real. Puedo verte hablando.",
    ["Oops."] = "Ups.",
    ["Is that you, your Royal Highness?"] = "¿Es usted, su Alteza Real?",
    ["Er...yes, it is. I'm using magic to communicate with you."] = "Er... sí, lo es. Estoy usando magia para comunicarme contigo.",
    ["Very amusing, your Royal Highness. How may I help you?"] = "Muy divertido, Su Alteza Real. ¿Cómo puedo ayudarte?",
    ["Select an option"] = "Seleccione una opción",
    ["How is the kingdom faring?"] = "¿Cómo le va al reino?",
    ["How do I manage the kingdom?"] = "¿Cómo administro el reino?",
    ["About the task System:..."] = "Acerca de la tarea Sistema:...",
    ["That's all, thanks."] = "Eso es todo, gracias.",
    ["Very well, your Royal Highness. If you have any further problems, pleas talk to me in person."] = "Muy bien, Su Alteza Real. Si tiene más problemas, por favor hable conmigo en persona.",
    ["Ello, who's that?"] = "Hola, ¿quién es ese?",
    ["I'm Player. I'm using magic to communicate with you."] = "Soy Player. Estoy usando magia para comunicarme contigo.",
    ["Bizarre. Go on then, what do you want?"] = "Extraño. Anda entonces, ¿qué quieres?",
    ["Choose an option:"] = "Elige una opción:",
    ["I need to talk to you about Lucien."] = "Necesito hablar contigo sobre Lucien.",
    ["I need to talk to you about Lucien!"] = "¡Necesito hablarte sobre Lucien!",
    ["Oh, yes, and what about Lucien? I haven't heard that name in a while."] = "Ah, sí, ¿y qué pasa con Lucien? Hace tiempo que no escucho ese nombre.",
    ["He's growing in power and we need to apprehend him. Would you be interested in joining a small party tasked with doing so?"] = "Su poder está creciendo y debemos detenerlo. ¿Estaría interesado en unirse a un pequeño grupo encargado de hacerlo?",
    ["I've spent the last few years telling amateurs to kill goblins. Excitement and danger sounds like just the ticket before I quit the job forever."] = "He pasado los últimos años diciéndoles a los aficionados que maten duendes. La emoción y el peligro suenan como el boleto antes de dejar el trabajo para siempre.",
    ["Great news Turael, many thanks!"] = "¡Buenas noticias Turael, muchas gracias!",
    ["Ask about something else"] = "pregunta sobre otra cosa",
    ["I need another assignment."] = "Necesito otra tarea.",
    ["You're still hunting [assigned creature]; come back when you've finished your task."] = "Todavía estás cazando a [assigned creature]; Vuelve cuando hayas terminado tu tarea.",
    ["Er... Nothing..."] = "Er... Nada...",
    ["You seem very forgetful, really. You have already recruited me, there's no point trying again."] = "Pareces muy olvidadizo, de verdad. Ya me has reclutado, no tiene sentido volver a intentarlo.",
    ["Well, please don't. If you want to talk to me, do it face to face. I can see you, you know."] = "Bueno, por favor no lo hagas. Si quieres hablar conmigo, hazlo cara a cara. Puedo verte, ¿sabes?",
    ["I'm Player. I'm using my magic to communicate with you."] = "Soy Player. Estoy usando mi magia para comunicarme contigo.",
    ["Er...nothing."] = "Eh... nada.",
    ["Hello, Lanthus"] = "Hola, Lanthus",
    ["Huh?"] = "¿Eh?",
    ["Be not afraid! I am the all mighty god of all! Bow down before your creator!"] = "¡No tengas miedo! ¡Soy el dios todopoderoso de todos! ¡Inclínate ante tu creador!",
    ["No you're not. You're standing over there. Leave me alone!"] = "No, no lo eres. Estás parado allí. ¡Déjame en paz!",
    ["Okay, Okay; I'm bowing, I'm bowing. Just don't h-h-hurt me!"] = "Está bien, está bien; Me inclino, me inclino. ¡Sólo no me hagas daño!",
    ["Are you listening to me, Lanthus?"] = "¿Me estás escuchando, Lanthus?",
    ["I...I am. How may I h-h-help you?"] = "Yo... lo soy. ¿Cómo puedo ayudarte?",
    ["How long until another game starts?"] = "¿Cuánto falta para que comience otro juego?",
    ["The n-next game starts in X minute[s]. Sir."] = "El n-siguiente juego comienza en X minuto[s]. Señor.",
    ["Very well."] = "Muy bien.",
    ["But why do you want to know that?"] = "¿Pero por qué quieres saber eso?",
    ["Silence!"] = "¡Silencio!",
    ["How many people are waiting in each room?"] = "¿Cuántas personas hay esperando en cada sala?",
    ["There's no one in the Zamorak room,"] = "No hay nadie en la sala Zamorak,",
    ["and there's no one in the Saradomin room."] = "y no hay nadie en la sala Saradomin.",
    ["That is all. Now keep out of trouble."] = "Eso es todo. Ahora no te metas en problemas.",
    ["Y-yes."] = "S-sí.",
    ["I'm watching you, Lanthus."] = "Te estoy observando, Lanthus.",
    ["Ello, Player."] = "Hola, Player.",
    ["I'm using magic to communicate with you."] = "Estoy usando magia para comunicarme contigo.",
    ["Er..Nothing."] = "Er... Nada.",
    ["Hello there"] = "Hola",
    ["What the...?"] = "¿Qué...?",
    ["Don't worry, Murphy. My name's Player and I'm using magic to contact you!"] = "No te preocupes, Murphy. ¡Mi nombre es Player y estoy usando magia para contactarte!",
    ["That's so rude when you may as well just speak to me in person!"] = "¡Eso es tan grosero cuando podrías hablar conmigo en persona!",
    ["Well I never! Technology these days. It's beyond me. So how might I help you?"] = "¡Pues yo nunca! Tecnología en estos días. Está más allá de mí. Entonces, ¿cómo puedo ayudarte?",
    ["I was just wondering if there was anyone down there helping you out on the trawler?"] = "Me preguntaba si había alguien ahí abajo ayudándote en el barco pesquero.",
    ["The boat has just left, actually! Perhaps, when it comes back, you can join them on another run?"] = "¡El barco acaba de zarpar, de hecho! ¿Quizás, cuando regrese, puedas unirte a ellos en otra carrera?",
    ["Sounds like a plan."] = "Suena como un plan.",
    ["The boat is just sitting there, waiting for someone to join. How about it?"] = "El barco está ahí, esperando a que alguien se una. ¿Qué tal?",
    ["Maybe I'll come have a look. I'll catch you later."] = "Tal vez vaya a echar un vistazo. Te veré más tarde.",
    ["Okay, mate. Bye!"] = "Está bien, amigo. ¡Adiós!",
    ["Hello mate. What are you up to now?"] = "Hola amigo. ¿Qué estás haciendo ahora?",
    ["Erm, I'm a bit busy at the moment."] = "Erm, estoy un poco ocupado en este momento.",
    ["Oooh, I bet you're travelling the seas. Or maybe you're visiting world leaders?"] = "Oooh, apuesto a que estás viajando por los mares. ¿O tal vez estás visitando a líderes mundiales?",
    ["Well, I'm trying to fight TzTok-Jad at the moment."] = "Bueno, estoy intentando luchar contra TzTok-Jad en este momento.",
    ["He must be really tough!"] = "¡Debe ser muy duro!",
    ["Yes, he's got a combat level of 702."] = "Sí, tiene un nivel de combate de 702.",
    ["Enjoy!"] = "¡Disfruta!",
    ["Thanks. Arghhhh, death to you, foul beast!"] = "Gracias. ¡Arghhhh, muerte para ti, bestia asquerosa!",
    ["Hello!"] = "¡Hola!",
    ["Oh, hi."] = "Oh, hola.",
    ["What adventure are you now on?"] = "¿En qué aventura estás ahora?",
    ["Well, I just dispatched TzTok-Jad. Pretty tough! I'm now on my way to the desert. I'm going to see if I can hunt down this Kalphite Queen everyone's been telling me about."] = "Bueno, acabo de enviar a TzTok-Jad. ¡Bastante duro! Ahora estoy de camino al desierto. Voy a ver si puedo localizar a ese Kalphite Queen del que todo el mundo me habla.",
    ["I should warn you, you'll need a team to take that beast on."] = "Debo advertirte que necesitarás un equipo para enfrentarte a esa bestia.",
    ["I've already thought of that. I've arranged for a couple of the slayer masters to join me."] = "Ya he pensado en eso. He hecho arreglos para que un par de slayer masters se unan a mí.",
    ["Wow! I wish I could witness that!"] = "¡Guau! ¡Ojalá pudiera presenciar eso!",
    ["Hello again!"] = "¡Hola de nuevo!",
    ["That's funny, I was just talking about you."] = "Qué gracioso, justo estaba hablando de ti.",
    ["You were?"] = "¿Lo estabas?",
    ["Yes, I've been arranging various leaders of Runescape to discuss some political issues. It seems you've certainly been around a bit!"] = "Sí, he estado organizando a varios líderes de Runescape para discutir algunos temas políticos. ¡Parece que ya llevas un tiempo por aquí!",
    ["I suppose I have. What issues are you suppose to discuss in this meeting? Who will be there?"] = "Supongo que sí. ¿Qué temas se supone que debes discutir en esta reunión? ¿Quién estará allí?",
    ["Sorry, that's top secret information."] = "Lo siento, esa es información ultrasecreta.",
    ["That's fine, I understand."] = "Está bien, lo entiendo.",
    ["Hi there, where are you now?"] = "Hola, ¿dónde estás ahora?",
    ["I am in the Clan Wars free-for-all arena: the one with the pretty red portal. I'm meeting lots of interesting people."] = "Estoy en la arena de Guerras de clanes todos contra todos: la que tiene el bonito portal rojo. Estoy conociendo a mucha gente interesante.",
    ["Oh? That's a funny place to meet people."] = "¿Ah? Es un lugar divertido para conocer gente.",
    ["Well, I thought that too, but this guy told me to bring all my most valuable items and follow him in there to meet his friends."] = "Bueno, yo también pensé eso, pero este tipo me dijo que trajera todos mis artículos más valiosos y lo siguiera hasta allí para encontrarse con sus amigos.",
    ["Um, Cyrisus, aren't you afraid that they might kill you so that you lose all your stuff?"] = "Um, Cyrisus, ¿no tienes miedo de que te maten y pierdas todas tus cosas?",
    ["Oh yes, they did try that. So I killed all of them instead. But it was very nice to meet them anyway."] = "Oh, sí, lo intentaron. Así que los maté a todos. Pero fue muy agradable conocerlos de todos modos.",
    ["I guess you're fine."] = "Supongo que estás bien.",
    ["Hey. How's it going?"] = "Hola. ¿Cómo estás?",
    ["Summoning, summoning and more summoning!"] = "Summoning, invocaciones y más invocaciones!",
    ["Really? Nice one. So what's your choice of a pet at the moment?"] = "¿En serio? Bonita. Entonces, ¿cuál es tu elección de mascota en este momento?",
    ["Dragon!"] = "¡Dragón!",
    ["No way! I'm so jealous."] = "¡De ninguna manera! Estoy tan celoso.",
    ["It's certainly taken a lot of hard work, but it's very much worthwhile!"] = "Ciertamente ha requerido mucho trabajo duro, ¡pero vale la pena!",
    ["I'll bet!"] = "¡Apuesto!",
    ["Player? Do you wish me to re-enchant crystal teleport seeds for you?"] = "¿Player? ¿Quieres que te vuelva a encantar las semillas de teletransporte de cristal?",
    ["I haven't got any of those."] = "No tengo ninguno de esos.",
    ["Perhaps another time."] = "Quizás en otro momento.",
    ["Hello there."] = "Hola.",
    ["Greetings, voice in my head."] = "Saludos, voz en mi cabeza.",
    ["I wanted to talk to you about the penguin spies all over the world."] = "Quería hablarte sobre los pingüinos espías en todo el mundo.",
    ["What about them?"] = "¿Qué pasa con ellos?",
    ["I've found more penguins."] = "He encontrado más pingüinos.",
    ["More? Hmm, interesting. How many have you found?"] = "¿Más? Mmmm, interesante. ¿Cuántos has encontrado?",
    ["I've found X penguin[s] this week."] = "Encontré a X penguin[s] esta semana.",
    ["I'm having trouble finding the penguins. Can I have a hint?"] = "Tengo problemas para encontrar los pingüinos. ¿Puedo tener una pista?",
    ["I've heard there's a penguin located around a village between a great tower and a vampyre's manor."] = "He oído que hay un pingüino ubicado alrededor de un pueblo entre una gran torre y la mansión de vampyre.",
    ["I've heard there's a penguin located around Ardougne"] = "He oído que hay un pingüino ubicado alrededor de Ardougne.",
    ["I've heard there's a penguin located around Feldip Hills, near Gu'Tanoth"] = "He oído que hay un pingüino ubicado alrededor de Feldip Hills, cerca de Gu'Tanoth.",
    ["I've heard there's a penguin located around the Al Kharid region, north of Shantay Pass"] = "He oído que hay un pingüino ubicado alrededor de la región Al Kharid, al norte del paso Shantay.",
    ["I've heard there's a penguin located around the Ice Mountain region"] = "He oído que hay un pingüino ubicado alrededor de la región de Ice Mountain.",
    ["I've heard there's a penguin located between the Fremenniks and the Barbarians"] = "He oído que hay un pingüino ubicado entre los Fremenniks y los Bárbaros.",
    ["I've heard there's a penguin located deep in the jungle"] = "He oído que hay un pingüino ubicado en lo profundo de la jungla.",
    ["I've heard there's a penguin located east of the Mage Training Arena"] = "He oído que hay un pingüino ubicado al este del Mage Training Arena.",
    ["I've heard there's a penguin located in a city of plagues within the desert"] = "He oído que hay un pingüino ubicado en una ciudad de plagas dentro del desierto.",
    ["I've heard there's a penguin located in a town of druids"] = "He oído que hay un pingüino ubicado en un pueblo de druidas.",
    ["I've heard there's a penguin located in or around Falador"] = "He oído que hay un pingüino ubicado en Falador o sus alrededores.",
    ["I've heard there's a penguin located in the east of the kingdom of Kandarin"] = "He oído que hay un pingüino ubicado al este del reino de Kandarin.",
    ["I've heard there's a penguin located in the fairy realm"] = "He oído que hay un pingüino ubicado en el reino de las hadas.",
    ["I've heard there's a penguin located in the frozen wastes"] = "He oído que hay un pingüino ubicado en los páramos helados.",
    ["I've heard there's a penguin located in the north of the Kharidian desert"] = "He oído que hay un pingüino ubicado en el norte de Kharidian desert.",
    ["I've heard there's a penguin located in the north of the kingdom of Misthalin"] = "He oído que hay un pingüino ubicado en el norte del reino de Misthalin.",
    ["I've heard there's a penguin located in the south of the Kharidian desert"] = "He oído que hay un pingüino ubicado en el sur de Kharidian desert.",
    ["I've heard there's a penguin located in the south of the kingdom of Misthalin"] = "He oído que hay un pingüino ubicado en el sur del reino de Misthalin.",
    ["I've heard there's a penguin located in the west of the kingdom of Kandarin"] = "He oído que hay un pingüino ubicado en el oeste del reino de Kandarin.",
    ["I've heard there's a penguin located in the wilderness"] = "He oído que hay un pingüino ubicado en wilderness.",
    ["I've heard there's a penguin located near a big tree surrounded by short people"] = "He oído que hay un pingüino ubicado cerca de un gran árbol rodeado de gente baja.",
    ["I've heard there's a penguin located near a mountain of wolves"] = "He oído que hay un pingüino ubicado cerca de una montaña de lobos.",
    ["I've heard there's a penguin located near a tainted swamp"] = "He oído que hay un pingüino ubicado cerca de un pantano contaminado.",
    ["I've heard there's a penguin located near a town of werewolves"] = "He oído que hay un pingüino ubicado cerca de un pueblo de hombres lobo.",
    ["I've heard there's a penguin located near Port Sarim"] = "He oído que hay un pingüino ubicado cerca de Port Sarim.",
    ["I've heard there's a penguin located near some ogres in South Feldip Hills"] = "He oído que hay un pingüino ubicado cerca de unos ogros en South Feldip Hills.",
    ["I've heard there's a penguin located near the Barbarian Outpost"] = "He oído que hay un pingüino ubicado cerca del Puesto Bárbaro.",
    ["I've heard there's a penguin located near the bees and flax"] = "He oído que hay un pingüino ubicado cerca de las abejas y el lino.",
    ["I've heard there's a penguin located near the Castle of Arthur"] = "He oído que hay un pingüino ubicado cerca del Castillo de Arturo.",
    ["I've heard there's a penguin located near the city of ghosts"] = "He oído que hay un pingüino ubicado cerca de la ciudad de los fantasmas.",
    ["I've heard there's a penguin located near the coast, east of Ardougne"] = "He oído que hay un pingüino ubicado cerca de la costa, al este de Ardougne.",
    ["I've heard there's a penguin located near the island of Dragontooth"] = "He oído que hay un pingüino ubicado cerca de la isla de Dragontooth.",
    ["I've heard there's a penguin located near the mudskippers"] = "He oído que hay un pingüino ubicado cerca de los saltamontes.",
