    ["Ello, who's this?"] = "Hola, ¿quién es?",
    ["It's Player. I'm using my magic to communicate with you."] = "Soy Player. Estoy usando mi magia para comunicarme contigo.",
    ["What a waste of runes. I can see you, you know. Let's talk face to face."] = "Qué desperdicio de runas. Puedo verte, ¿sabes? Hablemos cara a cara.",
    ["A useful application of magical talent. How can I help?"] = "Una aplicación útil del talento mágico. ¿Cómo puedo ayudar?",
    ["What is this?! You must not break my concentration!"] = "¡¿Qué es esto?! ¡No debes romper mi concentración!",
    ["What a waste of runes! - I can see you, lets talk face to face."] = "¡Qué desperdicio de runas! - Puedo verte, hablemos cara a cara.",
    ["Are you trying to collapse the Abyss? What do you want? Speak quickly!"] = "¿Estás intentando colapsar el Abismo? ¿Qué deseas? ¡Habla rápido!",
    ["Actually, I can't think of anything right now..."] = "En realidad, no se me ocurre nada en este momento...",
    ["THEN STOP DISTRACTING ME!"] = "¡ENTONCES DEJA DE DISTRAERME!",
    ["Honestly, you have no idea of the pressure I am under attempting to keep this portal open!"] = "Honestamente, ¡no tienes idea de la presión que estoy bajo al intentar mantener este portal abierto!",
    ["Sorry to disturb you. I just needed your help with something quickly."] = "Lamento molestarte. Solo necesitaba tu ayuda con algo rápido.",
    ["What? Oh... Very well. what did you want?"] = "¿Qué? Ah... Muy bien. ¿Qué querías?",
    ["Chose an option:"] = "Elige una opción:",
    ["Can I have another Abyssal book?"] = "¿Puedo tener otro libro de Abyssal?",
    ["Can I have another Abyssal book? I seem to have misplaced the one I was given."] = "¿Puedo tener otro libro de Abyssal? Parece que perdí el que me dieron.",
    ["Here, take it, it is important to pool our research. Now leave me be, I must concentrate!"] = "Toma, tómatelo, es importante aunar nuestra investigación. ¡Ahora déjame en paz, debo concentrarme!",
    ["Ahh, a familiar voice in my head!"] = "¡Ahh, una voz familiar en mi cabeza!",
    ["So, where's Pikkenmix?"] = "Entonces, ¿dónde está Pikkenmix?",
    ["What's it all about?"] = "¿De qué se trata?",
    ["Hi Pauline!"] = "¡Hola Paulina!",
    ["Bah! You made me jump! I suppose you want to claim some reward wishes?"] = "¡Bah! ¡Me hiciste saltar! ¿Supongo que quieres reclamar algunos deseos de recompensa?",
    ["Yes please."] = "Sí, por favor.",
    ["What? Ah, very bright of you contacting me this way."] = "¿Qué? Ah, muy brillante que me contactes de esta manera.",
    ["Yeah, thought I'd make use of the new spell to ask a question."] = "Sí, pensé en utilizar el nuevo hechizo para hacer una pregunta.",
    ["Can you change my spell book back to the standard one?"] = "¿Puedes cambiar mi libro de hechizos al estándar?",
    ["Hmmm, no I think you need to prove yourself a bit more first."] = "Hmmm, no, creo que primero debes demostrar tu valía un poco más.",
    ["If you complete the elite achievement diary tasks the Oneiromancer will help you."] = "Si completas las tareas del diario de logros de élite, Oneiromancer te ayudará.",
    ["Certainly..."] = "Ciertamente...",
    ["There!"] = "¡Ahí!",
    ["Can I tell you a joke?"] = "¿Puedo contarte un chiste?",
    ["Oh, I do like jokes, go ahead."] = "Oh, me gustan las bromas, adelante.",
    ["What do you call a crazy moon?"] = "¿Cómo se llama una luna loca?",
    ["A crazy moon... Hmm, I don't know. What?"] = "Una luna loca... Hmm, no lo sé. ¿Qué?",
    ["A luna-tic!"] = "¡Un lunático!",
    ["Ahahahaha!"] = "¡Jajajajaja!",
    ["Hahaa!"] = "¡Jajaa!",
    ["Hahahaha!"] = "¡Jajajaja!",
    ["Okay, okay. It wasn't THAT funny."] = "Está bien, está bien. No fue TAN gracioso.",
    ["Mieliki sent Nyriki to a swamp, south-east of Canifis."] = "Mieliki envió a Nyriki a un pantano, al sureste de Canifis.",
    ["What would you like to say?"] = "¿Qué te gustaría decir?",
    ["Who are you?"] = "¿Quién eres?",
    ["Mieliki is an alchemist. Mieliki's stupid husband Nyriki hunts for giant chinchompas to get chemicals for Mieliki."] = "Mieliki es un alquimista. El estúpido marido de Mieliki, Nyriki, busca chinchompas gigantes para conseguir productos químicos para Mieliki.",
    ["Nyriki needs human help because he is stupid. Use Mieliki portal, in this shop, to go to him now."] = "Nyriki necesita ayuda humana porque es estúpido. Utilice el portal Mieliki, en esta tienda, para acudir a él ahora.",
    ["Can you teleport me?"] = "¿Puedes teletransportarme?",
    ["Mieliki is working! Use the portal."] = "¡Mieliki está trabajando! Utilice el portal.",
    ["Mieliki is working! Come to Mieliki's shop in the Gnome Stronghold and use the portal."] = "¡Mieliki está trabajando! Ven a la tienda de Mieliki en Gnome Stronghold y utiliza el portal.",
    ["Thanks."] = "Gracias.",
    ["Very well, human. Work hard."] = "Muy bien, humano. Atarearse.",
    ["If you're going to bother me with your prattle, you could at least have the decency to do it to my face. Get over here."] = "Si vas a molestarme con tu parloteo, al menos podrías tener la decencia de hacerlo en mi cara. Ven aquí.",
    ["You have no business in my head. My secrets are not for your eyes. Get out."] = "No tienes nada que hacer en mi cabeza. Mis secretos no son para tus ojos. Salir.",
    ["Too scared to seek me out in person, hmm? Well, what is it?"] = "Tienes demasiado miedo para buscarme en persona, ¿eh? Bueno, ¿qué es?",
    ["Why would you waste the runes to contact me when you're standing so close?"] = "¿Por qué desperdiciarías las runas para contactarme cuando estás tan cerca?",
    ["You have no business in my head. My thoughts are my own."] = "No tienes nada que hacer en mi cabeza. Mis pensamientos son míos.",
    ["That's a shame. It'd have been nice to see you. Well, what is it?"] = "Es una pena. Hubiera sido bueno verte. Bueno, ¿qué es?",
    ["Ugh, another one."] = "Uf, otro.",
    ["Oh nothing. What can I help with?"] = "Oh, nada. ¿En qué puedo ayudar?",
    ["Oh, well, someone said something about some druids in the desert, and rather than go there I figured I'd see what was going on first."] = "Oh, bueno, alguien dijo algo sobre unos druidas en el desierto, y en lugar de ir allí pensé en ver qué estaba pasando primero.",
    ["Look, if you want to help, maybe come and have a chat rather than pushing your way into my head."] = "Mira, si quieres ayudar, tal vez vengas y conversemos en lugar de meterte en mi cabeza.",
    ["Well I did-"] = "Bueno, lo hice-",
    ["Good day!"] = "¡Buenos días!",
    ["Helloooo?"] = "¿Holaaaa?",
    ["There is no one there but the cold, dark void of your own mind."] = "No hay nadie allí excepto el vacío frío y oscuro de tu propia mente.",
    ["Hello, Polletix?"] = "Hola, ¿Polletix?",
    ["What are you doing?"] = "¿Qué estás haciendo?",
    ["Well I was jus-"] = "Bueno, solo estaba-",
    ["I can see you. You're right here."] = "Puedo verte. Estás justo aquí.",
    ["Oh, I-"] = "Oh, yo-",
    ["Now, if you want to talk I suggest you come and do so in person, rather than this misuse of magic."] = "Ahora, si quieres hablar te sugiero que vengas y lo hagas en persona, en lugar de este mal uso de la magia.",
    ["Hello adventurer. This is a nifty little trick. How can I help?"] = "Hola aventurero. Este es un pequeño truco ingenioso. ¿Cómo puedo ayudar?",
    ["I was just wondering what herb you wanted planted today?"] = "Me preguntaba qué hierba querías plantar hoy.",
    ["Oh, today I'd like you to plant and harvest: [Herb type] seed."] = "Oh, hoy me gustaría que plantes y coseches: semilla [Herb type].",
    ["Great, thanks!"] = "¡Genial, gracias!",
    ["Hello? is this the Raptor?"] = "¿Hola? ¿Es este the Raptor?",
