    ["**The Raptor** Explain yourself."] = "**The Raptor** Explícate.",
    ["Huh? Okay."] = "¿Eh? Bueno.",
    ["Baa, baaaa, BAA!"] = "¡Baa, baaaa, BAA!",
    ["Baaa?"] = "¿Baaa?",
