    ["Whoa! A voice in my head! What do you want?"] = "¡Vaya! ¡Una voz en mi cabeza! ¿Qué deseas?",
    ["I am your evil master!"] = "¡Soy tu malvado maestro!",
    ["You're using dark magic to contact me! That is SO evil! What is thy bidding, O Master?"] = "¡Estás usando magia oscura para contactarme! ¡Eso es TAN malvado! ¿Cuál es tu orden, oh Maestro?",
    ["Build me an army worthy of Zamorak!"] = "¡Constrúyeme un ejército digno de Zamorak!",
    ["Yes, O master! As soon as I get this summoning thing to work, my army of evil UNDEAD CHAOS ZOMBIE DEMON ASSASSINS OF DARKNESS will overrun the world! Mwuhahahahaaa!"] = "¡Sí, oh maestro! ¡Tan pronto como haga funcionar esta cosa de invocación, mi ejército de malvados UNDEAD CHAOS ZOMBIE DEMON ASSASSINS OF DARKNESS OF DARKNESS invadirá el mundo! ¡Mwuhahahahaaa!",
    ["Error! Perception mismatch (auditory/visual)."] = "¡Error! Desajuste de percepción (auditiva/visual).",
    ["Don't worry, Golem! It's Player!"] = "¡No te preocupes, Golem! ¡Es Player!",
    ["I am sorry. I can hear you but not see you. I will have to examine my eyes."] = "Lo siento. Puedo oírte pero no verte. Tendré que examinarme los ojos.",
    ["No, you can't see me because I'm not there. I'm contacting you by magic!"] = "No, no puedes verme porque no estoy allí. ¡Me estoy contactando contigo por arte de magia!",
    ["If you are not here then I cannot be hearing you. I will have to examine my ears."] = "Si no estás aquí, entonces no puedo escucharte. Tendré que examinarme los oídos.",
    ["Don't worry about it, Golem."] = "No te preocupes, Golem.",
    ["What you want, Bentnoze?"] = "¿Qué quieres, Bentnoze?",
